const formatJpPhone = (s) => {
  // ★ 全角数字(０-９)も受け付ける (iPad等で全角入力されると従来はすべて除去され消えていた)
  const half = String(s ?? '').replace(/[０-９]/g, c => String.fromCharCode(c.charCodeAt(0) - 0xFEE0));
  const digits = half.replace(/[^0-9]/g, '');
  if (!digits) return '';
  // 携帯 (090/080/070) と IP (050) → 3-4-4
  if (/^(090|080|070|050)/.test(digits)) {
    if (digits.length <= 3) return digits;
    if (digits.length <= 7) return `${digits.slice(0,3)}-${digits.slice(3)}`;
    return `${digits.slice(0,3)}-${digits.slice(3,7)}-${digits.slice(7,11)}`;
  }
  // フリーダイヤル等 0120 → 4-3-3
  if (/^(0120|0800)/.test(digits)) {
    if (digits.length <= 4) return digits;
    if (digits.length <= 7) return `${digits.slice(0,4)}-${digits.slice(4)}`;
    return `${digits.slice(0,4)}-${digits.slice(4,7)}-${digits.slice(7,10)}`;
  }
  // 2桁市外 (03/06) → 2-4-4
  if (/^(03|06)/.test(digits)) {
    if (digits.length <= 2) return digits;
    if (digits.length <= 6) return `${digits.slice(0,2)}-${digits.slice(2)}`;
    return `${digits.slice(0,2)}-${digits.slice(2,6)}-${digits.slice(6,10)}`;
  }
  // その他 3桁市外 → 3-3-4
  if (digits.length <= 3) return digits;
  if (digits.length <= 6) return `${digits.slice(0,3)}-${digits.slice(3)}`;
  return `${digits.slice(0,3)}-${digits.slice(3,6)}-${digits.slice(6,10)}`;
};

// 郵便番号フォーマッタ: ハイフン無しの数字 → 3-4
const formatJpZip = (s) => {
  const digits = (s || '').replace(/[^0-9]/g, '').slice(0, 7);
  if (!digits) return '';
  if (digits.length <= 3) return digits;
  return `${digits.slice(0,3)}-${digits.slice(3)}`;
};

// 招待コード関連 (利用者ID 6桁 + チェックデジット 1桁 = 7桁)
// patientId (任意の正数) を 6桁ゼロパディングし、各桁の合計 mod 10 のチェックデジットを付与
const calcCheckDigit = (sixDigitStr) => {
  const sum = sixDigitStr.split('').reduce((s,c) => s + (parseInt(c,10)||0), 0);
  return String(sum % 10);
};
