const generateOneTimeInviteCode = () => {
  const part = (n) => Array.from({length:n}, () => _INV_CHARS[Math.floor(Math.random()*_INV_CHARS.length)]).join('');
  return `FAM-${part(4)}-${part(4)}`;
};

