// === 真っさらな新規店舗のための初期 AppData ===
// 店舗情報 (zip/address/phone/fax) を facilityInfo へ自動転記
// 運動メニューは初期空 (事業所ごとにユーザーが追加)
function createBlankAppData(storeRecord, staffSession) {
  const facility = {
    name: storeRecord?.name || staffSession?.storeName || '',
    short_name: storeRecord?.short_name || '',
    // ★ 各種設定は zipCode / addressBuilding を参照するため、その名前で転記する (以前は zip のみで反映されなかった)
    zip: storeRecord?.zip_code || '',
    zipCode: storeRecord?.zip_code || '',
    address: storeRecord?.address || '',
    addressBuilding: storeRecord?.address_building || '',
    phone: storeRecord?.phone || '',
    fax: storeRecord?.fax || '',
    email: storeRecord?.email || '',
    manager: '',
    closedDays: [],  // ★ 初期は定休日なし (ユーザーが設定で選ぶ)
    // ★ サービス提供時間 / 定員 / 責任者 は空欄でスタート
    serviceTimeAM: '',
    serviceTimePM: '',
    capacity: 0,
    serviceResponsible: '',
  };
  return {
    patients: [],
    ticketRecords: [],
    familyAnnouncements: [],
    familyPersonalAnnouncements: [],
    familyPhotos: [],
    faxHistory: [],
    monitoringRecords: [],
    fitnessRecords: [],
    dailyLogs: [],
    contactBooks: [],
    initialReports: [],
    kinouKeikakuRecords: [],
    tsushoKeikakuRecords: [],
    seikatsuKinouRecords: [],
    kyomiKanshinRecords: [],
    systemSettings: {
      facilityInfo: facility,
      // 運動メニュー: 初期は空 (事業所ごとに追加してもらう)
      exerciseItems: [],
      individualExerciseItems: [],
      massageStaff: [],
      // ★ サービス提供内容の項目管理: 初期は空 (介護整体含めユーザーが事業所単位で追加)
      serviceItems: [],
      massageTypes: ['通常','横向き','仰向け','うつ伏せ','座位','無し'],
      onyokuTypes: [],
      // ★ 体力測定 初期項目: 身長・体重のみ (全利用者で測る基本項目)
      fitnessItems: [
        { id: 'height', name: '身長', unit: 'cm', fixed: true },
        { id: 'weight', name: '体重', unit: 'kg', fixed: true },
      ],
      // ★ 体力測定 対象介護度 初期は未チェック (ユーザーが選ぶ)
      fitnessTargets: [],
      fiscalYearStart: 4,  // 4月開始 (一般的デフォルト)
      cmOffices: [],
      careManagers: [],
      announcementRetentionMonths: 24,
    },
    diarySettings: { staff: [], cars: [], scheduleAM: [], schedulePM: [] },
    storeMembers: [],
    holidays: [],
    monthlyShifts: {},
    workSchedule: {}, // ★ 勤務表: { 月キー(YYYY-MM): { スタッフキー(氏名|役職): { 日: 区分 } } }
    // 連絡帳設定の最小デフォルト (空配列だと crash しないように items: [] を保証)
    contactBookConfig: {
      facilityName: facility.name || '',
      facilityPhone: facility.phone || '',
      items: [],
    },
  };
}

