  const expiringPats = dPats.filter(p => isInsuranceExpiring(p));
  const kanaGroups = ['all', ...['あ','か','さ','た','な','は','ま','や','ら','わ'].filter(row => (appData.patients||[]).some(p => getRowFromKana(p.kana) === row))];
  const latPause = (p) => { if (!p.pauseHistory || !p.pauseHistory.length) return null; return [...p.pauseHistory].sort((a, b) => new Date(b.fromDate) - new Date(a.fromDate))[0]; };
  const fD = (s) => s ? s.replace(/-/g, '/') : '';
  const dBtw = (f, t) => { if (!f) return 0; const a = new Date(f); a.setHours(0, 0, 0, 0); const b = new Date(t || new Date()); b.setHours(0, 0, 0, 0); return Math.max(0, Math.ceil((b - a) / 86400000)); };
  const dTxt = (d) => { if (d >= 365) { const y = Math.floor(d / 365), m = Math.floor((d % 365) / 30); return m > 0 ? `${y}年${m}ヶ月` : `${y}年`; } if (d >= 30) return `${Math.floor(d / 30)}ヶ月`; return `${d}日`; };
  const subInfo = (p) => { const s = getPatientDisplayStatus(p); if (s === '利用中') { if (!p.startDate) return {}; return { text: dTxt(dBtw(p.startDate, new Date())), sub: '継続', color: 'text-emerald-600' }; } if (s === '休止') { const l = latPause(p); if (!l) return {}; return { text: `${fD(l.fromDate)}〜`, sub: `${dBtw(l.fromDate, new Date())}日間`, color: 'text-orange-600', reason: l.reason }; } if (s === '退所済み') { if (!p.endDate) return {}; return { text: fD(p.endDate), sub: `${dTxt(dBtw(p.endDate, new Date()))}経過`, color: 'text-slate-500' }; } return {}; };
  const mKey = `${currentMonth.getFullYear()}-${String(currentMonth.getMonth() + 1).padStart(2, '0')}`;
