const KK_STATUS = ['自立','見守り','一部介助','全介助'];
const KK_SHINSHIN = ['なし','軽度','中等度','重度'];
const SEIKATSU_ADL = ['食事','移乗','整容','トイレ動作','入浴','歩行','階段昇降','更衣','排便管理','排尿管理'];
const SEIKATSU_KIKYO = ['寝返り','起き上がり','座位保持','立ち上がり','立位保持'];
const SEIKATSU_IADL = ['調理','掃除','洗濯','買い物','交通機関の利用','服薬管理','金銭管理','電話の使用'];
const SEIKATSU_SHINSHIN = ['麻痺','関節拘縮','筋力低下','関節痛','バランス低下','嚥下障害','視力低下','聴力低下'];
const KYOMI_DEFAULT = ['自分でトイレに行く','一人でお風呂に入る','自分で服を着る','自分で食べる','歯磨きをする','身だしなみを整える','好きなときに眠る','掃除・整理整頓','料理を作る','買い物','散歩','友人とのおしゃべり','家族・親戚との団らん','趣味の活動','スポーツ','旅行・外出','庭いじり・園芸','読書','俳句・川柳','書道','絵を描く','写真','音楽を聴く','歌・カラオケ','楽器の演奏','将棋・囲碁・麻雀','編み物・手芸','針仕事','テレビ・映画','パソコン・スマホ','賃金を伴う仕事','ボランティア活動','地域の行事・活動','子や孫の世話','動物の世話','お参り・信仰'];

// === 個別機能訓練計画書 (アドオン: kinou_keikaku) ===
function KinouKeikakuView({ appData, onSave, dirtyRef, saveFnRef, onShowPrintPreview, navigateTo, targetPatientId }) {
  const markDirty = () => { if (dirtyRef) dirtyRef.current = true; };
  const patients = sortPatientsByKana((appData.patients||[]).filter(p => p.status==='利用中' || p.status==='休止'));
  const [pid, setPid] = React.useState((targetPatientId!=null && (appData.patients||[]).some(p=>p.id===targetPatientId)) ? targetPatientId : (patients[0]?.id ?? null));
  const [editing, setEditing] = React.useState(null); // 編集中レコード or null
  const patient = (appData.patients||[]).find(p => p.id === pid);
  const exItems = appData.systemSettings?.exerciseItems || [];
  const facility = appData.systemSettings?.facilityInfo || {};
  const records = (appData.kinouKeikakuRecords||[]).filter(r => r.patientId === pid)
    .sort((a,b) => (b.createdDate||'').localeCompare(a.createdDate||''));

  const _age = (bd) => { if(!bd) return ''; const d=new Date(bd), n=new Date(); let a=n.getFullYear()-d.getFullYear(); if(n.getMonth()<d.getMonth()||(n.getMonth()===d.getMonth()&&n.getDate()<d.getDate()))a--; return a; };
  const toReiwa = (iso) => { if(!iso) return ''; const d=new Date(iso); if(isNaN(d.getTime())) return iso; const r=d.getFullYear()-2018; return `令和${r}年${d.getMonth()+1}月${d.getDate()}日`; };
  const JIRITSU_BODY = ['自立','J1','J2','A1','A2','B1','B2','C1','C2'];
  const JIRITSU_DEM = ['自立','Ⅰ','Ⅱa','Ⅱb','Ⅲa','Ⅲb','Ⅳ','M'];
  // ★ 共通項目の連携: フェイスシートを正としてこの計画書へ取り込む(通所介護計画書と同じ考え方)。
  //   自立度は表記ゆれ(半角I/全角Ⅰ)を正規化して合わせる。
  const _kkFsAuto = (p) => {
    // ★ フェイスシートの保存先は patient.personalFile.faceSheet (patient.faceSheet は添付専用)。
    //   ここを取り違えると連携が丸ごと効かず、自立度が入らない/経緯に既往歴しか出ない等になる。
    const fs = (p?.personalFile?.faceSheet) || p?.faceSheet || {};
    const j = (...a) => a.filter(x => String(x||'').trim()).join('\n');
    return {
      jiritsuBody: normalizeAdlLevel(fs.adlLevel),
      jiritsuDementia: normalizeDemLevel(fs.dementiaLevel),
      honninKibou: j(fs.needs),
      shakaiSanka: j(fs.hobby && `趣味・楽しみ：${fs.hobby}`, fs.personality && `性格・人柄：${fs.personality}`, fs.otherServices && `他サービスの利用：${fs.otherServices}`),
      kyotakuKankyo: j(fs.floorPlan, fs.householdType && `世帯：${fs.householdType}${fs.householdTypeOther?`（${fs.householdTypeOther}）`:''}`),
      byomei: j((fs.kiou ?? p?.kiou)),
      gappei: j(fs.chronicDiseases && `主治医：${fs.chronicDiseases}`, fs.medication && `服薬：${fs.medication}`),
      ryuiPoint: j(p?.ryui, fs.allergies && `アレルギー：${fs.allergies}`),
    };
  };
  // フェイスシートから空欄のみ補完 (入力済みは上書きしない)
  const kkImportFromFaceSheet = () => {
    const a = _kkFsAuto(patient);
    const fill = Object.keys(a).filter(k => String(a[k]||'').trim() && !String(editing?.[k]||'').trim());
    if (!fill.length) { alert('フェイスシートから補完できる空欄がありませんでした。（入力済みの欄は上書きしません）'); return; }
    setEditing(e => { const ne={...e}; fill.forEach(k => { ne[k]=a[k]; }); return ne; });
    markDirty();
  };
  const blankProgram = () => ({ content:'', point:'', freqWeek:'', time:'', person:'機能訓練指導員' });
  const programsFromPlanned = () => {
    const pe = patient?.plannedExercises || {};
    const list = Object.entries(pe).filter(([k,v]) => v && v!=='ー' && String(v).trim()!=='')
      .map(([k,v]) => { const it = exItems.find(i=>i.id===k); const unit=it?.defaultUnit||''; const num=String(v).match(/[0-9０-９]/)?String(v):''; return { content:`${it?.name||k}（運動器機能の向上のために）`, point:'', freqWeek:'', time: num?`${v}${/分|回|往復/.test(String(v))?'':unit}`:String(v), person:'機能訓練指導員' }; });
    return list.length ? list : [blankProgram(),blankProgram()];
  };
  const newRecord = () => ({
    id: `kk_${pid}_${Date.now()}`, patientId: pid, createdAt: Date.now(),
    createdDate: toReiwa(new Date().toISOString().slice(0,10)), prevDate: '', firstDate: '',
    author: '', authorJob: '機能訓練指導員',
    // ★ 自立度・希望・社会参加・居宅環境・病名・留意事項はフェイスシートから自動取込
    ..._kkFsAuto(patient),
    kazokuKibou: '',
    hasshoDate: '', nyuinDate: '', taiinDate: '',
    chiryoKeika: '',
    shortKinou: '', shortKatsudo: '', shortSanka: '', shortAchieve: '',
    longKinou: '', longKatsudo: '', longSanka: '', longAchieve: '',
    programs: programsFromPlanned(), programPlanner: '',
    jikangaiJisshi: '', tokki: '',
    henka: '', kadai: '',
    setsumeiDate: '', setsumeisha: '',
  });

  const upd = (patch) => { setEditing(e => ({ ...e, ...patch })); markDirty(); };
  const updProg = (i, patch) => { setEditing(e => ({ ...e, programs: e.programs.map((p,idx)=> idx===i ? {...p,...patch} : p) })); markDirty(); };
  const addProg = () => { setEditing(e => ({ ...e, programs: [...e.programs, blankProgram()] })); markDirty(); };
  const delProg = (i) => { setEditing(e => ({ ...e, programs: e.programs.filter((_,idx)=>idx!==i) })); markDirty(); };

  // ★ close=true: 保存して一覧へ戻る / close=false: 一時保存(編集画面は開いたまま。 画面を戻る前に消えないよう取っておく)
  const saveRecord = (close=true) => {
    if (!editing) return;
    const list = [...(appData.kinouKeikakuRecords||[])];
    const idx = list.findIndex(r => r.id === editing.id);
    const rec = { ...editing, _savedAt: syncNow() };
    if (idx >= 0) list[idx] = rec; else list.push(rec);
    onSave({ ...appData, kinouKeikakuRecords: list }, { manual:true, message: close ? '✓ 個別機能訓練計画書を保存しました' : '✓ 一時保存しました' });
    if (dirtyRef) dirtyRef.current = false;
    if (close) setEditing(null);
    else setEditing(rec); // 保存済みレコードで編集を継続(以降は上書き保存)
  };
  React.useEffect(() => { if (!saveFnRef) return; saveFnRef.current = () => { if (editing) saveRecord(); }; });

  const delRecord = (id) => {
    if (!window.confirm('この計画書を削除します。よろしいですか？')) return;
    onSave({ ...appData, kinouKeikakuRecords: (appData.kinouKeikakuRecords||[]).filter(r=>r.id!==id) }, { manual:true, message:'削除しました' });
    if (editing?.id === id) setEditing(null);
  };
  const dupRecord = (r) => { setEditing({ ...r, id:`kk_${pid}_${Date.now()}`, createdAt:Date.now(), prevDate: r.createdDate||'', createdDate: toReiwa(new Date().toISOString().slice(0,10)), shortAchieve:'', longAchieve:'', henka:'', kadai:'', setsumeiDate:'', setsumeisha:'' }); };

  // ★ 計画書連携: この利用者の最新の 生活機能チェック / 興味・関心 レコードを取得
  const _latestBy = (arr) => (arr||[]).filter(r=>r.patientId===pid).sort((a,b)=>(b.recordDate||'').localeCompare(a.recordDate||'')||((b.createdAt||0)-(a.createdAt||0)))[0] || null;
  const latestSeikatsu = _latestBy(appData.seikatsuKinouRecords);
  const latestKyomi = _latestBy(appData.kyomiKanshinRecords);
  const _appendField = (key, text) => { if(!text) return; setEditing(e => { const cur=(e[key]||'').trim(); return {...e, [key]: cur ? `${cur}\n${text}` : text}; }); markDirty(); };
  // 生活機能チェック(ADL/IADL/起居/心身機能) → 「機能訓練実施上の留意事項」へ取り込む
  const importFromSeikatsu = () => {
    if(!latestSeikatsu){ if(navigateTo && window.confirm('この利用者の生活機能チェックがまだありません。作成画面を開きますか？')) navigateTo('seikatsu_kinou'); return; }
    const s = latestSeikatsu;
    const care = (obj, items) => (items||[]).filter(k=>{const v=obj?.[k]; return v && v!=='自立';}).map(k=>`${k}:${obj[k]}`);
    const shin = (SEIKATSU_SHINSHIN).filter(k=>{const v=s.shinshin?.[k]; return v && v!=='なし';}).map(k=>`${k}:${s.shinshin[k]}`);
    const adl = [...care(s.adl,SEIKATSU_ADL), ...care(s.kikyo,SEIKATSU_KIKYO), ...care(s.iadl,SEIKATSU_IADL)];
    const parts=[];
    if(shin.length) parts.push(`【心身機能】${shin.join('／')}`);
    if(adl.length) parts.push(`【生活動作で介助・見守りが必要】${adl.join('／')}`);
    if(!parts.length){ alert('生活機能チェックに介助が必要な項目がありませんでした（すべて自立／なし）。'); return; }
    const summary = parts.join(' ');
    if(!window.confirm(`生活機能チェック（${s.recordDate||'日付なし'}）から、次を「機能訓練実施上の留意事項」に取り込みます。\n\n${summary}\n\nよろしいですか？（既存の内容の下に追記します）`)) return;
    _appendField('ryuiPoint', summary);
  };
  // 興味・関心チェック → 「本人の希望」「社会参加の状況」へ取り込む
  const importFromKyomi = () => {
    if(!latestKyomi){ if(navigateTo && window.confirm('この利用者の興味・関心チェックがまだありません。作成画面を開きますか？')) navigateTo('kyomi_kanshin'); return; }
    const k = latestKyomi;
    const flagItems = (flag) => { const out=[]; (KYOMI_DEFAULT).forEach(name=>{ if(k.items?.[name]?.[flag]) out.push(name); }); (k.custom||[]).forEach(c=>{ if(c && c[flag] && c.name) out.push(c.name); }); return out; };
    const shitemitai = flagItems('shitemitai');
    const shiteiru = flagItems('shiteiru');
    const bikou = (k.bikou||'').trim();
    if(!shitemitai.length && !shiteiru.length && !bikou){ alert('興味・関心チェックに取り込める項目がありませんでした。'); return; }
    const msg = [ shitemitai.length?`「してみたい」→ 本人の希望：${shitemitai.join('、')}`:'', shiteiru.length?`「している」→ 社会参加の状況：${shiteiru.join('、')}`:'', bikou?'備考 → 本人の希望に追記':'' ].filter(Boolean).join('\n');
    if(!window.confirm(`興味・関心チェック（${k.recordDate||'日付なし'}）から取り込みます。\n\n${msg}\n\nよろしいですか？（既存の内容の下に追記します）`)) return;
    const kibou = [ shitemitai.length?`してみたい：${shitemitai.join('、')}`:'', bikou ].filter(Boolean).join('\n');
    if(kibou) _appendField('honninKibou', kibou);
    if(shiteiru.length) _appendField('shakaiSanka', `関心・実施中：${shiteiru.join('、')}`);
  };

  // 印刷対象 (編集中 or 最新)
  const printRec = editing || records[0] || null;

  return (
    <div className="flex flex-col h-full">
      {/* ヘッダ */}
      <div className="sticky top-0 z-20 bg-white border-b border-slate-200 px-4 py-2.5 flex items-center gap-3 flex-wrap">
        <KeikakuTabs current="kinou_keikaku" navigateTo={navigateTo}/>
        <select value={pid??''} onChange={e=>{ setEditing(null); setPid(Number(e.target.value)); }} className="px-3 py-1.5 bg-slate-50 border border-slate-300 rounded-lg text-sm font-bold outline-none">
          {patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
        </select>
        <div className="flex-1"/>
        {!editing && <button onClick={()=>setEditing(newRecord())} className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-bold shadow active:scale-95">＋ 新規作成</button>}
        {editing && <>
          <button onClick={()=>{ if(dirtyRef?.current && !window.confirm('編集中の内容を破棄しますか？（一時保存すれば残せます）')) return; if(dirtyRef) dirtyRef.current=false; setEditing(null); }} className="px-4 py-2 bg-slate-200 hover:bg-slate-300 text-slate-600 rounded-lg text-sm font-bold">閉じる</button>
          <button onClick={()=>saveRecord(false)} className="px-4 py-2 bg-white border border-emerald-500 text-emerald-600 hover:bg-emerald-50 rounded-lg text-sm font-bold active:scale-95" title="編集画面を開いたまま保存します">一時保存</button>
          <button onClick={()=>saveRecord(true)} className="px-5 py-2 bg-emerald-500 hover:bg-emerald-600 text-white rounded-lg text-sm font-bold shadow active:scale-95">保存して閉じる</button>
        </>}
        {printRec && <button onClick={()=>onShowPrintPreview('個別機能訓練計画書','A4','kk-print-area')} className="px-4 py-2 bg-slate-700 hover:bg-slate-800 text-white rounded-lg text-sm font-bold shadow active:scale-95">印刷/PDF</button>}
      </div>

      <div className="flex-1 overflow-y-auto p-4 bg-slate-50">
        {!pid ? <div className="text-center text-slate-400 py-20 font-bold">利用者を登録してください</div> : editing ? (
          <div className="max-w-4xl mx-auto space-y-4">
            {/* 計画書連携: 他様式から取り込む */}
            <div className="bg-indigo-50 rounded-xl border border-indigo-200 p-4">
              <div className="text-sm font-bold text-indigo-700 mb-1 flex items-center gap-2">他の様式から取り込む（計画書連携）</div>
              <div className="text-[11px] text-indigo-900 opacity-70 mb-3">フェイスシート・生活機能チェック・興味関心チェック・運動メニューの最新内容を、この計画書の該当欄へ取り込みます（既存の内容の下に追記します）。</div>
              <div className="flex flex-wrap gap-2">
                <button onClick={kkImportFromFaceSheet} title="フェイスシートから 自立度・本人の希望・社会参加・居宅環境・病名・留意事項 を空欄にだけ補完します（入力済みは上書きしません）"
                  className="px-3 py-2 bg-white border border-indigo-300 text-indigo-700 rounded-lg text-xs font-bold hover:bg-indigo-100">
                  フェイスシートから空欄を補完
                </button>
                <button onClick={importFromSeikatsu} title="最新の生活機能チェックから、介助が必要なADL/IADL・心身機能を『機能訓練実施上の留意事項』へ取り込みます"
                  className="px-3 py-2 bg-white border border-indigo-300 text-indigo-700 rounded-lg text-xs font-bold hover:bg-indigo-100">
                  生活機能チェックから取り込む <span className="font-normal opacity-70">{latestSeikatsu?`（${latestSeikatsu.recordDate||'日付なし'}）`:'（未作成）'}</span>
                </button>
                <button onClick={importFromKyomi} title="最新の興味・関心チェックから『してみたい/している』項目を『本人の希望/社会参加の状況』へ取り込みます"
                  className="px-3 py-2 bg-white border border-indigo-300 text-indigo-700 rounded-lg text-xs font-bold hover:bg-indigo-100">
                  興味・関心から取り込む <span className="font-normal opacity-70">{latestKyomi?`（${latestKyomi.recordDate||'日付なし'}）`:'（未作成）'}</span>
                </button>
                <button onClick={()=>upd({programs:programsFromPlanned()})} title="運動メニュー（月別提供記録の予定運動）から個別機能訓練項目を取り込みます"
                  className="px-3 py-2 bg-white border border-amber-300 text-amber-700 rounded-lg text-xs font-bold hover:bg-amber-100">
                  運動メニューから訓練項目を取り込む
                </button>
              </div>
            </div>
            {/* 基本情報 */}
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="text-sm font-bold text-blue-700 mb-3">基本情報（{patient?.name} 様／{patient?.gender||''}／{_age(patient?.birthDate)}歳／{patient?.careLevel||''}）</div>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                <KKDateField label="作成日" value={editing.createdDate} onChange={v=>upd({createdDate:v})}/>
                <KKDateField label="前回作成日" value={editing.prevDate} onChange={v=>upd({prevDate:v})} ph="（初回は空欄）"/>
                <KKDateField label="初回作成日" value={editing.firstDate} onChange={v=>upd({firstDate:v})}/>
                <KKField label="計画作成者" value={editing.author} onChange={v=>upd({author:v})}/>
                <KKField label="職種" value={editing.authorJob} onChange={v=>upd({authorJob:v})}/>
                <div/>
                <div>
                  <label className="block text-xs font-bold text-slate-500 mb-1">障害高齢者の日常生活自立度</label>
                  <select value={editing.jiritsuBody} onChange={e=>upd({jiritsuBody:e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none">
                    <option value="">選択</option>{JIRITSU_BODY.map(o=><option key={o} value={o}>{o}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 mb-1">認知症高齢者の日常生活自立度</label>
                  <select value={editing.jiritsuDementia} onChange={e=>upd({jiritsuDementia:e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none">
                    <option value="">選択</option>{JIRITSU_DEM.map(o=><option key={o} value={o}>{o}</option>)}
                  </select>
                </div>
              </div>
            </div>
            {/* Ⅰ 利用者の基本情報 */}
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="text-sm font-bold text-blue-700 mb-3">Ⅰ 利用者の基本情報</div>
              <div className="grid md:grid-cols-2 gap-3">
                <KKField label="利用者本人の希望" value={editing.honninKibou} onChange={v=>upd({honninKibou:v})} rows={2}/>
                <KKField label="家族の希望" value={editing.kazokuKibou} onChange={v=>upd({kazokuKibou:v})} rows={2}/>
                <KKField label="利用者本人の社会参加の状況" value={editing.shakaiSanka} onChange={v=>upd({shakaiSanka:v})} rows={2}/>
                <KKField label="利用者の居宅の環境（環境因子）" value={editing.kyotakuKankyo} onChange={v=>upd({kyotakuKankyo:v})} rows={2}/>
              </div>
            </div>
            {/* 健康状態・経過 */}
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="text-sm font-bold text-blue-700 mb-3">健康状態・経過</div>
              <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-3">
                <KKField label="病名" value={editing.byomei} onChange={v=>upd({byomei:v})}/>
                <KKDateField label="発症日・受傷日" value={editing.hasshoDate} onChange={v=>upd({hasshoDate:v})}/>
                <KKDateField label="直近の入院日" value={editing.nyuinDate} onChange={v=>upd({nyuinDate:v})}/>
                <KKDateField label="直近の退院日" value={editing.taiinDate} onChange={v=>upd({taiinDate:v})}/>
              </div>
              <div className="grid md:grid-cols-1 gap-3">
                <KKField label="治療経過（手術がある場合は手術日・術式等）" value={editing.chiryoKeika} onChange={v=>upd({chiryoKeika:v})} rows={2}/>
                <KKField label="合併疾患・コントロール状態（高血圧・心疾患・呼吸器疾患・糖尿病等）" value={editing.gappei} onChange={v=>upd({gappei:v})} rows={2}/>
                <KKField label="機能訓練実施上の留意事項（開始前・訓練中の留意事項、運動強度・負荷量等）" value={editing.ryuiPoint} onChange={v=>upd({ryuiPoint:v})} rows={2} suggestions={TPL_RYUI}/>
              </div>
            </div>
            {/* Ⅱ 目標 */}
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="text-sm font-bold text-blue-700 mb-3">Ⅱ 個別機能訓練の目標</div>
              <div className="grid md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <div className="flex items-center gap-2"><span className="text-xs font-bold text-slate-600">短期目標（今後3ヶ月）</span>
                    <select value={editing.shortAchieve} onChange={e=>upd({shortAchieve:e.target.value})} className="px-2 py-1 border border-slate-300 rounded text-xs outline-none"><option value="">達成度</option><option>達成</option><option>一部</option><option>未達</option></select></div>
                  <KKField label="（機能）" value={editing.shortKinou} onChange={v=>upd({shortKinou:v})} rows={2} suggestions={TPL_KINOU}/>
                  <KKField label="（活動）" value={editing.shortKatsudo} onChange={v=>upd({shortKatsudo:v})} rows={2} suggestions={TPL_KATSUDO}/>
                  <KKField label="（参加）" value={editing.shortSanka} onChange={v=>upd({shortSanka:v})} rows={2} suggestions={TPL_SANKA}/>
                </div>
                <div className="space-y-2">
                  <div className="flex items-center gap-2"><span className="text-xs font-bold text-slate-600">長期目標</span>
                    <select value={editing.longAchieve} onChange={e=>upd({longAchieve:e.target.value})} className="px-2 py-1 border border-slate-300 rounded text-xs outline-none"><option value="">達成度</option><option>達成</option><option>一部</option><option>未達</option></select></div>
                  <KKField label="（機能）" value={editing.longKinou} onChange={v=>upd({longKinou:v})} rows={2} suggestions={TPL_KINOU}/>
                  <KKField label="（活動）" value={editing.longKatsudo} onChange={v=>upd({longKatsudo:v})} rows={2} suggestions={TPL_KATSUDO}/>
                  <KKField label="（参加）" value={editing.longSanka} onChange={v=>upd({longSanka:v})} rows={2} suggestions={TPL_SANKA}/>
                </div>
              </div>
            </div>
            {/* 個別機能訓練項目 */}
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="flex items-center justify-between mb-2">
                <div className="text-sm font-bold text-blue-700">個別機能訓練項目</div>
                <div className="flex gap-2">
                  <button onClick={()=>upd({programs:programsFromPlanned()})} className="px-3 py-1 bg-amber-100 hover:bg-amber-200 text-amber-700 rounded text-xs font-bold">運動メニューから取込</button>
                  <button onClick={addProg} className="px-3 py-1 bg-blue-100 hover:bg-blue-200 text-blue-700 rounded text-xs font-bold">＋ 行追加</button>
                </div>
              </div>
              <div className="grid grid-cols-12 gap-2 text-[10px] font-bold text-slate-400 px-1 mb-1">
                <div className="col-span-4">プログラム内容（何を目的に〜する）</div><div className="col-span-3">留意点</div><div className="col-span-2">頻度(週○回)</div><div className="col-span-2">時間</div><div className="col-span-1"></div>
              </div>
              <div className="space-y-2">
                {editing.programs.map((pr,i)=>(
                  <div key={i} className="grid grid-cols-12 gap-2 items-start bg-slate-50 rounded-lg p-2">
                    <input value={pr.content} onChange={e=>updProg(i,{content:e.target.value})} placeholder="○○のために△△する" className="col-span-4 px-2 py-1.5 bg-white border border-slate-300 rounded text-xs outline-none"/>
                    <input value={pr.point} onChange={e=>updProg(i,{point:e.target.value})} placeholder="留意点" className="col-span-3 px-2 py-1.5 bg-white border border-slate-300 rounded text-xs outline-none"/>
                    <input value={pr.freqWeek} onChange={e=>updProg(i,{freqWeek:e.target.value})} placeholder="週○回" className="col-span-2 px-2 py-1.5 bg-white border border-slate-300 rounded text-xs outline-none"/>
                    <input value={pr.time} onChange={e=>updProg(i,{time:e.target.value})} placeholder="○分" className="col-span-2 px-2 py-1.5 bg-white border border-slate-300 rounded text-xs outline-none"/>
                    <button onClick={()=>delProg(i)} className="col-span-1 text-red-500 hover:text-red-700 text-xs font-bold py-1.5">削除</button>
                    <input value={pr.person} onChange={e=>updProg(i,{person:e.target.value})} placeholder="主な実施者" className="col-span-11 px-2 py-1 bg-white border border-slate-200 rounded text-[11px] outline-none"/>
                  </div>
                ))}
              </div>
              <div className="mt-2"><KKField label="プログラム立案者" value={editing.programPlanner} onChange={v=>upd({programPlanner:v})}/></div>
              <div className="grid md:grid-cols-2 gap-3 mt-3">
                <KKField label="利用者本人・家族等がサービス利用時間以外に実施すること" value={editing.jikangaiJisshi} onChange={v=>upd({jikangaiJisshi:v})} rows={2}/>
                <KKField label="特記事項" value={editing.tokki} onChange={v=>upd({tokki:v})} rows={2}/>
              </div>
            </div>
            {/* Ⅲ 実施後の対応 */}
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="text-sm font-bold text-blue-700 mb-1">Ⅲ 個別機能訓練実施後の対応</div>
              <div className="text-[10px] text-slate-400 mb-3">※ 初回作成時は記載不要</div>
              <div className="grid md:grid-cols-2 gap-3">
                <KKField label="個別機能訓練の実施による変化" value={editing.henka} onChange={v=>upd({henka:v})} rows={2}/>
                <KKField label="個別機能訓練実施における課題とその要因" value={editing.kadai} onChange={v=>upd({kadai:v})} rows={2}/>
              </div>
            </div>
            {/* 説明 */}
            <div className="bg-white rounded-xl border border-slate-200 p-4 grid grid-cols-2 gap-3">
              <KKDateField label="説明日" value={editing.setsumeiDate} onChange={v=>upd({setsumeiDate:v})}/>
              <KKField label="説明者" value={editing.setsumeisha} onChange={v=>upd({setsumeisha:v})}/>
            </div>
          </div>
        ) : (
          /* 一覧 */
          <div className="max-w-3xl mx-auto">
            {records.length === 0 ? (
              <div className="text-center text-slate-400 py-16">
                <div className="font-bold mb-2">{patient?.name} 様の個別機能訓練計画書はまだありません</div>
                <button onClick={()=>setEditing(newRecord())} className="px-5 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-bold shadow">＋ 新規作成</button>
              </div>
            ) : (
              <div className="space-y-2">
                {records.length>=2 && (
                  <div className="bg-white rounded-xl border border-slate-200 p-4 mb-1">
                    <div className="text-sm font-bold text-blue-700 mb-2">目標の推移（見直し比較・新しい順）</div>
                    <div className="overflow-x-auto">
                      <table className="w-full text-xs border-collapse whitespace-pre-wrap">
                        <thead><tr className="bg-slate-50 text-slate-500"><th className="border border-slate-200 px-2 py-1 text-left w-24">作成日</th><th className="border border-slate-200 px-2 py-1 text-left">短期目標(機能/活動)</th><th className="border border-slate-200 px-2 py-1 w-14">達成</th><th className="border border-slate-200 px-2 py-1 text-left">長期目標(機能)</th><th className="border border-slate-200 px-2 py-1 w-14">達成</th></tr></thead>
                        <tbody>
                          {records.slice(0,4).map((r,i)=>(
                            <tr key={r.id} className={i===0?'bg-emerald-50':''}>
                              <td className="border border-slate-200 px-2 py-1 font-bold text-slate-700 align-top">{r.createdDate||'—'}{i===0&&<span className="ml-1 text-[9px] text-emerald-600">最新</span>}</td>
                              <td className="border border-slate-200 px-2 py-1 align-top">{[r.shortKinou,r.shortKatsudo].filter(Boolean).join(' / ')||'—'}</td>
                              <td className="border border-slate-200 px-2 py-1 text-center align-top">{r.shortAchieve||'—'}</td>
                              <td className="border border-slate-200 px-2 py-1 align-top">{r.longKinou||'—'}</td>
                              <td className="border border-slate-200 px-2 py-1 text-center align-top">{r.longAchieve||'—'}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}
                {records.map(r => (
                  <div key={r.id} className="bg-white rounded-xl border border-slate-200 p-4 flex items-center justify-between gap-3">
                    <div>
                      <div className="font-bold text-slate-800">作成日: {r.createdDate}{r.author?`／作成者: ${r.author}`:''}</div>
                      <div className="text-xs text-slate-500 mt-0.5 truncate" style={{maxWidth:420}}>短期目標(機能): {r.shortKinou||'（未入力）'}</div>
                    </div>
                    <div className="flex gap-2 shrink-0">
                      <button onClick={()=>setEditing(r)} className="px-3 py-1.5 bg-blue-100 hover:bg-blue-200 text-blue-700 rounded-lg text-xs font-bold">編集</button>
                      <button onClick={()=>dupRecord(r)} className="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-lg text-xs font-bold">複製して更新</button>
                      <button onClick={()=>delRecord(r.id)} className="px-3 py-1.5 bg-red-50 hover:bg-red-100 text-red-600 rounded-lg text-xs font-bold">削除</button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {/* 印刷用 (非表示) — 別紙様式3-3 に準拠 (A4) */}
      {printRec && (() => {
        const B='1px solid #000';
        const cell={border:B,padding:'3px 5px',verticalAlign:'top',whiteSpace:'pre-wrap',fontSize:'10px',wordBreak:'break-word'};
        const lab={...cell,background:'#f3f4f6',fontWeight:'bold'};
        const sec={fontWeight:'bold',fontSize:'12px',margin:'8px 0 3px',borderBottom:'2px solid #000',paddingBottom:'1px'};
        const scale=(opts,sel)=>opts.map(o=><span key={o} style={{marginRight:6,padding:sel===o?'0 3px':'0',fontWeight:sel===o?'bold':'normal',border:sel===o?'1.5px solid #000':'none',borderRadius:sel===o?'3px':0}}>{o}</span>);
        const pr=printRec; const bd=patient?.birthDate?new Date(patient.birthDate):null;
        return (
        <div id="kk-print-area" style={{display:'none',background:'white',color:'#000',width:'210mm',height:'297mm',padding:'6mm 7mm 4mm',boxSizing:'border-box',fontFamily:'"Hiragino Sans","Yu Gothic",sans-serif',lineHeight:1.3,overflow:'hidden',flexDirection:'column'}}>
          {/* ★ A4(210x297mm)を1枚で使い切る。 各セクションを flex 比率で縦に配分し、下部に余白を残さない。
              印刷プレビューは display:none を block に置換するため、flex は CSS 側で指定する。 */}
          <style>{`#kk-print-area{display:flex!important}
            #kk-print-area table{table-layout:fixed;width:100%;border-collapse:collapse;max-width:100%}
            #kk-print-area td,#kk-print-area th{word-break:break-word;overflow-wrap:anywhere}
            #kk-print-area *{max-width:100%}
            #kk-print-area .kkgrow{flex:1 1 0;min-height:0;display:flex;flex-direction:column}
            #kk-print-area .kkgrow>table{height:100%}
            #kk-print-area .kkfix{flex:0 0 auto}`}</style>
          <div className="kkfix" style={{fontSize:'10px'}}>別紙様式３－３</div>
          <div className="kkfix" style={{textAlign:'center',fontSize:'15px',fontWeight:'bold',margin:'2px 0 6px'}}>【個別機能訓練計画書】</div>
          <table style={{width:'100%',borderCollapse:'collapse'}}><tbody>
            <tr><td style={cell}>作成日：{pr.createdDate||'令和　年　月　日'}</td><td style={cell}>前回作成日：{pr.prevDate||'令和　年　月　日'}</td><td style={cell}>初回作成日：{pr.firstDate||'令和　年　月　日'}</td></tr>
          </tbody></table>
          <table style={{width:'100%',borderCollapse:'collapse',marginTop:'-1px'}}><tbody>
            <tr>
              <td style={{...cell,width:'34%'}}><div style={{fontSize:'8px'}}>ふりがな　{patient?.kana||''}</div><div style={{fontSize:'12px',fontWeight:'bold'}}>{patient?.name||''}</div></td>
              <td style={{...cell,width:'10%'}}>性別<br/>{patient?.gender||''}</td>
              <td style={{...cell,width:'24%'}}>{bd?`${bd.getFullYear()}年${bd.getMonth()+1}月${bd.getDate()}日生（${_age(patient?.birthDate)}歳）`:'　年　月　日生（　歳）'}</td>
              <td style={{...cell,width:'12%'}}>要介護度<br/>{patient?.careLevel||''}</td>
              <td style={cell}>計画作成者：{pr.author||''}<br/>職種：{pr.authorJob||''}</td>
            </tr>
          </tbody></table>
          <table style={{width:'100%',borderCollapse:'collapse',marginTop:'-1px'}}><tbody>
            <tr><td style={{...cell,width:'50%'}}><b>障害高齢者の日常生活自立度:</b><br/>{scale(JIRITSU_BODY,pr.jiritsuBody)}</td><td style={cell}><b>認知症高齢者の日常生活自立度:</b><br/>{scale(JIRITSU_DEM,pr.jiritsuDementia)}</td></tr>
          </tbody></table>

          <div className="kkfix" style={sec}>Ⅰ　利用者の基本情報<span style={{fontSize:'8px',fontWeight:'normal',marginLeft:8}}>※別紙様式3-1・3-2を別途活用すること</span></div>
          <div className="kkgrow" style={{flexGrow:34}}>
          <table style={{width:'100%',borderCollapse:'collapse'}}><tbody>
            <tr><td style={{...lab,width:'18%'}}>利用者本人の希望</td><td style={{...cell,width:'32%'}}>{pr.honninKibou}</td><td style={{...lab,width:'18%'}}>家族の希望</td><td style={cell}>{pr.kazokuKibou}</td></tr>
            <tr><td style={lab}>本人の社会参加の状況</td><td style={cell}>{pr.shakaiSanka}</td><td style={lab}>居宅の環境（環境因子）</td><td style={cell}>{pr.kyotakuKankyo}</td></tr>
          </tbody></table></div>

          <div className="kkfix" style={sec}>健康状態・経過</div>
          <div className="kkgrow" style={{flexGrow:42}}>
          <table style={{width:'100%',borderCollapse:'collapse'}}><tbody>
            <tr><td style={{...lab,width:'22%'}}>病名</td><td style={cell}>{pr.byomei}</td><td style={cell}>発症日・受傷日：{pr.hasshoDate}</td><td style={cell}>入院日：{pr.nyuinDate}</td><td style={cell}>退院日：{pr.taiinDate}</td></tr>
            <tr><td style={lab}>治療経過</td><td style={cell} colSpan={4}>{pr.chiryoKeika}</td></tr>
            <tr><td style={lab}>合併疾患・状態</td><td style={cell} colSpan={4}>{pr.gappei}</td></tr>
            <tr><td style={lab}>機能訓練実施上の留意事項</td><td style={cell} colSpan={4}>{pr.ryuiPoint}</td></tr>
          </tbody></table></div>
          <div className="kkfix" style={{fontSize:'8px',color:'#333',margin:'1px 0 0'}}>※①〜⑤に加えて、介護支援専門員から、居宅サービス計画上の利用者本人等の意向、総合的な支援方針等について確認すること。</div>

          <div className="kkfix" style={sec}>Ⅱ　個別機能訓練の目標・個別機能訓練項目の設定</div>
          <div className="kkfix" style={{fontSize:'10px',fontWeight:'bold',margin:'2px 0'}}>個別機能訓練の目標</div>
          <div className="kkgrow" style={{flexGrow:40}}>
          <table style={{width:'100%',borderCollapse:'collapse'}}><tbody>
            <tr><td style={{...lab,width:'50%'}}>機能訓練の短期目標（今後3ヶ月）　目標達成度（達成・一部・未達）：{pr.shortAchieve||''}</td><td style={lab}>機能訓練の長期目標　目標達成度（達成・一部・未達）：{pr.longAchieve||''}</td></tr>
            <tr><td style={cell}>（機能）{pr.shortKinou}</td><td style={cell}>（機能）{pr.longKinou}</td></tr>
            <tr><td style={cell}>（活動）{pr.shortKatsudo}</td><td style={cell}>（活動）{pr.longKatsudo}</td></tr>
            <tr><td style={cell}>（参加）{pr.shortSanka}</td><td style={cell}>（参加）{pr.longSanka}</td></tr>
          </tbody></table></div>
          <div style={{fontSize:'8px',color:'#333',margin:'1px 0 0'}}>※短期目標（長期目標を達成するために必要な行為）は、訓練実施期間内に達成を目指す項目のみを記載することとして差し支えない。目標達成の目安となる期間もあわせて記載すること。</div>
          <div className="kkfix" style={{fontSize:'10px',fontWeight:'bold',margin:'5px 0 2px'}}>個別機能訓練項目</div>
          <div className="kkgrow" style={{flexGrow:56}}>
          <table style={{width:'100%',borderCollapse:'collapse'}}>
            <thead><tr>{['プログラム内容（何を目的に（〜のために）〜する）','留意点','頻度','時間','主な実施者'].map((h,i)=><th key={h} style={{...lab,textAlign:'center',width:i===0?'40%':i===1?'24%':'12%'}}>{h}</th>)}</tr></thead>
            <tbody>
              {Array.from({length:Math.max(4,(pr.programs||[]).length)}).map((_,i)=>{ const p=(pr.programs||[])[i]||{}; return (
                <tr key={i}>
                  <td style={cell}>{['①','②','③','④','⑤','⑥','⑦','⑧'][i]||''} {p.content||''}</td>
                  <td style={cell}>{p.point||''}</td>
                  <td style={{...cell,textAlign:'center'}}>{p.freqWeek?`週${String(p.freqWeek).replace(/[週回]/g,'')}回`:'週　回'}</td>
                  <td style={{...cell,textAlign:'center'}}>{p.time||'　分'}</td>
                  <td style={cell}>{p.person||''}</td>
                </tr>
              ); })}
            </tbody>
          </table></div>
          <table className="kkfix" style={{width:'100%',borderCollapse:'collapse',marginTop:'-1px'}}><tbody>
            <tr><td style={{...cell,textAlign:'left',fontSize:'8px',color:'#333'}}>※短期目標で設定した目標を達成するために必要な行為に対応するよう、訓練項目を具体的に設定すること。</td><td style={{...cell,width:'30%',textAlign:'right'}}>プログラム立案者：{pr.programPlanner||''}</td></tr>
          </tbody></table>
          <div className="kkgrow" style={{flexGrow:22}}>
          <table style={{width:'100%',borderCollapse:'collapse'}}><tbody>
            <tr><td style={{...lab,width:'40%'}}>利用者本人・家族等がサービス利用時間以外に実施すること</td><td style={cell}>{pr.jikangaiJisshi}</td><td style={{...lab,width:'14%'}}>特記事項</td><td style={cell}>{pr.tokki}</td></tr>
          </tbody></table></div>

          <div className="kkfix" style={sec}>Ⅲ　個別機能訓練実施後の対応</div>
          <div className="kkgrow" style={{flexGrow:30}}>
          <table style={{width:'100%',borderCollapse:'collapse'}}><tbody>
            <tr><td style={{...lab,width:'50%',textAlign:'center'}}>個別機能訓練の実施による変化</td><td style={{...lab,textAlign:'center'}}>個別機能訓練実施における課題とその要因</td></tr>
            <tr><td style={cell}>{pr.henka}</td><td style={cell}>{pr.kadai}</td></tr>
          </tbody></table></div>
          <div className="kkfix" style={{fontSize:'8px',color:'#333',margin:'1px 0 0'}}>※実施結果等をふまえ、目標の見直しや訓練項目の変更等を行った場合は計画書の再作成又は更新等を行うこと。初回作成時にはⅢについては記載不要である。</div>

          <table className="kkfix" style={{width:'100%',borderCollapse:'collapse',marginTop:'4px'}}><tbody>
            <tr><td style={cell}>（地域密着型）通所介護　{facility.name||'○○○'}　事業所No.{facility.jigyoshoNo||facility.officeNo||'000000000'}<br/>住所{facility.address||'○○○'}　電話番号{facility.phone||'○○○'}</td><td style={{...cell,width:'40%'}}>説明日：{pr.setsumeiDate||'令和　年　月　日'}<br/>説明者：{pr.setsumeisha||''}</td></tr>
          </tbody></table>
        </div>
        );
      })()}
    </div>
  );
}

// === 生活機能チェックシート (別紙様式3-2 / アドオン: kinou_keikaku) ===
function SeikatsuKinouView({ appData, onSave, dirtyRef, saveFnRef, onShowPrintPreview, navigateTo, targetPatientId }) {
  const markDirty = () => { if (dirtyRef) dirtyRef.current = true; };
  const patients = sortPatientsByKana((appData.patients||[]).filter(p => p.status==='利用中' || p.status==='休止'));
  const [pid, setPid] = React.useState((targetPatientId!=null && (appData.patients||[]).some(p=>p.id===targetPatientId)) ? targetPatientId : (patients[0]?.id ?? null));
  const [editing, setEditing] = React.useState(null);
  const patient = (appData.patients||[]).find(p => p.id === pid);
  const facility = appData.systemSettings?.facilityInfo || {};
  const toReiwa = (iso) => { if(!iso) return ''; const d=new Date(iso); if(isNaN(d.getTime())) return iso; return `令和${d.getFullYear()-2018}年${d.getMonth()+1}月${d.getDate()}日`; };
  const records = (appData.seikatsuKinouRecords||[]).filter(r => r.patientId === pid).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));
  const newRecord = () => ({ id:`sk_${pid}_${Date.now()}`, patientId:pid, createdAt:Date.now(), recordDate:toReiwa(new Date().toISOString().slice(0,10)), recorder:'', adl:{}, kikyo:{}, iadl:{}, shinshin:{}, ninchi:'', kadai:patient?.ryui||'', bikou:'' });
  const upd = (patch) => { setEditing(e=>({...e,...patch})); markDirty(); };
  const updMap = (group,key,val) => { setEditing(e=>({...e,[group]:{...(e[group]||{}),[key]:val}})); markDirty(); };
  const saveRecord = (close=true) => { if(!editing) return; const list=[...(appData.seikatsuKinouRecords||[])]; const i=list.findIndex(r=>r.id===editing.id); const rec={...editing,_savedAt:syncNow()}; if(i>=0)list[i]=rec; else list.push(rec); onSave({...appData,seikatsuKinouRecords:list},{manual:true,message: close?'✓ 生活機能チェックシートを保存しました':'✓ 一時保存しました'}); if(dirtyRef)dirtyRef.current=false; if(close) setEditing(null); else setEditing(rec); };
  React.useEffect(()=>{ if(!saveFnRef) return; saveFnRef.current=()=>{ if(editing) saveRecord(); }; });
  const delRecord = (id) => { if(!window.confirm('削除しますか？')) return; onSave({...appData,seikatsuKinouRecords:(appData.seikatsuKinouRecords||[]).filter(r=>r.id!==id)},{manual:true,message:'削除しました'}); if(editing?.id===id)setEditing(null); };
  const dupRecord = (r) => setEditing({...r, id:`sk_${pid}_${Date.now()}`, createdAt:Date.now(), recordDate:toReiwa(new Date().toISOString().slice(0,10))});
  const printRec = editing || records[0] || null;
  const grpForm = (title, group, items, opts) => (
    <div className="bg-white rounded-xl border border-slate-200 p-4">
      <div className="text-sm font-bold text-blue-700 mb-2">{title}</div>
      {/* ★ 項目名とプルダウンを近づけ、次の項目との間を空ける。
          従来はラベルが w-24 固定でプルダウンが w-full に伸びていたため、
          「食事 ---- [自立]」と離れ、逆に隣の「移乗」とくっついて読みにくかった。 */}
      <div className="grid grid-cols-2 md:grid-cols-3 gap-x-8 gap-y-2">
        {items.map(it => (
          <div key={it} className="flex items-center gap-2">
            <span className="text-xs text-slate-600 shrink-0">{it}</span>
            <KKSelect value={editing[group]?.[it]} onChange={v=>updMap(group,it,v)} opts={opts} className="w-28"/>
          </div>
        ))}
      </div>
    </div>
  );
  const cellB={border:'1px solid #000',padding:'3px 6px',fontSize:'10px',verticalAlign:'top',wordBreak:'break-word'};
  const labB={...cellB,background:'#f3f4f6',fontWeight:'bold'};
  return (
    <div className="flex flex-col h-full">
      <div className="sticky top-0 z-20 bg-white border-b border-slate-200 px-4 py-2.5 flex items-center gap-3 flex-wrap">
        <KeikakuTabs current="seikatsu_kinou" navigateTo={navigateTo}/>
        <select value={pid??''} onChange={e=>{ setEditing(null); setPid(Number(e.target.value)); }} className="px-3 py-1.5 bg-slate-50 border border-slate-300 rounded-lg text-sm font-bold outline-none">
          {patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
        </select>
        <div className="flex-1"/>
        {!editing && <button onClick={()=>setEditing(newRecord())} className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-bold shadow active:scale-95">＋ 新規作成</button>}
        {editing && <>
          <button onClick={()=>{ if(dirtyRef?.current && !window.confirm('編集中の内容を破棄しますか？（一時保存すれば残せます）')) return; if(dirtyRef)dirtyRef.current=false; setEditing(null); }} className="px-4 py-2 bg-slate-200 hover:bg-slate-300 text-slate-600 rounded-lg text-sm font-bold">閉じる</button>
          <button onClick={()=>saveRecord(false)} className="px-4 py-2 bg-white border border-emerald-500 text-emerald-600 hover:bg-emerald-50 rounded-lg text-sm font-bold active:scale-95" title="編集画面を開いたまま保存します">一時保存</button>
          <button onClick={()=>saveRecord(true)} className="px-5 py-2 bg-emerald-500 hover:bg-emerald-600 text-white rounded-lg text-sm font-bold shadow active:scale-95">保存して閉じる</button>
        </>}
        {printRec && <button onClick={()=>onShowPrintPreview('生活機能チェックシート','A4','sk-print-area')} className="px-4 py-2 bg-slate-700 hover:bg-slate-800 text-white rounded-lg text-sm font-bold shadow active:scale-95">印刷/PDF</button>}
      </div>
      <div className="flex-1 overflow-y-auto p-4 bg-slate-50">
        {!pid ? <div className="text-center text-slate-400 py-20 font-bold">利用者を登録してください</div> : editing ? (
          <div className="max-w-4xl mx-auto space-y-4">
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="text-sm font-bold text-blue-700 mb-3">基本情報（{patient?.name} 様）</div>
              <div className="grid grid-cols-2 gap-3">
                <KKDateField label="作成日" value={editing.recordDate} onChange={v=>upd({recordDate:v})}/>
                <KKField label="記入者" value={editing.recorder} onChange={v=>upd({recorder:v})}/>
              </div>
            </div>
            {grpForm('起居動作','kikyo',SEIKATSU_KIKYO,KK_STATUS)}
            {grpForm('ADL（日常生活動作）','adl',SEIKATSU_ADL,KK_STATUS)}
            {grpForm('IADL（手段的日常生活動作）','iadl',SEIKATSU_IADL,KK_STATUS)}
            {grpForm('心身機能・構造（程度）','shinshin',SEIKATSU_SHINSHIN,KK_SHINSHIN)}
            <div className="bg-white rounded-xl border border-slate-200 p-4 grid md:grid-cols-1 gap-3">
              <KKField label="認知機能・コミュニケーション" value={editing.ninchi} onChange={v=>upd({ninchi:v})} rows={2}/>
              <KKField label="生活上の課題・背景因子" value={editing.kadai} onChange={v=>upd({kadai:v})} rows={2}/>
              <KKField label="備考" value={editing.bikou} onChange={v=>upd({bikou:v})} rows={2}/>
            </div>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto">
            {records.length === 0 ? (
              <div className="text-center text-slate-400 py-16"><div className="font-bold mb-2">{patient?.name} 様の生活機能チェックシートはまだありません</div><button onClick={()=>setEditing(newRecord())} className="px-5 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-bold shadow">＋ 新規作成</button></div>
            ) : (
              <div className="space-y-2">{records.map(r=>(
                <div key={r.id} className="bg-white rounded-xl border border-slate-200 p-4 flex items-center justify-between gap-3">
                  <div className="font-bold text-slate-800">作成日: {r.recordDate}{r.recorder?`／記入者: ${r.recorder}`:''}</div>
                  <div className="flex gap-2 shrink-0">
                    <button onClick={()=>setEditing(r)} className="px-3 py-1.5 bg-blue-100 hover:bg-blue-200 text-blue-700 rounded-lg text-xs font-bold">編集</button>
                    <button onClick={()=>dupRecord(r)} className="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-lg text-xs font-bold">複製</button>
                    <button onClick={()=>delRecord(r.id)} className="px-3 py-1.5 bg-red-50 hover:bg-red-100 text-red-600 rounded-lg text-xs font-bold">削除</button>
                  </div>
                </div>
              ))}</div>
            )}
          </div>
        )}
      </div>
      {printRec && (
        <div id="sk-print-area" style={{display:'none',background:'white',color:'#000',width:'794px',padding:'34px 36px',boxSizing:'border-box',fontFamily:'"Hiragino Sans","Yu Gothic",sans-serif',lineHeight:1.3}}>
          <style>{`#sk-print-area table{table-layout:fixed;width:100%;border-collapse:collapse;max-width:100%} #sk-print-area td,#sk-print-area th{word-break:break-word;overflow-wrap:anywhere} #sk-print-area *{max-width:100%}`}</style>
          <div style={{fontSize:'10px'}}>別紙様式３－２</div>
          <div style={{textAlign:'center',fontSize:'15px',fontWeight:'bold',margin:'2px 0 6px'}}>【生活機能チェックシート】</div>
          <table style={{width:'100%',borderCollapse:'collapse'}}><tbody>
            <tr><td style={labB}>氏名</td><td style={cellB}>{patient?.name} 様</td><td style={labB}>作成日</td><td style={cellB}>{printRec.recordDate}</td><td style={labB}>記入者</td><td style={cellB}>{printRec.recorder}</td></tr>
          </tbody></table>
          {[['起居動作',SEIKATSU_KIKYO,'kikyo'],['ADL（日常生活動作）',SEIKATSU_ADL,'adl'],['IADL（手段的日常生活動作）',SEIKATSU_IADL,'iadl'],['心身機能・構造',SEIKATSU_SHINSHIN,'shinshin']].map(([title,items,grp])=>(
            <div key={grp}>
              <div style={{fontWeight:'bold',fontSize:'11px',margin:'6px 0 2px'}}>{title}</div>
              <table style={{width:'100%',borderCollapse:'collapse'}}><tbody>
                {Array.from({length:Math.ceil(items.length/2)}).map((_,r)=>(
                  <tr key={r}>{[0,1].map(c=>{ const it=items[r*2+c]; return it?(<React.Fragment key={c}><td style={{...labB,width:'22%'}}>{it}</td><td style={{...cellB,width:'28%'}}>{printRec[grp]?.[it]||''}</td></React.Fragment>):<React.Fragment key={c}><td style={cellB}></td><td style={cellB}></td></React.Fragment>; })}</tr>
                ))}
              </tbody></table>
            </div>
          ))}
          <table style={{width:'100%',borderCollapse:'collapse',marginTop:'6px'}}><tbody>
            <tr><td style={labB}>認知・コミュニケーション</td><td style={cellB}>{printRec.ninchi}</td></tr>
            <tr><td style={labB}>生活上の課題・背景因子</td><td style={cellB}>{printRec.kadai}</td></tr>
            <tr><td style={labB}>備考</td><td style={cellB}>{printRec.bikou}</td></tr>
          </tbody></table>
          <div style={{fontSize:'10px',marginTop:'6px'}}>{facility.name||''}</div>
        </div>
      )}
    </div>
  );
}

// === 興味・関心チェックシート (別紙様式3-1 / アドオン: kinou_keikaku) ===
function KyomiKanshinView({ appData, onSave, dirtyRef, saveFnRef, onShowPrintPreview, navigateTo, targetPatientId }) {
  const markDirty = () => { if (dirtyRef) dirtyRef.current = true; };
  const patients = sortPatientsByKana((appData.patients||[]).filter(p => p.status==='利用中' || p.status==='休止'));
  const [pid, setPid] = React.useState((targetPatientId!=null && (appData.patients||[]).some(p=>p.id===targetPatientId)) ? targetPatientId : (patients[0]?.id ?? null));
  const [editing, setEditing] = React.useState(null);
  const [newItem, setNewItem] = React.useState('');
  const patient = (appData.patients||[]).find(p => p.id === pid);
  const facility = appData.systemSettings?.facilityInfo || {};
  const toReiwa = (iso) => { if(!iso) return ''; const d=new Date(iso); if(isNaN(d.getTime())) return iso; return `令和${d.getFullYear()-2018}年${d.getMonth()+1}月${d.getDate()}日`; };
  const records = (appData.kyomiKanshinRecords||[]).filter(r => r.patientId === pid).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));
  const newRecord = () => ({ id:`ki_${pid}_${Date.now()}`, patientId:pid, createdAt:Date.now(), recordDate:toReiwa(new Date().toISOString().slice(0,10)), recorder:'', items:{}, custom:[], bikou:'' });
  const upd = (patch) => { setEditing(e=>({...e,...patch})); markDirty(); };
  const toggle = (name,key) => { setEditing(e=>{ const cur=e.items?.[name]||{}; return {...e, items:{...e.items,[name]:{...cur,[key]:!cur[key]}}}; }); markDirty(); };
  const toggleCustom = (i,key) => { setEditing(e=>({...e, custom:e.custom.map((c,idx)=>idx===i?{...c,[key]:!c[key]}:c)})); markDirty(); };
  const addCustom = () => { if(!newItem.trim()) return; setEditing(e=>({...e, custom:[...(e.custom||[]), {name:newItem.trim()}]})); setNewItem(''); markDirty(); };
  const delCustom = (i) => { setEditing(e=>({...e, custom:e.custom.filter((_,idx)=>idx!==i)})); markDirty(); };
  const saveRecord = (close=true) => { if(!editing) return; const list=[...(appData.kyomiKanshinRecords||[])]; const i=list.findIndex(r=>r.id===editing.id); const rec={...editing,_savedAt:syncNow()}; if(i>=0)list[i]=rec; else list.push(rec); onSave({...appData,kyomiKanshinRecords:list},{manual:true,message: close?'✓ 興味・関心チェックシートを保存しました':'✓ 一時保存しました'}); if(dirtyRef)dirtyRef.current=false; if(close) setEditing(null); else setEditing(rec); };
  React.useEffect(()=>{ if(!saveFnRef) return; saveFnRef.current=()=>{ if(editing) saveRecord(); }; });
  const delRecord = (id) => { if(!window.confirm('削除しますか？')) return; onSave({...appData,kyomiKanshinRecords:(appData.kyomiKanshinRecords||[]).filter(r=>r.id!==id)},{manual:true,message:'削除しました'}); if(editing?.id===id)setEditing(null); };
  const dupRecord = (r) => setEditing({...r, id:`ki_${pid}_${Date.now()}`, createdAt:Date.now(), recordDate:toReiwa(new Date().toISOString().slice(0,10))});
  const printRec = editing || records[0] || null;
  const COLS = [['shiteiru','している'],['shitemitai','してみたい'],['kyomi','興味がある']];
  const row3 = (name, vals, onTog) => (
    <div className="flex items-center gap-2 py-1 border-b border-slate-100">
      <span className="text-xs text-slate-700 flex-1 min-w-0">{name}</span>
      {COLS.map(([k,l])=>(
        <label key={k} className="flex items-center gap-1 text-[10px] text-slate-500 w-16 justify-center shrink-0">
          <input type="checkbox" checked={!!vals?.[k]} onChange={()=>onTog(k)} className="accent-blue-500"/>{l}
        </label>
      ))}
    </div>
  );
  const cellB={border:'1px solid #000',padding:'2px 5px',fontSize:'10px',textAlign:'center'};
  return (
    <div className="flex flex-col h-full">
      <div className="sticky top-0 z-20 bg-white border-b border-slate-200 px-4 py-2.5 flex items-center gap-3 flex-wrap">
        <KeikakuTabs current="kyomi_kanshin" navigateTo={navigateTo}/>
        <select value={pid??''} onChange={e=>{ setEditing(null); setPid(Number(e.target.value)); }} className="px-3 py-1.5 bg-slate-50 border border-slate-300 rounded-lg text-sm font-bold outline-none">
          {patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
        </select>
        <div className="flex-1"/>
        {!editing && <button onClick={()=>setEditing(newRecord())} className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-bold shadow active:scale-95">＋ 新規作成</button>}
        {editing && <>
          <button onClick={()=>{ if(dirtyRef?.current && !window.confirm('編集中の内容を破棄しますか？（一時保存すれば残せます）')) return; if(dirtyRef)dirtyRef.current=false; setEditing(null); }} className="px-4 py-2 bg-slate-200 hover:bg-slate-300 text-slate-600 rounded-lg text-sm font-bold">閉じる</button>
          <button onClick={()=>saveRecord(false)} className="px-4 py-2 bg-white border border-emerald-500 text-emerald-600 hover:bg-emerald-50 rounded-lg text-sm font-bold active:scale-95" title="編集画面を開いたまま保存します">一時保存</button>
          <button onClick={()=>saveRecord(true)} className="px-5 py-2 bg-emerald-500 hover:bg-emerald-600 text-white rounded-lg text-sm font-bold shadow active:scale-95">保存して閉じる</button>
        </>}
        {printRec && <button onClick={()=>onShowPrintPreview('興味・関心チェックシート','A4','ki-print-area')} className="px-4 py-2 bg-slate-700 hover:bg-slate-800 text-white rounded-lg text-sm font-bold shadow active:scale-95">印刷/PDF</button>}
      </div>
      <div className="flex-1 overflow-y-auto p-4 bg-slate-50">
        {!pid ? <div className="text-center text-slate-400 py-20 font-bold">利用者を登録してください</div> : editing ? (
          <div className="max-w-3xl mx-auto space-y-4">
            <div className="bg-white rounded-xl border border-slate-200 p-4 grid grid-cols-2 gap-3">
              <KKDateField label="作成日" value={editing.recordDate} onChange={v=>upd({recordDate:v})}/>
              <KKField label="記入者" value={editing.recorder} onChange={v=>upd({recorder:v})}/>
            </div>
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="text-sm font-bold text-blue-700 mb-2">興味・関心（あてはまるものにチェック）</div>
              {KYOMI_DEFAULT.map(name => row3(name, editing.items?.[name], (k)=>toggle(name,k)))}
              {(editing.custom||[]).map((c,i)=>(
                <div key={i} className="flex items-center gap-1">
                  <div className="flex-1">{row3(c.name, c, (k)=>toggleCustom(i,k))}</div>
                  <button onClick={()=>delCustom(i)} className="text-red-400 hover:text-red-600 text-xs px-1">✕</button>
                </div>
              ))}
              <div className="flex gap-2 mt-3">
                <input value={newItem} onChange={e=>setNewItem(e.target.value)} placeholder="項目を追加（例：陶芸）" className="flex-1 px-3 py-1.5 bg-slate-50 border border-slate-300 rounded-lg text-xs outline-none"/>
                <button onClick={addCustom} className="px-3 py-1.5 bg-blue-100 hover:bg-blue-200 text-blue-700 rounded-lg text-xs font-bold">＋ 追加</button>
              </div>
            </div>
            <div className="bg-white rounded-xl border border-slate-200 p-4"><KKField label="備考（具体的な希望・エピソード等）" value={editing.bikou} onChange={v=>upd({bikou:v})} rows={2}/></div>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto">
            {records.length === 0 ? (
              <div className="text-center text-slate-400 py-16"><div className="font-bold mb-2">{patient?.name} 様の興味・関心チェックシートはまだありません</div><button onClick={()=>setEditing(newRecord())} className="px-5 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-bold shadow">＋ 新規作成</button></div>
            ) : (
              <div className="space-y-2">{records.map(r=>(
                <div key={r.id} className="bg-white rounded-xl border border-slate-200 p-4 flex items-center justify-between gap-3">
                  <div className="font-bold text-slate-800">作成日: {r.recordDate}{r.recorder?`／記入者: ${r.recorder}`:''}</div>
                  <div className="flex gap-2 shrink-0">
                    <button onClick={()=>setEditing(r)} className="px-3 py-1.5 bg-blue-100 hover:bg-blue-200 text-blue-700 rounded-lg text-xs font-bold">編集</button>
                    <button onClick={()=>dupRecord(r)} className="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-lg text-xs font-bold">複製</button>
                    <button onClick={()=>delRecord(r.id)} className="px-3 py-1.5 bg-red-50 hover:bg-red-100 text-red-600 rounded-lg text-xs font-bold">削除</button>
                  </div>
                </div>
              ))}</div>
            )}
          </div>
        )}
      </div>
      {printRec && (
        <div id="ki-print-area" style={{display:'none',background:'white',color:'#000',width:'794px',padding:'34px 36px',boxSizing:'border-box',fontFamily:'"Hiragino Sans","Yu Gothic",sans-serif',lineHeight:1.25}}>
          <style>{`#ki-print-area table{table-layout:fixed;width:100%;border-collapse:collapse;max-width:100%} #ki-print-area td,#ki-print-area th{word-break:break-word;overflow-wrap:anywhere} #ki-print-area *{max-width:100%}`}</style>
          <div style={{fontSize:'10px'}}>別紙様式３－１</div>
          <div style={{textAlign:'center',fontSize:'15px',fontWeight:'bold',margin:'2px 0 6px'}}>【興味・関心チェックシート】</div>
          <div style={{fontSize:'10.5px',marginBottom:'4px'}}>氏名：{patient?.name} 様　　作成日：{printRec.recordDate}　　記入者：{printRec.recorder}</div>
          <table style={{width:'100%',borderCollapse:'collapse'}}>
            <thead><tr><th style={{...cellB,background:'#f3f4f6',width:'52%',textAlign:'left'}}>生活行為</th><th style={{...cellB,background:'#f3f4f6'}}>している</th><th style={{...cellB,background:'#f3f4f6'}}>してみたい</th><th style={{...cellB,background:'#f3f4f6'}}>興味がある</th></tr></thead>
            <tbody>
              {[...KYOMI_DEFAULT.map(n=>({name:n,v:printRec.items?.[n]})), ...(printRec.custom||[]).map(c=>({name:c.name,v:c}))].map((row,i)=>(
                <tr key={i}><td style={{...cellB,textAlign:'left'}}>{row.name}</td><td style={cellB}>{row.v?.shiteiru?'○':''}</td><td style={cellB}>{row.v?.shitemitai?'○':''}</td><td style={cellB}>{row.v?.kyomi?'○':''}</td></tr>
              ))}
            </tbody>
          </table>
          {printRec.bikou && <div style={{fontSize:'10.5px',marginTop:'6px'}}>備考：{printRec.bikou}</div>}
        </div>
      )}
    </div>
  );
}

// === モニタリング表（通所介護モニタリング表 正式様式 1人1枚）編集モーダル ===
// ★ 運営基準で求められる必須事項: ①サービスの実施状況 ②目標の達成(進捗)状況 ③利用者及び家族の満足度
//   ④生活状況・心身の状況の変化 ⑤今後の方向性(継続/一部変更して継続/中止)。 各項目はプルダウン選択+記述。
const MON_ITEMS = [
  { key:'s1',   no:'①', title:'サービスの実施状況',                 explain:'通所介護計画の内容どおりにサービス提供を実施できたかどうか。', options:['実施できた','概ね実施できた','一部実施できなかった','実施できなかった'] },
  { key:'goal', no:'②', title:'サービス利用目標の達成・進捗状況',     explain:'通所介護計画の目標の達成度・進捗状況。',                     options:['達成','概ね達成','一部達成','未達成','評価困難'] },
  { key:'s2',   no:'③', title:'利用者及び家族の満足度',             explain:'現に利用しているサービスに利用者・家族が満足しているか。',     options:['満足','概ね満足','普通','やや不満','不満'] },
  { key:'s3',   no:'④', title:'利用者の生活状況及び心身の状況の変化', explain:'生活状況や心身の状況に変化がないか。',                       options:['変化なし','改善傾向','悪化傾向','経過観察を要する'] },
  { key:'s4',   no:'⑤', title:'今後の方向性',                       explain:'計画の変更が必要な新たな課題が生じていないか等による判断。',   options:['このまま継続','一部内容を変更して継続','サービス中止'] },
];
const _monNorm = (v, autoText) => (v && typeof v === 'object') ? { sel: v.sel||'', text: v.text||'' } : { sel:'', text: (v!=null && v!=='') ? v : (autoText||'') };
// ★ モニタリング表を「表形式HTML」で生成 (モニタリング画面・個人ファイル 共通で使用)
const _escMon = (s) => String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br>');
// === 通所介護計画書 (アドオン: tsusho_keikaku) ===
// ★ 厚労省「別紙様式３－４【（地域密着型）通所介護計画書】」準拠。印刷はA4 1枚を使い切る(下部余白なし)。
const TSUSHO_PROG = ['入浴','食事','機能訓練','口腔・栄養','レクリエーション','健康チェック','送迎'];
const TK_ADL_OPTS = ['自立','J1','J2','A1','A2','B1','B2','C1','C2'];
const TK_DEM_OPTS = ['自立','Ⅰ','Ⅱa','Ⅱb','Ⅲa','Ⅲb','Ⅳ','M'];
const TK_JISSHI  = ['実施','一部','未実施'];
const TK_TASSEI  = ['達成','一部','未達成'];
const TK_ACHIEVE = ['達成','一部','未達'];
const TK_MARU    = ['①','②','③','④','⑤'];
const TK_UMU     = ['有','無'];
function TsushoKeikakuView({ appData, onSave, dirtyRef, saveFnRef, onShowPrintPreview, navigateTo, targetPatientId }) {
  const markDirty = () => { if (dirtyRef) dirtyRef.current = true; };
  const patients = sortPatientsByKana((appData.patients||[]).filter(p => p.status==='利用中' || p.status==='休止'));
  const [pid, setPid] = React.useState((targetPatientId!=null && (appData.patients||[]).some(p=>p.id===targetPatientId)) ? targetPatientId : (patients[0]?.id ?? null));
  const [editing, setEditing] = React.useState(null);
  const patient = (appData.patients||[]).find(p => p.id === pid);
  const facility = appData.systemSettings?.facilityInfo || {};
  const records = (appData.tsushoKeikakuRecords||[]).filter(r => r.patientId === pid).sort((a,b)=>(b.createdDate||'').localeCompare(a.createdDate||''));
  const _age = (bd)=>{ if(!bd) return ''; const d=new Date(bd),n=new Date(); let a=n.getFullYear()-d.getFullYear(); if(n.getMonth()<d.getMonth()||(n.getMonth()===d.getMonth()&&n.getDate()<d.getDate()))a--; return a; };
  const toReiwa = (iso)=>{ if(!iso) return ''; const d=new Date(iso); if(isNaN(d.getTime())) return iso; const r=d.getFullYear()-2018; return `令和${r}年${d.getMonth()+1}月${d.getDate()}日`; };
  const blankProg = ()=>({ item:'', content:'', freqWeek:'', time:'' });
  const _defaultProgs = ()=>['入浴','機能訓練','レクリエーション','健康チェック'].map(item=>({ item, content:'', freqWeek:'', time:'' }));
  // ★ 様式3-4: サービス提供内容 ①〜⑤ / プログラム(1日の流れ)
  const blankSvc = ()=>({ from:'', to:'', content:'', jisshi:'', tassei:'', effect:'' });
  const _defaultSvcs = ()=>Array.from({length:5}, blankSvc);
  const _defaultFlow = ()=>Array.from({length:8}, ()=>({ time:'', content:'' }));
  // ★ プログラム(1日の流れ)は日誌スケジュール(各種設定)から生成する。利用者の基本利用日がPMのみならPM表を使う。
  // ★ 1日の流れは 各種設定「日誌」のスケジュールをそのまま使う。
  //   午前のみ→AM表 / 午後のみ→PM表 / 午前も午後もある(1日 or 両方)→AM表とPM表の両方を載せる。
  const _useAmPm = (p)=>{
    const amp=(p?.scheduleAmPm||[]).map(v=>String(v||''));
    const hasAM=amp.some(v=>v.includes('AM')||v.includes('1日'));
    const hasPM=amp.some(v=>v.includes('PM')||v.includes('1日'));
    return { hasAM, hasPM };
  };
  const _flowSrc = (p)=>{
    const ds=appData.diarySettings||{};
    const { hasAM, hasPM } = _useAmPm(p);
    const am=(ds.scheduleAM||[]), pm=(ds.schedulePM||[]);
    if (hasAM && hasPM) return [...am, ...pm];   // 午前・午後とも利用 → 両方
    if (hasPM) return pm;
    if (hasAM) return am;
    return am.length ? am : pm;                   // 基本利用日が未設定なら AM を既定に
  };
  const _autoFlow = (p)=>{ const s=_flowSrc(p); return s.length ? s.map(x=>({ time:x.time||'', content:x.content||'' })) : _defaultFlow(); };
  // ★ 利用予定: 基本利用日(scheduleAmPm)＋送迎時間(pickupTimes)から「曜日（区分 時間）」を組み立てる
  const _baseUseDays=(p)=>{
    const patient = p || null;
    if(!patient) return '';
    const dows=['日','月','火','水','木','金','土'];
    const parts=[];
    (patient.scheduleAmPm||[]).forEach((v,i)=>{ if(v){ const t=(patient.pickupTimes?.[i]||'').trim(); parts.push(`${dows[i]}（${v}${t?` ${t}`:''}）`); } });
    return parts.join('・');
  };
  // ★ 提供時間区分: 施設の提供時間(各種設定→事業所情報)から所要時間を計算して区分に落とす。
  //   午前・午後とも利用なら 1日(serviceTimeFullDay)、午後のみなら PM、それ以外は AM を使う。
  const _teikyoKubun = (p)=>{
    const f = appData.systemSettings?.facilityInfo || {};
    const { hasAM, hasPM } = _useAmPm(p);
    const src = (hasAM && hasPM) ? (f.serviceTimeFullDay || '') : hasPM ? (f.serviceTimePM || '') : (f.serviceTimeAM || '');
    const m = String(src).match(/(\d{1,2}):(\d{2})\s*[~〜～-]\s*(\d{1,2}):(\d{2})/);
    if (!m) return '';
    const mins = (Number(m[3])*60+Number(m[4])) - (Number(m[1])*60+Number(m[2]));
    if (!(mins > 0)) return '';
    const h = mins/60;
    for (let lo=3; lo<=8; lo++) { if (h >= lo && h < lo+1) return `${lo}時間以上${lo+1}時間未満`; }
    return h < 3 ? '2時間以上3時間未満' : '8時間以上9時間未満';
  };
  // ★ 職員名の候補 (計画作成者・説明者のプルダウン用)
  const _staffOpts = Array.from(new Set((appData.diarySettings?.staff||[]).map(s=>String(s?.name||'').trim()).filter(Boolean)));
  const _roleOpts = Array.from(new Set((appData.diarySettings?.staff||[]).map(s=>String(s?.role||'').trim()).filter(Boolean).concat(['生活相談員','機能訓練指導員','看護師','介護職員','管理者'])));
  // ★ フェイスシート／基本情報から自動読込 (経緯・希望・健康状態・自立度 等)
  const _fsAuto = (p)=>{
    // ★ フェイスシートの保存先は patient.personalFile.faceSheet (patient.faceSheet は添付専用)。
    //   ここを取り違えると連携が丸ごと効かず、自立度が入らない/経緯に既往歴しか出ない等になる。
    const fs = (p?.personalFile?.faceSheet) || p?.faceSheet || {};
    const j = (...a)=>a.filter(x=>String(x||'').trim()).join('\n');
    return {
      // ★ 自立度はフェイスシートを正とする。 認知症自立度は半角(I/IIa)保存のため全角(Ⅰ/Ⅱa)へ正規化して○を合わせる
      adlLevel: normalizeAdlLevel(fs.adlLevel), demLevel: normalizeDemLevel(fs.dementiaLevel),
      keii: j(fs.lifeHistory, (fs.kiou ?? p?.kiou), fs.currentSituation),
      honninKibou: j(fs.needs),
      kazokuKibou: '',
      shakaiSanka: j(fs.hobby && `趣味・楽しみ：${fs.hobby}`, fs.personality && `性格・人柄：${fs.personality}`, fs.otherServices && `他サービスの利用：${fs.otherServices}`),
      kyotakuKankyo: j(fs.floorPlan, fs.householdType && `世帯：${fs.householdType}${fs.householdTypeOther?`（${fs.householdTypeOther}）`:''}`),
      kenkoJotai: j(fs.chronicDiseases && `主治医：${fs.chronicDiseases}`, fs.medicalInstitution && `医療機関：${fs.medicalInstitution}`, fs.medication && `服薬：${fs.medication}`),
      iryoRisk: j(p?.ryui, fs.allergies && `アレルギー：${fs.allergies}`, fs.pickupNotes && `送迎時の注意：${fs.pickupNotes}`),
    };
  };
  const newRecord = ()=>({
    id:`tk_${pid}_${Date.now()}`, patientId:pid, createdAt:Date.now(),
    createdDate:toReiwa(new Date().toISOString().slice(0,10)),
    prevDate:(records[0]?.createdDate||''), firstDate:(records[records.length-1]?.createdDate||''),
    author:'', authorJob:'生活相談員',
    ..._fsAuto(patient),
    riyoubi:_baseUseDays(patient), teikyoTime:_teikyoKubun(patient), hoshin:'',
    longSetDate:'', longDueDate:'', longGoal:'', longAchieve:'',
    shortSetDate:'', shortDueDate:'', shortGoal:'', shortAchieve:'',
    services:_defaultSvcs(),
    mukae: patient?.pickupType ? '有' : '', okuri: patient?.pickupType ? '有' : '',
    flow:_autoFlow(patient),
    tokki:'', soukatsu:'', saihyokaDate:'',
    setsumeiDate:'', setsumeisha:'', doui:'',
  });
  // ★ 旧レコード(独自レイアウト時代)を様式3-4の構造へ引き上げる。既存の入力は捨てない。
  const _migrate = (r)=>{
    const o = { ...r };
    if (!Array.isArray(o.services)) {
      const old=(r.programs||[]).filter(p=>p&&(String(p.item||'')+String(p.content||'')).trim());
      o.services = old.slice(0,5).map(p=>({ from:'', to:'',
        content:[p.item,p.content].filter(Boolean).join('：')+(p.freqWeek?`（${p.freqWeek}）`:'')+(p.time?`（${p.time}）`:''),
        jisshi:'', tassei:'', effect:'' }));
    }
    while (o.services.length < 5) o.services.push(blankSvc());
    if (!Array.isArray(o.flow) || !o.flow.length) o.flow = _defaultFlow();
    if (o.iryoRisk == null) o.iryoRisk = r.healthNote || '';
    if (o.longDueDate == null) o.longDueDate = r.longPeriod || '';
    if (o.shortDueDate == null) o.shortDueDate = r.shortPeriod || '';
    if (o.mukae == null || o.okuri == null) { const s=String(r.sougei||''); o.mukae=o.mukae??(s?'有':''); o.okuri=o.okuri??(s?'有':''); }
    ['adlLevel','demLevel','keii','shakaiSanka','kyotakuKankyo','kenkoJotai','iryoRisk','longSetDate','shortSetDate','soukatsu','saihyokaDate'].forEach(k=>{ if(o[k]==null) o[k]=''; });
    return o;
  };
  // ★ フェイスシートから再取込 (空欄のみ補完。入力済みは上書きしない)
  const importFromFaceSheet = ()=>{
    const a=_fsAuto(patient);
    const fill=Object.keys(a).filter(k=>String(a[k]||'').trim() && !String(editing?.[k]||'').trim());
    if(!fill.length){ alert('フェイスシートから補完できる空欄がありませんでした。（入力済みの欄は上書きしません）'); return; }
    setEditing(e=>{ const ne={...e}; fill.forEach(k=>{ ne[k]=a[k]; }); return ne; });
    markDirty();
  };
  // ★ プログラム(1日の流れ): 各種設定の日誌スケジュール(AM/PM)から反映
  const fillFlow = ()=>{
    const src=_flowSrc(patient);
    if(!src.length){ alert('各種設定「日誌」の1日の流れ（AM/PM）が未登録です。'); return; }
    upd({ flow: src.map(s=>({ time:s.time||'', content:s.content||'' })) });
  };
  // ★ 目標の設定日/達成予定日を「サービス提供内容①」の期間からコピーする
  // ★ 長期目標の期間(設定日〜達成予定日)を、サービス提供内容①〜⑤の期間へコピーする。
  //   計画のプログラムは目標の期間内に実施するため、目標側を正として下ろす。
  //   和暦(令和8年3月)は「○月○日」形式に落として①〜⑤の from/to に入れる。
  const _toMD = (jp)=>{ const d=parseJpDate(jp)||parseJpMonth(jp); return d ? `${d.getMonth()+1}月${d.getDate()}日` : String(jp||''); };
  const copyLongPeriodToServices = ()=>{
    const from = editing?.longSetDate, to = editing?.longDueDate;
    if(!String(from||'').trim() && !String(to||'').trim()){ alert('長期目標の設定日・達成予定日を先に入力してください。'); return; }
    if(!window.confirm('長期目標の期間を、サービス提供内容①〜⑤の期間にコピーします。よろしいですか？（各項目の内容は変わりません）')) return;
    const f=_toMD(from), t=_toMD(to);
    setEditing(e=>({ ...e, services:(e.services||[]).map(sv=>({ ...sv, from:f, to:t })) }));
    markDirty();
  };
  const upd = (patch)=>{ setEditing(e=>({...e,...patch})); markDirty(); };
  const updProg = (i,patch)=>{ setEditing(e=>({...e, programs:e.programs.map((p,idx)=>idx===i?{...p,...patch}:p)})); markDirty(); };
  const addProg = ()=>{ setEditing(e=>({...e, programs:[...(e.programs||[]), blankProg()]})); markDirty(); };
  const delProg = (i)=>{ setEditing(e=>({...e, programs:e.programs.filter((_,idx)=>idx!==i)})); markDirty(); };
  // ★ 様式3-4: サービス提供内容①〜⑤ / 1日の流れ
  const updSvc = (i,patch)=>{ setEditing(e=>({...e, services:(e.services||[]).map((s,idx)=>idx===i?{...s,...patch}:s)})); markDirty(); };
  const updFlow = (i,patch)=>{ setEditing(e=>({...e, flow:(e.flow||[]).map((s,idx)=>idx===i?{...s,...patch}:s)})); markDirty(); };
  const addFlow = ()=>{ setEditing(e=>({...e, flow:[...(e.flow||[]), {time:'',content:''}]})); markDirty(); };
  const delFlow = (i)=>{ setEditing(e=>({...e, flow:(e.flow||[]).filter((_,idx)=>idx!==i)})); markDirty(); };
  // ★ close=true: 保存して一覧へ戻る / close=false: 一時保存(編集画面は開いたまま)
  //   一時保存は「画面を戻る前に消えないよう取っておく」用途。 どちらもクラウドへ保存する。
  const saveRecord = (close=true)=>{
    if(!editing) return;
    const list=[...(appData.tsushoKeikakuRecords||[])];
    const idx=list.findIndex(r=>r.id===editing.id);
    const rec={...editing,_savedAt:syncNow()};
    if(idx>=0) list[idx]=rec; else list.push(rec);
    onSave({...appData, tsushoKeikakuRecords:list}, {manual:true, message: close ? '✓ 通所介護計画書を保存しました' : '✓ 一時保存しました'});
    if(dirtyRef) dirtyRef.current=false;
    if(close) setEditing(null);
    else setEditing(rec); // 保存済みレコードで編集を継続(以降は上書き保存になる)
  };
  React.useEffect(()=>{ if(!saveFnRef) return; saveFnRef.current=()=>{ if(editing) saveRecord(); }; });
  const delRecord=(id)=>{ if(!window.confirm('この計画書を削除します。よろしいですか？')) return; onSave({...appData, tsushoKeikakuRecords:(appData.tsushoKeikakuRecords||[]).filter(r=>r.id!==id)}, {manual:true, message:'削除しました'}); if(editing?.id===id) setEditing(null); };
  const dupRecord=(r)=>{ setEditing(_migrate({...r, id:`tk_${pid}_${Date.now()}`, createdAt:Date.now(), prevDate:r.createdDate||'', createdDate:toReiwa(new Date().toISOString().slice(0,10)), longAchieve:'', shortAchieve:'', soukatsu:'', saihyokaDate:'', setsumeiDate:'', setsumeisha:'', doui:''})); };

  // ★ 計画書連携: 個別機能訓練計画書 / 興味・関心 から取り込む
  const latestKinou=(appData.kinouKeikakuRecords||[]).filter(r=>r.patientId===pid).sort((a,b)=>String(b.createdDate||'').localeCompare(String(a.createdDate||''))||((b.createdAt||0)-(a.createdAt||0)))[0]||null;
  const latestKyomi=(appData.kyomiKanshinRecords||[]).filter(r=>r.patientId===pid).sort((a,b)=>(b.recordDate||'').localeCompare(a.recordDate||'')||((b.createdAt||0)-(a.createdAt||0)))[0]||null;
  const _appendField=(key,text)=>{ if(!text) return; setEditing(e=>{ const cur=(e[key]||'').trim(); return {...e,[key]:cur?`${cur}\n${text}`:text}; }); markDirty(); };
  const importFromKinou=()=>{
    if(!latestKinou){ if(navigateTo && window.confirm('この利用者の個別機能訓練計画書がまだありません。作成画面を開きますか？')) navigateTo('kinou_keikaku'); return; }
    const k=latestKinou;
    const sg=[k.shortKinou,k.shortKatsudo,k.shortSanka].filter(Boolean).join('／');
    const lg=[k.longKinou,k.longKatsudo,k.longSanka].filter(Boolean).join('／');
    if(!window.confirm(`個別機能訓練計画書（${k.createdDate||''}）から、本人・家族の意向／目標／機能訓練プログラムを取り込みます。よろしいですか？（空欄に反映・重複追加なし）`)) return;
    setEditing(e=>{
      const ne={...e};
      if((k.honninKibou||'').trim() && !(e.honninKibou||'').trim()) ne.honninKibou=k.honninKibou;
      if((k.kazokuKibou||'').trim() && !(e.kazokuKibou||'').trim()) ne.kazokuKibou=k.kazokuKibou;
      if(sg && !(e.shortGoal||'').trim()) ne.shortGoal=sg;
      if(lg && !(e.longGoal||'').trim()) ne.longGoal=lg;
      const kinouProgs=(k.programs||[]).filter(p=>p&&(p.content||'').trim()).map(p=>({ item:'機能訓練', content:p.content, freqWeek:p.freqWeek||'', time:p.time||'' }));
      if(kinouProgs.length){ const hasKinou=(e.programs||[]).some(p=>p.item==='機能訓練' && (p.content||'').trim()); if(!hasKinou) ne.programs=[...(e.programs||[]), ...kinouProgs]; }
      return ne;
    });
    markDirty();
  };
  const importFromKyomi=()=>{
    if(!latestKyomi){ if(navigateTo && window.confirm('この利用者の興味・関心チェックがまだありません。作成画面を開きますか？')) navigateTo('kyomi_kanshin'); return; }
    const k=latestKyomi;
    const flag=(f)=>{ const o=[]; (KYOMI_DEFAULT).forEach(n=>{ if(k.items?.[n]?.[f]) o.push(n); }); (k.custom||[]).forEach(c=>{ if(c&&c[f]&&c.name) o.push(c.name); }); return o; };
    const st=flag('shitemitai'), si=flag('shiteiru'), bikou=(k.bikou||'').trim();
    if(!st.length&&!si.length&&!bikou){ alert('取り込める項目がありませんでした。'); return; }
    if(!window.confirm('興味・関心チェックから「ご本人の希望・意向」に取り込みます。よろしいですか？（既存の下に追記）')) return;
    const kibou=[ st.length?`してみたい：${st.join('、')}`:'', si.length?`している：${si.join('、')}`:'', bikou ].filter(Boolean).join('\n');
    if(kibou) _appendField('honninKibou', kibou);
  };
  // ★ 利用予定: 基本利用日(scheduleAmPm)＋送迎時間(pickupTimes)から「曜日（区分 時間）」を組み立てて反映
  const fillRiyoubi=()=>{ const s=_baseUseDays(patient); if(!s){ alert('この利用者の基本利用日が登録されていません（利用者マスタで設定してください）。'); return; } upd({riyoubi:s}); };
  const TEIKYO_TIMES=['3時間以上4時間未満','4時間以上5時間未満','5時間以上6時間未満','6時間以上7時間未満','7時間以上8時間未満','8時間以上9時間未満'];

  const printRec = editing || records[0] || null;
  return (
    <div className="flex flex-col h-full">
      <div className="sticky top-0 z-20 bg-white border-b border-slate-200 px-4 py-2.5 flex items-center gap-3 flex-wrap">
        <KeikakuTabs current="tsusho_keikaku" navigateTo={navigateTo}/>
        <select value={pid??''} onChange={e=>{ setEditing(null); setPid(Number(e.target.value)); }} className="px-3 py-1.5 bg-slate-50 border border-slate-300 rounded-lg text-sm font-bold outline-none">
          {patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
        </select>
        <div className="flex-1"/>
        {!editing && <button onClick={()=>setEditing(newRecord())} className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-bold shadow active:scale-95">＋ 新規作成</button>}
        {editing && <>
          <button onClick={()=>{ if(dirtyRef?.current && !window.confirm('編集中の内容を破棄しますか？（一時保存すれば残せます）')) return; if(dirtyRef) dirtyRef.current=false; setEditing(null); }} className="px-4 py-2 bg-slate-200 hover:bg-slate-300 text-slate-600 rounded-lg text-sm font-bold">閉じる</button>
          <button onClick={()=>saveRecord(false)} className="px-4 py-2 bg-white border border-emerald-500 text-emerald-600 hover:bg-emerald-50 rounded-lg text-sm font-bold active:scale-95" title="編集画面を開いたまま保存します">一時保存</button>
          <button onClick={()=>saveRecord(true)} className="px-5 py-2 bg-emerald-500 hover:bg-emerald-600 text-white rounded-lg text-sm font-bold shadow active:scale-95">保存して閉じる</button>
        </>}
        {printRec && <button onClick={()=>onShowPrintPreview('通所介護計画書','A4','tk-print-area')} className="px-4 py-2 bg-slate-700 hover:bg-slate-800 text-white rounded-lg text-sm font-bold shadow active:scale-95">印刷/PDF</button>}
      </div>
      <div className="flex-1 overflow-y-auto p-4 bg-slate-50">
        {!pid ? <div className="text-center text-slate-400 py-20 font-bold">利用者を登録してください</div> : editing ? (
          <div className="max-w-4xl mx-auto space-y-4">
            <div className="bg-indigo-50 rounded-xl border border-indigo-200 p-4">
              <div className="text-sm font-bold text-indigo-700 mb-1 flex items-center gap-2">他の様式から取り込む（計画書連携）</div>
              <div className="text-[11px] text-indigo-900 opacity-70 mb-3">個別機能訓練計画書・興味関心チェックの最新内容を、この計画書の該当欄へ取り込みます（空欄に反映／追記）。</div>
              <div className="flex flex-wrap gap-2">
                <button onClick={importFromKinou} className="px-3 py-2 bg-white border border-indigo-300 text-indigo-700 rounded-lg text-xs font-bold hover:bg-indigo-100">個別機能訓練計画書から取り込む <span className="font-normal opacity-70">{latestKinou?`（${latestKinou.createdDate||''}）`:'（未作成）'}</span></button>
                <button onClick={importFromKyomi} className="px-3 py-2 bg-white border border-indigo-300 text-indigo-700 rounded-lg text-xs font-bold hover:bg-indigo-100">興味・関心から取り込む <span className="font-normal opacity-70">{latestKyomi?`（${latestKyomi.recordDate||''}）`:'（未作成）'}</span></button>
              </div>
            </div>
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="text-sm font-bold text-blue-700 mb-3">基本情報（{patient?.name} 様／{patient?.gender||''}／{_age(patient?.birthDate)}歳／{patient?.careLevel||''}）<span className="ml-2 font-normal text-[11px] text-slate-400">氏名・生年月日・要介護度は利用者マスタから自動</span></div>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                <KKDateField label="作成日" value={editing.createdDate} onChange={v=>upd({createdDate:v})}/>
                <KKDateField label="前回作成日" value={editing.prevDate} onChange={v=>upd({prevDate:v})} ph="（初回は空欄）"/>
                <KKDateField label="初回作成日" value={editing.firstDate} onChange={v=>upd({firstDate:v})}/>
                <div>
                  <label className="block text-xs font-bold text-slate-600 mb-1">計画作成者</label>
                  <input value={editing.author||''} onChange={e=>upd({author:e.target.value})} list="tk-staff-names" placeholder="職員を選択／入力" className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none"/>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-600 mb-1">職種</label>
                  <input value={editing.authorJob||''} onChange={e=>upd({authorJob:e.target.value})} list="tk-staff-roles" className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none"/>
                </div>
              </div>
              <datalist id="tk-staff-names">{_staffOpts.map(x=><option key={x} value={x}/>)}</datalist>
              <datalist id="tk-staff-roles">{_roleOpts.map(x=><option key={x} value={x}/>)}</datalist>
              <div className="grid md:grid-cols-2 gap-3 mt-3">
                <div>
                  <label className="block text-xs font-bold text-slate-600 mb-1">障害高齢者の日常生活自立度</label>
                  <div className="flex flex-wrap gap-1">{TK_ADL_OPTS.map(o=>(
                    <button key={o} onClick={()=>upd({adlLevel: editing.adlLevel===o?'':o})} className={`px-2.5 py-1 rounded border text-xs font-bold ${editing.adlLevel===o?'bg-blue-600 text-white border-blue-600':'bg-white text-slate-600 border-slate-300 hover:bg-slate-50'}`}>{o}</button>
                  ))}</div>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-600 mb-1">認知症高齢者の日常生活自立度</label>
                  <div className="flex flex-wrap gap-1">{TK_DEM_OPTS.map(o=>(
                    <button key={o} onClick={()=>upd({demLevel: editing.demLevel===o?'':o})} className={`px-2.5 py-1 rounded border text-xs font-bold ${editing.demLevel===o?'bg-blue-600 text-white border-blue-600':'bg-white text-slate-600 border-slate-300 hover:bg-slate-50'}`}>{o}</button>
                  ))}</div>
                </div>
              </div>
            </div>
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="flex items-center justify-between mb-3">
                <div className="text-sm font-bold text-blue-700">Ⅰ　利用者の基本情報</div>
                <button onClick={importFromFaceSheet} className="px-3 py-1 bg-blue-100 hover:bg-blue-200 text-blue-700 rounded text-xs font-bold">フェイスシートから空欄を補完</button>
              </div>
              <div className="space-y-3">
                <KKField label="通所介護利用までの経緯（活動歴や病歴）" value={editing.keii} onChange={v=>upd({keii:v})} rows={3}/>
                <div className="grid md:grid-cols-2 gap-3">
                  <KKField label="利用者本人の希望" value={editing.honninKibou} onChange={v=>upd({honninKibou:v})} rows={3}/>
                  <KKField label="家族の希望" value={editing.kazokuKibou} onChange={v=>upd({kazokuKibou:v})} rows={3}/>
                </div>
                <KKField label="利用者本人の社会参加の状況" value={editing.shakaiSanka} onChange={v=>upd({shakaiSanka:v})} rows={2}/>
                <KKField label="利用者の居宅の環境 ★（特によく使用する場所・使用したい場所の環境）" value={editing.kyotakuKankyo} onChange={v=>upd({kyotakuKankyo:v})} rows={2}/>
                <div className="grid md:grid-cols-2 gap-3">
                  <KKField label="健康状態 ★（病名・合併症・服薬状況等）" value={editing.kenkoJotai} onChange={v=>upd({kenkoJotai:v})} rows={3} suggestions={TPL_HEALTH}/>
                  <KKField label="ケアの上での医学的リスク ★（血圧・転倒・嚥下障害等）・留意事項" value={editing.iryoRisk} onChange={v=>upd({iryoRisk:v})} rows={3}/>
                </div>
              </div>
              <div className="text-[10px] text-slate-400 mt-2">★ = 入浴介助加算（Ⅱ）を算定する場合に記入が必要な欄</div>
            </div>
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="text-sm font-bold text-blue-700 mb-3">Ⅱ　利用目標</div>
              {[['long','長期目標',TPL_GOAL_LONG],['short','短期目標',TPL_GOAL_SHORT]].map(([k,t,tpl])=>(
                <div key={k} className="mb-3 last:mb-0">
                  <div className="flex items-center gap-2 flex-wrap mb-1">
                    <span className="text-xs font-bold text-slate-600 w-16">{t}</span>
                    <div className="flex items-center gap-1"><input value={editing[k+'SetDate']||''} onChange={e=>upd({[k+'SetDate']:e.target.value})} placeholder="設定日(例:令和7年4月)" className="px-2 py-1 border border-slate-300 rounded text-xs outline-none w-36"/><input type="date" value={(()=>{const d=parseJpDate(editing[k+'SetDate'])||parseJpMonth(editing[k+'SetDate']);return d?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`:'';})()} onChange={e=>{const v=e.target.value;upd({[k+'SetDate']:v?`令和${new Date(v).getFullYear()-2018}年${new Date(v).getMonth()+1}月${new Date(v).getDate()}日`:''});}} title="カレンダー" className="w-8 px-1 py-1 bg-slate-50 border border-slate-300 rounded text-xs cursor-pointer" style={{colorScheme:'light'}}/></div>
                    <div className="flex items-center gap-1"><input value={editing[k+'DueDate']||''} onChange={e=>upd({[k+'DueDate']:e.target.value})} placeholder="達成予定日(例:令和8年3月)" className="px-2 py-1 border border-slate-300 rounded text-xs outline-none w-40"/><input type="date" value={(()=>{const d=parseJpDate(editing[k+'DueDate'])||parseJpMonth(editing[k+'DueDate']);return d?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`:'';})()} onChange={e=>{const v=e.target.value;upd({[k+'DueDate']:v?`令和${new Date(v).getFullYear()-2018}年${new Date(v).getMonth()+1}月${new Date(v).getDate()}日`:''});}} title="カレンダー" className="w-8 px-1 py-1 bg-slate-50 border border-slate-300 rounded text-xs cursor-pointer" style={{colorScheme:'light'}}/></div>
                    {k==='long' && <button onClick={copyLongPeriodToServices} className="px-2 py-1 bg-blue-100 hover:bg-blue-200 text-blue-700 rounded text-[11px] font-bold whitespace-nowrap">期間を①〜⑤へコピー</button>}
                    <span className="text-[11px] text-slate-400 ml-1">達成度</span>
                    {TK_ACHIEVE.map(o=>(
                      <button key={o} onClick={()=>upd({[k+'Achieve']: editing[k+'Achieve']===o?'':o})} className={`px-2.5 py-1 rounded border text-xs font-bold ${editing[k+'Achieve']===o?'bg-emerald-500 text-white border-emerald-500':'bg-white text-slate-600 border-slate-300 hover:bg-slate-50'}`}>{o}</button>
                    ))}
                  </div>
                  <KKField label="" value={editing[k+'Goal']} onChange={v=>upd({[k+'Goal']:v})} rows={2} suggestions={tpl}/>
                </div>
              ))}
            </div>
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="text-sm font-bold text-blue-700 mb-1">Ⅱ　サービス提供内容（①〜⑤）</div>
              <div className="text-[11px] text-slate-400 mb-3">長期・短期目標を達成するために必要なプログラムを具体的に設定してください。</div>
              <div className="space-y-3">
                {(editing.services||[]).map((sv,i)=>(
                  <div key={i} className="bg-slate-50 rounded-lg p-3 border border-slate-200">
                    <div className="flex items-center gap-2 mb-2 flex-wrap">
                      <span className="text-base font-bold text-blue-700">{TK_MARU[i]}</span>
                      <input value={sv.from||''} onChange={e=>updSvc(i,{from:e.target.value})} placeholder="○月○日" className="px-2 py-1 bg-white border border-slate-300 rounded text-xs outline-none w-20"/>
                      <input type="date" value={(()=>{const d=parseJpDate(sv.from);return d?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`:'';})()} onChange={e=>{const v=e.target.value;updSvc(i,{from:v?`${new Date(v).getMonth()+1}月${new Date(v).getDate()}日`:''});}} title="カレンダー" className="w-8 px-1 py-1 bg-slate-50 border border-slate-300 rounded text-xs cursor-pointer" style={{colorScheme:'light'}}/>
                      <span className="text-xs text-slate-400">〜</span>
                      <input value={sv.to||''} onChange={e=>updSvc(i,{to:e.target.value})} placeholder="○月○日" className="px-2 py-1 bg-white border border-slate-300 rounded text-xs outline-none w-20"/>
                      <input type="date" value={(()=>{const d=parseJpDate(sv.to);return d?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`:'';})()} onChange={e=>{const v=e.target.value;updSvc(i,{to:v?`${new Date(v).getMonth()+1}月${new Date(v).getDate()}日`:''});}} title="カレンダー" className="w-8 px-1 py-1 bg-slate-50 border border-slate-300 rounded text-xs cursor-pointer" style={{colorScheme:'light'}}/>
                    </div>
                    <KKField label="目的とケアの提供方針・内容" value={sv.content} onChange={v=>updSvc(i,{content:v})} rows={2}/>
                    <div className="grid md:grid-cols-3 gap-3 mt-2">
                      <div>
                        <label className="block text-[11px] font-bold text-slate-500 mb-1">評価：実施</label>
                        <div className="flex gap-1">{TK_JISSHI.map(o=>(
                          <button key={o} onClick={()=>updSvc(i,{jisshi: sv.jisshi===o?'':o})} className={`px-2 py-1 rounded border text-[11px] font-bold ${sv.jisshi===o?'bg-blue-600 text-white border-blue-600':'bg-white text-slate-600 border-slate-300 hover:bg-slate-100'}`}>{o}</button>
                        ))}</div>
                      </div>
                      <div>
                        <label className="block text-[11px] font-bold text-slate-500 mb-1">評価：達成</label>
                        <div className="flex gap-1">{TK_TASSEI.map(o=>(
                          <button key={o} onClick={()=>updSvc(i,{tassei: sv.tassei===o?'':o})} className={`px-2 py-1 rounded border text-[11px] font-bold ${sv.tassei===o?'bg-emerald-500 text-white border-emerald-500':'bg-white text-slate-600 border-slate-300 hover:bg-slate-100'}`}>{o}</button>
                        ))}</div>
                      </div>
                      <KKField label="効果、満足度など" value={sv.effect} onChange={v=>updSvc(i,{effect:v})} rows={1}/>
                    </div>
                  </div>
                ))}
              </div>
            </div>
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
                <div className="text-sm font-bold text-blue-700">プログラム（1日の流れ）・送迎</div>
                <div className="flex gap-2">
                  <button onClick={fillFlow} className="px-3 py-1 bg-blue-100 hover:bg-blue-200 text-blue-700 rounded text-xs font-bold">各種設定の1日の流れから反映</button>
                  <button onClick={addFlow} className="px-3 py-1 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded text-xs font-bold">＋ 行追加</button>
                </div>
              </div>
              <div className="flex flex-wrap gap-4 mb-3">
                {[['mukae','迎え'],['okuri','送り']].map(([k,t])=>(
                  <div key={k} className="flex items-center gap-2">
                    <span className="text-xs font-bold text-slate-600">{t}</span>
                    {TK_UMU.map(o=>(
                      <button key={o} onClick={()=>upd({[k]: editing[k]===o?'':o})} className={`px-3 py-1 rounded border text-xs font-bold ${editing[k]===o?'bg-blue-600 text-white border-blue-600':'bg-white text-slate-600 border-slate-300 hover:bg-slate-50'}`}>{o}</button>
                    ))}
                  </div>
                ))}
              </div>
              <div className="grid grid-cols-12 gap-2 text-[10px] font-bold text-slate-400 px-1 mb-1">
                <div className="col-span-3">予定時間</div><div className="col-span-8">サービス内容</div><div className="col-span-1"></div>
              </div>
              <div className="space-y-1.5">
                {(editing.flow||[]).map((f,i)=>(
                  <div key={i} className="grid grid-cols-12 gap-2 items-center">
                    <input value={f.time||''} onChange={e=>updFlow(i,{time:e.target.value})} placeholder="9:00" className="col-span-3 px-2 py-1.5 bg-white border border-slate-300 rounded text-xs outline-none"/>
                    <input value={f.content||''} onChange={e=>updFlow(i,{content:e.target.value})} placeholder="内容" className="col-span-8 px-2 py-1.5 bg-white border border-slate-300 rounded text-xs outline-none"/>
                    <button onClick={()=>delFlow(i)} className="col-span-1 text-red-500 hover:text-red-700 text-xs font-bold">削除</button>
                  </div>
                ))}
              </div>
            </div>
            <div className="bg-white rounded-xl border border-slate-200 p-4">
              <div className="flex items-center justify-between mb-3">
                <div className="text-sm font-bold text-blue-700">利用予定（特記事項に印字されます）</div>
                <button onClick={fillRiyoubi} className="px-3 py-1 bg-blue-100 hover:bg-blue-200 text-blue-700 rounded text-xs font-bold">基本利用日から反映</button>
              </div>
              <div className="grid md:grid-cols-2 gap-3">
                <KKField label="利用曜日・時間帯" value={editing.riyoubi} onChange={v=>upd({riyoubi:v})} rows={2} ph="例: 月（AM 09:00）・水（1日）"/>
                <div>
                  <label className="block text-xs font-bold text-slate-600 mb-1">提供時間区分</label>
                  <input value={editing.teikyoTime||''} onChange={e=>upd({teikyoTime:e.target.value})} list="tsusho-teikyo-times" placeholder="例: 3時間以上4時間未満" className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none"/>
                  <datalist id="tsusho-teikyo-times">{TEIKYO_TIMES.map(x=><option key={x} value={x}/>)}</datalist>
                </div>
              </div>
            </div>
            <div className="bg-white rounded-xl border border-slate-200 p-4 space-y-3">
              <KKField label="特記事項" value={editing.tokki} onChange={v=>upd({tokki:v})} rows={3}/>
              <div>
                <div className="flex items-center gap-2 mb-1">
                  <label className="text-xs font-bold text-slate-600">実施後の変化（総括）</label>
                  <div className="flex items-center gap-1"><input value={editing.saihyokaDate||''} onChange={e=>upd({saihyokaDate:e.target.value})} placeholder="再評価日(令和○年○月○日)" className="px-2 py-1 border border-slate-300 rounded text-xs outline-none w-44"/><input type="date" value={(()=>{const d=parseJpDate(editing.saihyokaDate);return d?`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`:'';})()} onChange={e=>{const v=e.target.value;upd({saihyokaDate:v?`令和${new Date(v).getFullYear()-2018}年${new Date(v).getMonth()+1}月${new Date(v).getDate()}日`:''});}} title="カレンダーで選ぶ" className="w-8 px-1 py-1 bg-slate-50 border border-slate-300 rounded text-xs cursor-pointer" style={{colorScheme:'light'}}/></div>
                </div>
                <KKField label="" value={editing.soukatsu} onChange={v=>upd({soukatsu:v})} rows={3}/>
              </div>
            </div>
            <div className="bg-white rounded-xl border border-slate-200 p-4 grid grid-cols-2 gap-3">
              <div>
                <label className="block text-xs font-bold text-slate-600 mb-1">説明者</label>
                <select value={editing.setsumeisha||''} onChange={e=>upd({setsumeisha:e.target.value})} className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none">
                  <option value="">（選択してください）</option>
                  {_staffOpts.map(x=><option key={x} value={x}>{x}</option>)}
                  {editing.setsumeisha && !_staffOpts.includes(editing.setsumeisha) && <option value={editing.setsumeisha}>{editing.setsumeisha}</option>}
                </select>
              </div>
              <KKDateField label="説明・同意日" value={editing.setsumeiDate} onChange={v=>upd({setsumeiDate:v})}/>
            </div>
          </div>
        ) : (
          <div className="max-w-3xl mx-auto">
            {records.length===0 ? (
              <div className="text-center text-slate-400 py-16">
                <div className="font-bold mb-2">{patient?.name} 様の通所介護計画書はまだありません</div>
                <button onClick={()=>setEditing(newRecord())} className="px-5 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-bold shadow">＋ 新規作成</button>
              </div>
            ) : (
              <div className="space-y-2">
                {records.length>=2 && (
                  <div className="bg-white rounded-xl border border-slate-200 p-4 mb-1">
                    <div className="text-sm font-bold text-blue-700 mb-2">目標の推移（見直し比較・新しい順）</div>
                    <div className="overflow-x-auto">
                      <table className="w-full text-xs border-collapse whitespace-pre-wrap">
                        <thead><tr className="bg-slate-50 text-slate-500"><th className="border border-slate-200 px-2 py-1 text-left w-24">作成日</th><th className="border border-slate-200 px-2 py-1 text-left">短期目標</th><th className="border border-slate-200 px-2 py-1 w-14">達成</th><th className="border border-slate-200 px-2 py-1 text-left">長期目標</th><th className="border border-slate-200 px-2 py-1 w-14">達成</th></tr></thead>
                        <tbody>
                          {records.slice(0,4).map((r,i)=>(
                            <tr key={r.id} className={i===0?'bg-emerald-50':''}>
                              <td className="border border-slate-200 px-2 py-1 font-bold text-slate-700 align-top">{r.createdDate||'—'}{i===0&&<span className="ml-1 text-[9px] text-emerald-600">最新</span>}</td>
                              <td className="border border-slate-200 px-2 py-1 align-top">{r.shortGoal||'—'}</td>
                              <td className="border border-slate-200 px-2 py-1 text-center align-top">{r.shortAchieve||'—'}</td>
                              <td className="border border-slate-200 px-2 py-1 align-top">{r.longGoal||'—'}</td>
                              <td className="border border-slate-200 px-2 py-1 text-center align-top">{r.longAchieve||'—'}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}
                {records.map(r=>(
                  <div key={r.id} className="bg-white rounded-xl border border-slate-200 p-4 flex items-center justify-between gap-3">
                    <div>
                      <div className="font-bold text-slate-800">作成日: {r.createdDate}{r.author?`／作成者: ${r.author}`:''}</div>
                      <div className="text-xs text-slate-500 mt-0.5 truncate" style={{maxWidth:420}}>短期目標: {r.shortGoal||'（未入力）'}</div>
                    </div>
                    <div className="flex gap-2 shrink-0">
                      <button onClick={()=>setEditing(_migrate(r))} className="px-3 py-1.5 bg-blue-100 hover:bg-blue-200 text-blue-700 rounded-lg text-xs font-bold">編集</button>
                      <button onClick={()=>dupRecord(r)} className="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-lg text-xs font-bold">複製して更新</button>
                      <button onClick={()=>delRecord(r.id)} className="px-3 py-1.5 bg-red-50 hover:bg-red-100 text-red-600 rounded-lg text-xs font-bold">削除</button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
      {printRec && (() => {
        // ★ 別紙様式３－４ 準拠のA4 1枚。flex比率で縦を配分し、下部に余白が残らないようにする。
        // 一覧から直接印刷する旧レコードも様式3-4の構造へ引き上げてから描画する
        const rec = _migrate(printRec);
        const esc=(s)=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
        const B='1px solid #000';
        // cs=利用者入力を出す枠(pre-wrapで改行保持) / csm=HTMLを組むだけの枠
        //   ※ csm を使わずにHTMLを複数行で書くと pre-wrap が改行とインデントを空白として描画し、行が異常に高くなる
        const cs=`border:${B};padding:2px 4px;vertical-align:top;white-space:pre-wrap;font-size:9px;word-break:break-word;line-height:1.4;`;
        const csm=cs.replace('white-space:pre-wrap;','');
        const lab=csm+'background:#f2f2f2;font-weight:bold;text-align:center;vertical-align:middle;white-space:nowrap;';
        const cap='display:block;font-size:7.5px;font-weight:bold;margin-bottom:1px;line-height:1.25;';
        const cg=(...w)=>`<colgroup>${w.map(x=>`<col style="width:${x}%"/>`).join('')}</colgroup>`;
        const circ=(v,sel)=> String(sel||'').trim()===String(v)
          ? `<span style="display:inline-block;border:1.2px solid #000;border-radius:50%;padding:0 2px;min-width:10px;text-align:center;font-weight:bold;">${esc(v)}</span>`
          : `<span style="display:inline-block;padding:0 2px;min-width:10px;text-align:center;">${esc(v)}</span>`;
        // --- ヘッダ ---
        const hdr1=`<table style="width:100%;border-collapse:collapse;table-layout:fixed;">${cg(34,33,33)}<tr>`
          +`<td style="${csm}">作成日：　${esc(rec.createdDate)||'　　　年　　月　　日'}</td>`
          +`<td style="${csm}">前回作成日：　${esc(rec.prevDate)||'　　　年　　月　　日'}</td>`
          +`<td style="${csm}">初回作成日：　${esc(rec.firstDate)||'　　　年　　月　　日'}</td>`
          +`</tr></table>`;
        const _bd=patient?.birthDate?new Date(patient.birthDate):null;
        const _bdOk=_bd&&!isNaN(_bd.getTime());
        const _era=_bdOk?(_bd.getFullYear()<1926?'大正':'昭和'):'';
        const _eraY=_bdOk?(_era==='大正'?_bd.getFullYear()-1911:_bd.getFullYear()-1925):'';
        const hdr2=`<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin-top:-1px;">${cg(26,6,26,10,32)}<tr>`
          +`<td style="${csm}padding:0;vertical-align:middle;"><div style="font-size:7px;padding:0 4px;border-bottom:1px dotted #999;line-height:1.5;">ふりがな　${esc(patient?.kana||'')}</div><div style="font-size:11px;font-weight:bold;padding:1px 4px;line-height:1.5;">氏　名　${esc(patient?.name||'')}</div></td>`
          +`<td style="${csm}text-align:center;vertical-align:middle;line-height:1.3;"><div style="font-size:7px;">性別</div><div style="font-size:10px;font-weight:bold;">${esc(patient?.gender||'')}</div></td>`
          +`<td style="${csm}text-align:center;vertical-align:middle;font-size:9px;line-height:1.4;"><div>${circ('大正',_era)}　/　${circ('昭和',_era)}</div><div>${_eraY||'　　'}年　${_bdOk?_bd.getMonth()+1:'　　'}月　${_bdOk?_bd.getDate():'　　'}日生　${_age(patient?.birthDate)!==''?_age(patient?.birthDate):'　　'}歳</div></td>`
          +`<td style="${csm}text-align:center;vertical-align:middle;line-height:1.3;"><div style="font-size:7px;">要介護度</div><div style="font-size:10px;font-weight:bold;">${esc(patient?.careLevel||'')}</div></td>`
          +`<td style="${csm}font-size:9px;vertical-align:middle;line-height:1.6;"><div>計画作成者：${esc(rec.author)}</div><div>職種：${esc(rec.authorJob)}</div></td>`
          +`</tr></table>`;
        const hdr3=`<table style="width:100%;border-collapse:collapse;table-layout:fixed;margin-top:-1px;">${cg(50,50)}<tr>`
          +`<td style="${csm}font-size:8.5px;text-align:center;">障害高齢者の日常生活自立度:　${TK_ADL_OPTS.map(o=>circ(o,rec.adlLevel)).join(' ')}</td>`
          +`<td style="${csm}font-size:8.5px;text-align:center;">認知症高齢者の日常生活自立度:　${TK_DEM_OPTS.map(o=>circ(o,rec.demLevel)).join(' ')}</td>`
          +`</tr></table>`;
        // --- Ⅰ 利用者の基本情報 ---
        const sec1=`<table style="width:100%;height:100%;border-collapse:collapse;table-layout:fixed;">${cg(50,50)}`
          +`<tr style="height:23%"><td style="${cs}" colspan="2"><span style="${cap}">通所介護利用までの経緯(活動歴や病歴)</span>${esc(rec.keii)}</td></tr>`
          +`<tr style="height:22%"><td style="${cs}"><span style="${cap}">利用者本人の希望</span>${esc(rec.honninKibou)}</td><td style="${cs}"><span style="${cap}">家族の希望</span>${esc(rec.kazokuKibou)}</td></tr>`
          +`<tr style="height:16%"><td style="${cs}" colspan="2"><span style="${cap}">利用者本人の社会参加の状況</span>${esc(rec.shakaiSanka)}</td></tr>`
          +`<tr style="height:17%"><td style="${cs}" colspan="2"><span style="${cap}">利用者の居宅の環境（利用者の居宅での生活状況をふまえ、特によく使用する場所・使用したいと考えている場所の環境を記入）★</span>${esc(rec.kyotakuKankyo)}</td></tr>`
          +`<tr style="height:22%"><td style="${cs}"><span style="${cap}">健康状態(病名､合併症(心疾患､呼吸器疾患等)､服薬状況等)★</span>${esc(rec.kenkoJotai)}</td><td style="${cs}"><span style="${cap}">ケアの上での医学的リスク(血圧､転倒､嚥下障害等)･留意事項★</span>${esc(rec.iryoRisk)}</td></tr>`
          +`</table>`;
        // --- Ⅱ 利用目標 (固定ラベル列は細く、入力欄=利用目標を最大化) ---
        const goalRow=(t,setD,dueD,goal,ach)=>`<tr>`
          +`<td style="${lab}font-size:8.5px;">${t}<br/>目標</td>`
          +`<td style="${csm}font-size:7.5px;vertical-align:middle;line-height:1.5;"><div>設定日　${esc(setD)||'　　年　　月'}</div><div>達成予定日　${esc(dueD)||'　　年　　月'}</div></td>`
          +`<td style="${cs}">${esc(goal)}</td>`
          +`<td style="${lab}font-size:8px;">目標<br/>達成度</td>`
          +`<td style="${csm}text-align:center;vertical-align:middle;font-size:8px;">${TK_ACHIEVE.map(o=>circ(o,ach)).join('・')}</td>`
          +`</tr>`;
        const goalTbl=`<table style="width:100%;height:100%;border-collapse:collapse;table-layout:fixed;">${cg(5,12,67,6,10)}`
          +`<tr style="height:1px;"><td colspan="5" style="${lab}font-size:9px;">利用目標</td></tr>`
          +goalRow('長期',rec.longSetDate,rec.longDueDate,rec.longGoal,rec.longAchieve)
          +goalRow('短期',rec.shortSetDate,rec.shortDueDate,rec.shortGoal,rec.shortAchieve)
          +`</table>`;
        // --- Ⅱ サービス提供内容 (①〜⑤ × 評価3段 + 右列に1日の流れ) ---
        const _svcs=[...(rec.services||[])].slice(0,5);
        while(_svcs.length<5) _svcs.push({from:'',to:'',content:'',jisshi:'',tassei:'',effect:''});
        const _flow=(rec.flow||[]).filter(f=>f&&(String(f.time||'')+String(f.content||'')).trim());
        const flowTbl=`<table style="width:100%;height:100%;border-collapse:collapse;table-layout:fixed;">${cg(40,60)}`
          +`<tr><td colspan="2" style="${lab}font-size:8.5px;border-top:none;">プログラム（1日の流れ）</td></tr>`
          +`<tr><td style="${lab}font-size:7.5px;">(予定時間)</td><td style="${lab}font-size:7.5px;">(ｻｰﾋﾞｽ内容)</td></tr>`
          +_flow.map(f=>`<tr><td style="${csm}font-size:7px;text-align:center;line-height:1.3;">${esc(f.time)}</td><td style="${csm}font-size:7px;line-height:1.3;">${esc(f.content)}</td></tr>`).join('')
          +`<tr style="height:100%"><td style="${csm}"></td><td style="${csm}"></td></tr>`
          +`</table>`;
        let svcRows=`<tr>`
          +`<td style="${lab}" colspan="2" rowspan="2">目的とケアの提供方針・内容</td>`
          +`<td style="${lab}" colspan="3">評価</td>`
          +`<td style="${lab}font-size:8.5px;" rowspan="2">迎え（${circ('有',rec.mukae)}・${circ('無',rec.mukae)}）</td>`
          +`</tr><tr>`
          +`<td style="${lab}font-size:7.5px;">実施</td>`
          +`<td style="${lab}font-size:7.5px;">達成</td>`
          +`<td style="${lab}font-size:8px;">効果、満足度など</td>`
          +`</tr>`;
        _svcs.forEach((s,i)=>{
          for(let k=0;k<3;k++){
            let tr='<tr>';
            if(k===0){
              tr+=`<td style="${lab}background:#fff;font-weight:normal;font-size:11px;" rowspan="3">${TK_MARU[i]}</td>`;
              tr+=`<td style="${cs}" rowspan="3"><div style="font-size:8px;border-bottom:1px dotted #bbb;padding-bottom:1px;margin-bottom:2px;">${esc(s.from)||'　　月　　日'}　～　${esc(s.to)||'　　月　　日'}</div>${esc(s.content)}</td>`;
            }
            tr+=`<td style="${csm}text-align:center;vertical-align:middle;font-size:7.5px;padding:1px;">${circ(TK_JISSHI[k],s.jisshi)}</td>`;
            tr+=`<td style="${csm}text-align:center;vertical-align:middle;font-size:7.5px;padding:1px;">${circ(TK_TASSEI[k],s.tassei)}</td>`;
            if(k===0) tr+=`<td style="${cs}" rowspan="3">${esc(s.effect)}</td>`;
            if(i===0&&k===0) tr+=`<td style="border:${B};padding:0;vertical-align:top;" rowspan="13">${flowTbl}</td>`;
            if(i===4&&k===1) tr+=`<td style="${lab}font-size:8.5px;" rowspan="2">送り（${circ('有',rec.okuri)}・${circ('無',rec.okuri)}）</td>`;
            tr+='</tr>';
            svcRows+=tr;
          }
        });
        const svcTbl=`<table style="width:100%;height:100%;border-collapse:collapse;table-layout:fixed;">${cg(4,40,5,5,21,25)}`
          +`<tr style="height:1px;"><td colspan="6" style="${lab}font-size:9px;">サービス提供内容（※）</td></tr>`
          +svcRows+`</table>`;
        // --- 特記事項 / 実施後の変化 / 説明者・同意日 ---
        // 利用予定・提供時間区分は様式3-4に専用欄が無いため、特記事項の先頭に印字する
        const _riyo=[rec.riyoubi&&`利用予定：${rec.riyoubi}`, rec.teikyoTime&&`提供時間区分：${rec.teikyoTime}`].filter(Boolean).join('　／　');
        const _tokki=[_riyo, String(rec.tokki||'')].filter(s=>String(s).trim()).join('\n');
        const douiTbl=`<table style="width:100%;border-collapse:collapse;table-layout:fixed;">${cg(50,50)}`
          +`<tr><td colspan="2" style="${lab}font-size:8.5px;">利用者・家族に対する本計画の説明者及び同意日</td></tr>`
          +`<tr><td style="${lab}font-size:8.5px;">説明者</td><td style="${lab}font-size:8.5px;">説明・同意日</td></tr>`
          +`<tr><td style="${csm}text-align:center;vertical-align:middle;height:9mm;font-size:10px;">${esc(rec.setsumeisha)}</td><td style="${csm}text-align:center;vertical-align:middle;font-size:9px;">${esc(rec.setsumeiDate)||'　　年　　月　　日'}</td></tr>`
          +`</table>`;
        const bottom=`<table style="width:100%;height:100%;border-collapse:collapse;table-layout:fixed;">${cg(53,47)}`
          +`<tr style="height:44%">`
          +`<td style="${cs}"><span style="${cap}">特記事項</span>${esc(_tokki)}</td>`
          +`<td style="padding:1px 4px;font-size:7px;line-height:1.35;vertical-align:top;">※サービス提供内容の設定にあたっては、長期目標・短期目標として設定した目標を達成するために必要なプログラムとなるよう、具体的に設定すること。<br/>※入浴介助加算（Ⅱ）を算定する場合は、★が記載された欄等において必要な情報を記入すること。</td>`
          +`</tr><tr style="height:56%">`
          +`<td style="${cs}"><span style="${cap}">実施後の変化(総括)　　再評価日：　${esc(rec.saihyokaDate)||'　　　年　　月　　日'}</span>${esc(rec.soukatsu)}</td>`
          +`<td style="padding:0;vertical-align:bottom;">${douiTbl}</td>`
          +`</tr></table>`;
        const _fzip=facility.zip||facility.zipCode||'';
        const _fno=facility.jigyoshoNo||facility.officeNo||'';
        const _fmgr=facility.manager||[facility.managerLast,facility.managerFirst].filter(Boolean).join(' ')||'';
        const _faddr=[facility.address,facility.addressBuilding].filter(Boolean).join('');
        const footer=`<div style="flex:0 0 auto;border:${B};padding:2px 5px;font-size:8.5px;line-height:1.55;margin-top:1mm;">`
          +`<div>（地域密着型）通所介護　${esc(facility.name)||'　　　　'}　　　${_fzip?'〒'+esc(_fzip):''}　住所：${esc(_faddr)}　　　管理者：${esc(_fmgr)}</div>`
          +`<div>　事業所No.${esc(_fno)}　　　　　　　　　Tel.${esc(facility.phone)}/Fax.${esc(facility.fax)}</div>`
          +`</div>`;
        const html=`<div style="width:210mm;height:297mm;padding:6mm 5mm 4mm;box-sizing:border-box;display:flex;flex-direction:column;font-family:'Hiragino Sans','Yu Gothic','MS PGothic',sans-serif;color:#000;background:#fff;overflow:hidden;">`
          +`<div style="flex:0 0 auto;font-size:9px;font-weight:bold;">別紙様式３－４</div>`
          +`<div style="flex:0 0 auto;text-align:center;font-size:13px;font-weight:bold;letter-spacing:1px;margin:0.8mm 0 1.5mm;">【（地域密着型）通所介護計画書】</div>`
          +`<div style="flex:0 0 auto;">${hdr1}${hdr2}${hdr3}</div>`
          +`<div style="flex:0 0 auto;font-size:9.5px;font-weight:bold;margin:1.6mm 0 0.6mm;border-bottom:1px solid #000;">Ⅰ　利用者の基本情報</div>`
          +`<div style="flex:92 1 0;min-height:0;">${sec1}</div>`
          +`<div style="flex:0 0 auto;font-size:9.5px;font-weight:bold;margin:1.6mm 0 0.6mm;border-bottom:1px solid #000;">Ⅱ　サービス利用目標・サービス提供内容の設定</div>`
          +`<div style="flex:28 1 0;min-height:0;">${goalTbl}</div>`
          +`<div style="flex:152 1 0;min-height:0;margin-top:1.2mm;">${svcTbl}</div>`
          +`<div style="flex:52 1 0;min-height:0;margin-top:1.2mm;">${bottom}</div>`
          +footer
          +`</div>`;
        return <div id="tk-print-area" style={{display:'none'}} dangerouslySetInnerHTML={{__html:html}}/>;
      })()}
    </div>
  );
}

// === LIFE・加算 共通ハブ (Phase1: ADL評価=Barthel Index。3加算が共有する土台) ===
// Barthel Index: 10項目・各固定配点・合計0〜100点。科学的介護推進体制加算/ADL維持等加算/個別機能訓練加算Ⅱ で共通利用。
const BARTHEL_ITEMS = [
  { key:'eat',      label:'食事',                 opts:[[10,'自立'],[5,'一部介助'],[0,'全介助']] },
  { key:'transfer', label:'移乗（ベッド⇔車椅子）', opts:[[15,'自立'],[10,'軽介助・監視'],[5,'座位可・多介助'],[0,'全介助']] },
  { key:'groom',    label:'整容',                 opts:[[5,'自立'],[0,'介助']] },
  { key:'toilet',   label:'トイレ動作',           opts:[[10,'自立'],[5,'一部介助'],[0,'全介助']] },
  { key:'bath',     label:'入浴',                 opts:[[5,'自立'],[0,'介助']] },
  { key:'walk',     label:'歩行（平地45m）',       opts:[[15,'自立'],[10,'介助歩行'],[5,'車椅子操作可'],[0,'全介助']] },
  { key:'stairs',   label:'階段昇降',             opts:[[10,'自立'],[5,'介助・監視'],[0,'不能']] },
  { key:'dress',    label:'更衣',                 opts:[[10,'自立'],[5,'一部介助'],[0,'全介助']] },
  { key:'stool',    label:'排便コントロール',      opts:[[10,'失禁なし'],[5,'時に失禁'],[0,'失禁あり']] },
  { key:'urine',    label:'排尿コントロール',      opts:[[10,'失禁なし'],[5,'時に失禁'],[0,'失禁あり']] },
];
const barthelTotal = (items) => BARTHEL_ITEMS.reduce((s,it)=>s+(Number(items?.[it.key])||0), 0);

// ★ 生活機能チェック(様式3-2)のADL → Barthel の点数へ変換する対応表。
//   同じ10項目を二度入力しているため、生活機能チェックから点数を「自動提案」できるようにする。
//   ★ あくまで提案値。 段階数も配点も項目ごとに違い(食事は3段階/移乗は4段階)、
//     「見守り」に完全に対応する選択肢が無い項目もあるため、最終判断は職員が行う前提。
//   SEIKATSU_ADL の並び順と BARTHEL_ITEMS の並び順は一致している(食事/移乗/整容/トイレ動作/
//   入浴/歩行/階段昇降/更衣/排便管理/排尿管理)。
const SEIKATSU_TO_BARTHEL_KEY = { '食事':'eat','移乗':'transfer','整容':'groom','トイレ動作':'toilet','入浴':'bath','歩行':'walk','階段昇降':'stairs','更衣':'dress','排便管理':'stool','排尿管理':'urine' };
const SEIKATSU_TO_BARTHEL_SCORE = {
  //           自立  見守り 一部介助 全介助
  eat:      { '自立':10, '見守り':5,  '一部介助':5,  '全介助':0 },
  transfer: { '自立':15, '見守り':10, '一部介助':5,  '全介助':0 }, // 見守り=軽介助・監視(10)
  groom:    { '自立':5,  '見守り':0,  '一部介助':0,  '全介助':0 }, // 2段階のみ
  toilet:   { '自立':10, '見守り':5,  '一部介助':5,  '全介助':0 },
  bath:     { '自立':5,  '見守り':0,  '一部介助':0,  '全介助':0 }, // 2段階のみ
  walk:     { '自立':15, '見守り':10, '一部介助':10, '全介助':0 }, // 見守り/一部介助=介助歩行(10)
  stairs:   { '自立':10, '見守り':5,  '一部介助':5,  '全介助':0 },
  dress:    { '自立':10, '見守り':5,  '一部介助':5,  '全介助':0 },
  stool:    { '自立':10, '見守り':5,  '一部介助':5,  '全介助':0 }, // 失禁なし/時に失禁/失禁あり
  urine:    { '自立':10, '見守り':5,  '一部介助':5,  '全介助':0 },
};
// 生活機能チェックの adl マップ → Barthel の items マップ。 未選択(空)の項目は含めない。
const seikatsuAdlToBarthel = (adlMap) => {
  const out = {};
  Object.keys(SEIKATSU_TO_BARTHEL_KEY).forEach(label => {
    const v = String((adlMap || {})[label] || '').trim();
    if (!v) return;
    const key = SEIKATSU_TO_BARTHEL_KEY[label];
    const sc = SEIKATSU_TO_BARTHEL_SCORE[key]?.[v];
    if (sc != null) out[key] = sc;
  });
  return out;
};
function LifeHubView({ appData, onSave, navigateTo, targetPatientId, dirtyRef, saveFnRef }) {
  const markDirty = () => { if (dirtyRef) dirtyRef.current = true; };
  const patients = sortPatientsByKana((appData.patients||[]).filter(p => p.status==='利用中' || p.status==='休止'));
  const [pid, setPid] = React.useState((targetPatientId!=null && (appData.patients||[]).some(p=>p.id===targetPatientId)) ? targetPatientId : (patients[0]?.id ?? null));
  const patient = (appData.patients||[]).find(p => p.id === pid);
  const addons = appData.systemSettings?.addons || {};
  const _age = (bd)=>{ if(!bd) return ''; const d=new Date(bd),n=new Date(); let a=n.getFullYear()-d.getFullYear(); if(n.getMonth()<d.getMonth()||(n.getMonth()===d.getMonth()&&n.getDate()<d.getDate()))a--; return a; };
  const today = new Date().toISOString().slice(0,10);
  const adlRecords = (appData.adlRecords||[]).filter(r => r.patientId===pid).sort((a,b)=>(b.evalDate||'').localeCompare(a.evalDate||''));
  const [editing, setEditing] = React.useState(null);
  const blank = () => ({ id:`adl_${pid}_${Date.now()}`, patientId:pid, evalDate:today, evaluator:'', items:{}, note:'' });
  const setItem = (k,v)=>{ setEditing(e=>({...e, items:{...e.items,[k]:Number(v)}})); markDirty(); };
  // ★ 生活機能チェック(3-2)のADLから Barthel の点数を「提案」する。 同じ10項目を二度入力しないため。
  //   あくまで候補として入れるだけで、保存は職員が内容を確認してから行う。
  const latestSeikatsu = (appData.seikatsuKinouRecords||[])
    .filter(r => r && r.patientId === pid)
    .sort((a,b) => String(b.recordDate||'').localeCompare(String(a.recordDate||'')) || ((b.createdAt||0)-(a.createdAt||0)))[0] || null;
  const importFromSeikatsu = () => {
    if (!latestSeikatsu) { alert('この利用者の生活機能チェック（様式3-2）がまだありません。'); return; }
    const sug = seikatsuAdlToBarthel(latestSeikatsu.adl);
    const n = Object.keys(sug).length;
    if (!n) { alert('生活機能チェックのADLがまだ入力されていません。'); return; }
    if (!window.confirm(`生活機能チェック（${latestSeikatsu.recordDate||''}）のADLから点数を提案します。\n${n}項目に候補を入れます。内容を確認して保存してください。\n\n※ 段階や配点が項目ごとに異なるため、あくまで目安です。`)) return;
    setEditing(e => ({ ...(e || blank()), items: { ...((e||{}).items||{}), ...sug } }));
    markDirty();
  };
  const save = () => {
    if (!editing) return;
    const rec = { ...editing, total: barthelTotal(editing.items), _savedAt: syncNow() };
    const list = [...(appData.adlRecords||[])];
    const i = list.findIndex(r=>r.id===rec.id);
    if (i>=0) list[i]=rec; else list.push(rec);
    onSave({ ...appData, adlRecords:list }, { manual:true, message:'✓ ADL評価（Barthel）を保存しました' });
    if (dirtyRef) dirtyRef.current=false;
    setEditing(null);
  };
  React.useEffect(()=>{ if(saveFnRef) saveFnRef.current = ()=>{ if(editing) save(); }; });
  const delRec = (id)=>{ if(!window.confirm('このADL評価を削除しますか？')) return; onSave({ ...appData, adlRecords:(appData.adlRecords||[]).filter(r=>r.id!==id) }, { manual:true, message:'削除しました' }); if(editing?.id===id) setEditing(null); };
  const enabledKasan = [
    ['kasan_kinou2','個別機能訓練加算Ⅱ','個別機能訓練計画（3-3/3-1/3-2）＋ADLをLIFEへ。'],
    ['kasan_kagaku','科学的介護推進体制加算','ADL・IADL・口腔・栄養・認知症・既往等の総論を6ヶ月ごとにLIFEへ。'],
    ['kasan_adl','ADL維持等加算','評価開始月と6ヶ月後のBarthelからADL利得を算定しLIFEへ。'],
  ].filter(([k])=>addons[k]);
  const curTotal = editing ? barthelTotal(editing.items) : (adlRecords[0]?.total ?? null);
  const prevTotal = editing ? (adlRecords[0]?.total ?? null) : (adlRecords[1]?.total ?? null);

  return (
    <div className="flex flex-col h-full">
      <div className="sticky top-0 z-20 bg-white border-b border-slate-200 px-4 py-2.5 flex items-center gap-3 flex-wrap">
        <select value={pid??''} onChange={e=>{ setEditing(null); setPid(Number(e.target.value)); }} className="px-3 py-1.5 bg-slate-50 border border-slate-300 rounded-lg text-sm font-bold outline-none">
          {patients.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
        </select>
        <div className="flex-1"/>
        {!editing && <button onClick={()=>setEditing(blank())} className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg text-sm font-bold shadow active:scale-95">＋ ADL評価を新規作成</button>}
        {editing && <>
          <button onClick={()=>{ if(dirtyRef?.current && !window.confirm('編集中の内容を破棄しますか？')) return; if(dirtyRef) dirtyRef.current=false; setEditing(null); }} className="px-4 py-2 bg-slate-200 hover:bg-slate-300 text-slate-600 rounded-lg text-sm font-bold">閉じる</button>
          <button onClick={save} className="px-5 py-2 bg-emerald-500 hover:bg-emerald-600 text-white rounded-lg text-sm font-bold shadow active:scale-95">保存</button>
        </>}
      </div>

      <div className="flex-1 overflow-y-auto p-4 bg-slate-50">
        {!pid ? <div className="text-center text-slate-400 py-20 font-bold">利用者を登録してください</div> : (
        <div className="max-w-4xl mx-auto space-y-4">
          {/* この店で有効な加算 */}
          <div className="bg-indigo-50 rounded-xl border border-indigo-200 p-4">
            <div className="text-sm font-bold text-indigo-700 mb-2">この事業所で算定中の加算（本部の店舗設定でON/OFF）</div>
            {enabledKasan.length===0 ? (
              <div className="text-xs text-indigo-900 opacity-70">現在ONの加算がありません。本部の「店舗設定 → アドオン」で、個別機能訓練加算Ⅱ／科学的介護推進体制加算／ADL維持等加算 を有効にしてください。</div>
            ) : (
              <div className="grid md:grid-cols-3 gap-2">
                {enabledKasan.map(([k,label,desc])=>(
                  <div key={k} className="bg-white rounded-lg border border-indigo-200 p-3">
                    <div className="text-xs font-bold text-slate-700">{label}</div>
                    <div className="text-[11px] text-slate-500 mt-1 leading-snug">{desc}</div>
                  </div>
                ))}
              </div>
            )}
            <div className="text-[11px] text-indigo-900 opacity-70 mt-2">※ 下の <b>共通データ（ADL＝Barthel Index）</b> は、上記どの加算にも自動で反映されます。各加算の固有項目は順次追加します。</div>
          </div>

          {/* 共通データ: 基本情報 */}
          <div className="bg-white rounded-xl border border-slate-200 p-4">
            <div className="text-sm font-bold text-blue-700 mb-1">共通データ ①利用者基本情報（自動）</div>
            <div className="text-sm text-slate-700">{patient?.name} 様　／　{patient?.gender||'—'}　／　{_age(patient?.birthDate)!==''?`${_age(patient?.birthDate)}歳`:'—'}　／　{patient?.careLevel||'要介護度未設定'}</div>
          </div>

          {/* 共通データ: ADL(Barthel) */}
          <div className="bg-white rounded-xl border border-slate-200 p-4">
            <div className="flex items-center justify-between mb-3 flex-wrap gap-2">
              <div className="text-sm font-bold text-blue-700">共通データ ②ADL評価（Barthel Index・0〜100点）</div>
              {curTotal!=null && <div className="text-sm font-bold text-slate-700">合計 <span className="text-xl text-emerald-600">{curTotal}</span> / 100点{prevTotal!=null && <span className={`ml-2 text-xs ${curTotal-prevTotal>0?'text-emerald-600':curTotal-prevTotal<0?'text-red-500':'text-slate-400'}`}>前回比 {curTotal-prevTotal>0?'+':''}{curTotal-prevTotal}</span>}</div>}
            </div>
            {editing ? (
              <div className="space-y-3">
                {/* ★ 生活機能チェック(3-2)と同じ10項目のため、そこから点数を提案できる(二度入力の解消)。
                    入るのは候補で、確認して保存する前提。 */}
                <div className="bg-indigo-50 rounded-xl border border-indigo-200 p-3 flex items-center gap-3 flex-wrap">
                  <div className="text-[11px] text-indigo-900 flex-1 min-w-[200px]">
                    <span className="font-bold">生活機能チェック（様式3-2）から点数を提案できます。</span>
                    <span className="opacity-70">同じ10項目を二度入力しなくて済みます。入った点数は必ず確認してから保存してください。</span>
                  </div>
                  <button onClick={importFromSeikatsu} className="px-3 py-2 bg-white border border-indigo-300 text-indigo-700 rounded-lg text-xs font-bold hover:bg-indigo-100 whitespace-nowrap">
                    生活機能チェックから取り込む <span className="font-normal opacity-70">{latestSeikatsu?`（${latestSeikatsu.recordDate||''}）`:'（未作成）'}</span>
                  </button>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                  <div><label className="block text-xs font-bold text-slate-500 mb-1">評価日</label><input type="date" value={editing.evalDate} onChange={e=>{setEditing(x=>({...x,evalDate:e.target.value}));markDirty();}} className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none"/></div>
                  <div><label className="block text-xs font-bold text-slate-500 mb-1">評価者</label><input value={editing.evaluator} onChange={e=>{setEditing(x=>({...x,evaluator:e.target.value}));markDirty();}} className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none"/></div>
                </div>
                <div className="divide-y divide-slate-100 border border-slate-200 rounded-lg">
                  {BARTHEL_ITEMS.map(it=>(
                    <div key={it.key} className="flex items-center gap-3 px-3 py-2 flex-wrap">
                      <div className="w-40 text-sm font-bold text-slate-700 shrink-0">{it.label}</div>
                      <div className="flex gap-1.5 flex-wrap">
                        {it.opts.map(([sc,lb])=>{ const on=Number(editing.items?.[it.key])===sc; return (
                          <button key={sc} onClick={()=>setItem(it.key,sc)} className={`px-2.5 py-1.5 rounded-lg text-xs font-bold border ${on?'bg-blue-600 text-white border-blue-600':'bg-white text-slate-600 border-slate-300 hover:bg-slate-100'}`}>{sc}点 {lb}</button>
                        ); })}
                      </div>
                    </div>
                  ))}
                </div>
                <div><label className="block text-xs font-bold text-slate-500 mb-1">備考</label><textarea value={editing.note} onChange={e=>{setEditing(x=>({...x,note:e.target.value}));markDirty();}} rows={2} className="w-full px-3 py-2 bg-white border border-slate-300 rounded-lg text-sm outline-none resize-none"/></div>
              </div>
            ) : adlRecords.length===0 ? (
              <div className="text-sm text-slate-400 py-6 text-center">まだADL評価がありません。「＋ ADL評価を新規作成」から入力してください。</div>
            ) : (
              <div className="space-y-3">
                {adlRecords.length>=2 && (
                  <div className="overflow-x-auto">
                    <table className="w-full text-xs border-collapse">
                      <thead><tr className="bg-slate-50 text-slate-500"><th className="border border-slate-200 px-2 py-1 text-left w-28">評価日</th><th className="border border-slate-200 px-2 py-1 w-20">合計</th>{BARTHEL_ITEMS.map(it=><th key={it.key} className="border border-slate-200 px-1 py-1">{it.label.slice(0,2)}</th>)}</tr></thead>
                      <tbody>
                        {adlRecords.slice(0,4).map((r,i)=>(
                          <tr key={r.id} className={i===0?'bg-emerald-50':''}>
                            <td className="border border-slate-200 px-2 py-1 font-bold text-slate-700">{r.evalDate}{i===0&&<span className="ml-1 text-[9px] text-emerald-600">最新</span>}</td>
                            <td className="border border-slate-200 px-2 py-1 text-center font-bold">{r.total}</td>
                            {BARTHEL_ITEMS.map(it=><td key={it.key} className="border border-slate-200 px-1 py-1 text-center text-slate-500">{r.items?.[it.key]??'—'}</td>)}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
                {adlRecords.map(r=>(
                  <div key={r.id} className="bg-slate-50 rounded-lg border border-slate-200 p-3 flex items-center justify-between gap-3">
                    <div><div className="font-bold text-slate-800 text-sm">{r.evalDate}　合計 {r.total}/100{r.evaluator?`　評価者: ${r.evaluator}`:''}</div>{r.note&&<div className="text-xs text-slate-500 mt-0.5 truncate" style={{maxWidth:420}}>{r.note}</div>}</div>
                    <div className="flex gap-2 shrink-0">
                      <button onClick={()=>setEditing(r)} className="px-3 py-1.5 bg-blue-100 hover:bg-blue-200 text-blue-700 rounded-lg text-xs font-bold">編集</button>
                      <button onClick={()=>delRec(r.id)} className="px-3 py-1.5 bg-red-50 hover:bg-red-100 text-red-600 rounded-lg text-xs font-bold">削除</button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {!editing && (
            <div className="bg-amber-50 rounded-xl border border-amber-200 p-4 text-xs text-amber-800 leading-relaxed">
              <b>次の開発予定：</b> 各加算の固有項目フォーム（科学的介護推進体制＝口腔/栄養/認知症/既往 等、ADL維持等＝利得算定、個別機能訓練Ⅱ＝計画連携）と、<b>LIFE連携CSVの書き出し</b>。CSVは公式のLIFE連携仕様に合わせて実装します（要・最新仕様確認）。
            </div>
          )}
        </div>
        )}
      </div>
    </div>
  );
}

function buildMonitoringTableHtml(patient, sheet, facility, monthLabel) {
  const f = facility || {}; const s = sheet || {};
  const cell = (v) => (v && typeof v==='object') ? v : { sel:'', text:(v!=null?String(v):'') };
  const bd = 'border:1px solid #000;';
  const fmt = (ymd) => { if(!ymd) return ''; try { return new Date(ymd).toLocaleDateString('ja-JP',{year:'numeric',month:'long',day:'numeric'}); } catch { return ymd; } };
  const rows = MON_ITEMS.map(it => { const c = cell(s[it.key]); return `<tr>
    <td style="${bd}background:#d9d9d9;padding:6px 8px;font-weight:bold;font-size:11px;width:170px;vertical-align:top;line-height:1.4;">${it.no}${it.title}<div style="font-weight:normal;font-size:9px;color:#444;margin-top:2px;">${_escMon(it.explain)}</div></td>
    <td style="${bd}padding:6px;font-size:11px;font-weight:bold;text-align:center;width:96px;vertical-align:top;">${_escMon(c.sel)||'　'}</td>
    <td style="${bd}padding:6px 9px;font-size:11px;vertical-align:top;line-height:1.6;">${_escMon(c.text)||'&nbsp;'}</td></tr>`; }).join('');
  return `<div style="font-family:'Hiragino Sans','Yu Gothic','MS PGothic',sans-serif;color:#000;background:white;">
    <div style="text-align:center;font-size:17px;font-weight:bold;margin-bottom:10px;">通所介護モニタリング表</div>
    <table style="width:100%;border-collapse:collapse;margin-bottom:6px;">
      <tr><td style="${bd}background:#f2f2f2;padding:5px 8px;font-weight:bold;font-size:11px;white-space:nowrap;">利用者名</td><td style="${bd}padding:5px 8px;font-size:11px;">${_escMon(patient.name)} 様</td>
          <td style="${bd}background:#f2f2f2;padding:5px 8px;font-weight:bold;font-size:11px;white-space:nowrap;">事業所名</td><td style="${bd}padding:5px 8px;font-size:11px;">${_escMon(f.name)||''}</td></tr>
      <tr><td style="${bd}background:#f2f2f2;padding:5px 8px;font-weight:bold;font-size:11px;">居宅介護支援事業者</td><td style="${bd}padding:5px 8px;font-size:11px;">${_escMon(patient.cmOffice)||''}</td>
          <td style="${bd}background:#f2f2f2;padding:5px 8px;font-weight:bold;font-size:11px;">担当ケアマネ</td><td style="${bd}padding:5px 8px;font-size:11px;">${_escMon(patient.cmName)||''} 様</td></tr>
      <tr><td style="${bd}background:#f2f2f2;padding:5px 8px;font-weight:bold;font-size:11px;">対象期間</td><td style="${bd}padding:5px 8px;font-size:11px;">${_escMon(monthLabel)}</td>
          <td style="${bd}background:#f2f2f2;padding:5px 8px;font-weight:bold;font-size:11px;">実施日</td><td style="${bd}padding:5px 8px;font-size:11px;">${_escMon(fmt(s.implDate))}</td></tr>
      <tr><td style="${bd}background:#f2f2f2;padding:5px 8px;font-weight:bold;font-size:11px;">実施者</td><td style="${bd}padding:5px 8px;font-size:11px;" colspan="3">${_escMon(s.recorder)||''}</td></tr>
    </table>
    <table style="width:100%;border-collapse:collapse;table-layout:fixed;">
      <tr><td style="${bd}background:#d9d9d9;padding:5px 8px;font-weight:bold;font-size:10.5px;text-align:center;width:170px;">項目</td>
          <td style="${bd}background:#d9d9d9;padding:5px 8px;font-weight:bold;font-size:10.5px;text-align:center;width:96px;">結果</td>
          <td style="${bd}background:#d9d9d9;padding:5px 8px;font-weight:bold;font-size:10.5px;text-align:center;">内容</td></tr>
      ${rows}
    </table></div>`;
}
function MonitoringSheetModal({ patient, facility, period, record, autoStatus, autoChange, autoSel, noAttendance, defaultRecorder, defaultDate, onClose, onSave, onPrint, onAiDraft, hasApiKey }) {
  const init = record?.sheet || {};
  const hasRec = !!record;
  const [implDate, setImplDate] = React.useState(init.implDate || defaultDate || '');
  const [recorder, setRecorder] = React.useState(init.recorder || defaultRecorder || '');
  // 各項目の {sel,text}。 既存記録があればそれ、無ければ自動初期値。
  const initVal = (key) => {
    if (hasRec) return _monNorm(init[key]);
    if (key==='s1') return { sel: (autoSel&&autoSel.s1) || (noAttendance ? '実施できなかった' : '実施できた'), text: autoStatus||'' };
    if (key==='s3') return { sel: '変化なし', text: autoChange||'' };
    if (key==='goal') return { sel: (autoSel&&autoSel.goal) || (noAttendance ? '評価困難' : '概ね達成'), text: noAttendance ? '当月は通所がなく評価が困難。' : '' };
    if (key==='s2') return { sel: noAttendance ? '' : '概ね満足', text: '' };
    if (key==='s4') return { sel: 'このまま継続', text: '' };
    return { sel:'', text:'' };
  };
  const [vals, setVals] = React.useState(() => { const o={}; MON_ITEMS.forEach(it=>o[it.key]=initVal(it.key)); return o; });
  const setSel = (k,v) => setVals(p=>({...p,[k]:{...p[k],sel:v}}));
  const setText = (k,v) => setVals(p=>({...p,[k]:{...p[k],text:v}}));
  const [aiLoading, setAiLoading] = React.useState(false);
  const [aiErr, setAiErr] = React.useState('');
  const runAi = async () => {
    if (!onAiDraft) return;
    setAiErr(''); setAiLoading(true);
    try {
      const out = await onAiDraft();
      setVals(prev => { const n={...prev}; MON_ITEMS.forEach(it=>{ if(out[it.key]) n[it.key] = { sel: out[it.key].sel || prev[it.key].sel, text: out[it.key].text || prev[it.key].text }; }); return n; });
    } catch(e){ setAiErr(String(e.message||e)); }
    setAiLoading(false);
  };
  const collect = () => ({ implDate, recorder, ...Object.fromEntries(MON_ITEMS.map(it=>[it.key, vals[it.key]])) });
  return ReactDOM.createPortal(
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[80] flex items-center justify-center p-0 sm:p-4">
      <div className="bg-white sm:rounded-2xl shadow-2xl w-full h-full sm:h-auto sm:max-w-2xl max-h-full sm:max-h-[92vh] flex flex-col overflow-hidden">
        <div className="px-5 py-3.5 border-b border-slate-200 bg-slate-50 flex items-center justify-between shrink-0">
          <div className="font-bold text-slate-800"><ClipboardList size={18} className="inline mr-1.5 text-sky-600"/>通所介護モニタリング表 — {patient.name} 様<span className="text-xs font-normal text-slate-400 ml-2">{period}</span></div>
          <button onClick={onClose} className="p-1.5 text-slate-400 hover:text-slate-600 hover:bg-slate-200 rounded-lg"><X size={18}/></button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          <div className="bg-sky-50 border border-sky-200 rounded-lg px-3 py-2 text-xs text-slate-600 leading-relaxed">
            <div><span className="font-bold">利用者:</span> {patient.name} 様（被保険者番号: {patient.insuranceNo||'—'}）</div>
            <div><span className="font-bold">事業所名:</span> {facility.name||'—'}</div>
            <div><span className="font-bold">居宅介護支援事業者:</span> {patient.cmOffice||'—'}　<span className="font-bold">担当ケアマネ:</span> {patient.cmName||'—'} 様{patient.cmFax?`（FAX ${patient.cmFax}）`:''}{!patient.cmFax && patient.cmOffice ? <span className="text-red-500 font-bold ml-1">※FAX番号 未登録</span>:''}</div>
            {noAttendance && <div className="text-red-600 font-bold mt-1">⚠ 当月は通所(利用)がありません → ①は「実施できなかった」を初期選択しています。</div>}
          </div>
          <div className="flex gap-3 flex-wrap">
            <div className="flex-1 min-w-[140px]">
              <label className="block text-sm font-bold text-slate-700 mb-1">実施日</label>
              <input type="date" value={implDate} onChange={e=>setImplDate(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg text-sm outline-none focus:border-blue-400" />
            </div>
            <div className="flex-1 min-w-[140px]">
              <label className="block text-sm font-bold text-slate-700 mb-1">モニタリング実施者</label>
              <input value={recorder} onChange={e=>setRecorder(e.target.value)} placeholder="実施者名" className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg text-sm outline-none focus:border-blue-400" />
            </div>
          </div>
          <div className="flex items-center justify-between gap-2 pt-1">
            <div className="text-xs font-bold text-slate-500">【モニタリング結果】各項目をプルダウンで選び、必要に応じて内容を記入します。</div>
            <button onClick={runAi} disabled={aiLoading} title={hasApiKey?'AIで全項目の下書きを生成':'各種設定→モニタリングでAPIキーを設定してください'}
              className="shrink-0 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1 bg-violet-600 hover:bg-violet-700 disabled:bg-slate-300 text-white whitespace-nowrap">
              {aiLoading ? '⟳ 生成中...' : 'AIで下書き'}
            </button>
          </div>
          {aiErr && <div className="text-xs text-red-600 font-bold bg-red-50 border border-red-200 rounded-lg px-3 py-2">{aiErr}</div>}
          {MON_ITEMS.map(it => (
            <div key={it.key} className="border border-slate-200 rounded-lg overflow-hidden">
              <div className="bg-slate-100 px-3 py-1.5 text-sm font-bold text-slate-700 flex items-center justify-between gap-2">
                <span>{it.no}{it.title}</span>
                <select value={vals[it.key].sel} onChange={e=>setSel(it.key, e.target.value)}
                  className="px-2 py-1 text-xs font-bold bg-white border border-slate-300 rounded-md outline-none focus:border-blue-400">
                  <option value="">— 選択 —</option>
                  {it.options.map(o=> <option key={o} value={o}>{o}</option>)}
                </select>
              </div>
              <div className="px-3 pt-1.5 text-[11px] text-slate-400 leading-snug">{it.explain}</div>
              <textarea value={vals[it.key].text} onChange={e=>setText(it.key, e.target.value)} rows={3} placeholder="内容（任意・選択に沿って記入）"
                className="w-full px-3 py-2 text-sm outline-none focus:bg-blue-50/30 leading-relaxed resize-y" />
            </div>
          ))}
        </div>
        <div className="px-4 py-3 border-t border-slate-200 bg-slate-50 flex items-center justify-end gap-2 shrink-0 flex-wrap">
          <button onClick={()=>{ onPrint(collect(), true); }} className="px-4 py-2.5 bg-slate-700 hover:bg-slate-800 text-white rounded-xl font-bold text-sm flex items-center gap-1.5"><Printer size={15}/>印刷・FAX</button>
          <button onClick={()=>{ onSave(collect()); onClose(); }} className="px-5 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl font-bold text-sm flex items-center gap-1.5 shadow"><Save size={15}/>個人ファイルへ保存</button>
        </div>
      </div>
    </div>, document.body);
}

// === MonitoringView (モニタリング作成) ===
function MonitoringView({ appData, onSave, dirtyRef, saveFnRef, onShowPrintPreview }) {
  const markDirty = React.useCallback(()=>{ if(dirtyRef) dirtyRef.current=true; },[dirtyRef]);
  const markClean = React.useCallback(()=>{ if(dirtyRef) dirtyRef.current=false; },[dirtyRef]);
  const [targetMonth, setTargetMonth] = React.useState(() => {
    const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
  });
  const [results, setResults] = React.useState(() => {
    // 保存済みのmonitoringRecordsからresultsを復元
    const saved = appData.monitoringRecords || [];
    const init = {};
    saved.forEach(r => {
      if (r.summary) {
        init[r.patientId] = { text: r.summary, confirmed: true, loading: false, error: null, editing: false };
      }
    });
    return init;
  });
  const [isGeneratingAll, setIsGeneratingAll] = React.useState(false);
  const cancelRef = React.useRef(false);
  const [copiedId, setCopiedId] = React.useState(null);
  const [isPrintMode, setIsPrintMode] = React.useState(false);
  const [searchQuery, setSearchQuery] = React.useState('');
  const [checkedIds, setCheckedIds] = React.useState(new Set());
  const [activeSelection, setActiveSelection] = React.useState(null);
  const [monitorSort, setMonitorSort] = React.useState('kana'); // 'kana'|'careLevel'|'cmOffice'|'schedule'
  const [sheetModal, setSheetModal] = React.useState(null); // {patientId} 正式モニタリング表の編集
  const [autoFax, setAutoFax] = React.useState(null); // 自動FAX送信の進捗/結果 {running,total,done,results:[]}
  const [editTextCell, setEditTextCell] = React.useState(null); // `${pid}:${key}` 一覧で本文を直接編集中のセル

  // 対象月が変わったらその月の保存済みデータで更新
  React.useEffect(() => {
    const month = `${tY}年${tM}月`;
    const saved = (appData.monitoringRecords||[]).filter(r => r.period === month);
    setResults(prev => {
      const next = {};
      // 保存済みを確定済みとしてセット
      saved.forEach(r => {
        next[r.patientId] = prev[r.patientId]?.loading
          ? prev[r.patientId]  // 生成中は維持
          : { text: r.summary, confirmed: true, loading: false, error: null, editing: false };
      });
      // 未確定（生成中・編集中）はそのまま維持
      Object.entries(prev).forEach(([pid, v]) => {
        if (!next[pid] && (v.loading || (v.text && !v.confirmed))) next[pid] = v;
      });
      return next;
    });
  }, [targetMonth]);

  // ★ 一覧のプルダウン変更・本文入力・AI下書きは upsertSheet で即保存されるため、未保存(dirty)は持たない。

  // 保存ボタン押下時: 一覧のプルダウン変更・手入力・AI下書きは updateSheetInline/upsertSheet で
  //   その都度 monitoringRecords に保存済み(シート構造を保持)。 ここで要約のみのレコードで
  //   上書きするとシート(①〜⑤・AI下書き)が消えるため、 dirty を落とすだけにする。
  React.useEffect(() => {
    if (!saveFnRef) return;
    saveFnRef.current = () => { if (dirtyRef) dirtyRef.current = false; };
  });

  const [tY, tM] = targetMonth.split('-').map(Number);
  // ★ AIコスト管理: 当月分は毎月15日以降のみ 作成・AI下書き・記入 を可能にする (過去月はいつでも可)
  const _mNow = new Date();
  const _isCurrentMonth = tY === _mNow.getFullYear() && tM === (_mNow.getMonth()+1);
  const _monthLocked = _isCurrentMonth && _mNow.getDate() < 15;
  // ★ AI利用回数の上限: 1事業所あたり「利用中の利用者数 ＋ 月3回」まで(実際のカレンダー月で集計)。
  const _aiMonthKey = `${_mNow.getFullYear()}-${String(_mNow.getMonth()+1).padStart(2,'0')}`;
  const _aiActiveCount = (appData.patients||[]).filter(p => p.status === '利用中').length;
  const _aiLimit = _aiActiveCount + 3;
  const _aiUsed = (appData.systemSettings?.aiUsage?.[_aiMonthKey]) || 0;
  const _aiRemaining = Math.max(0, _aiLimit - _aiUsed);
  // systemSettings に AI使用回数を n 加算した新しい systemSettings を返す
  const _bumpAiUsage = (ss, n) => ({ ...(ss||{}), aiUsage: { ...((ss||{}).aiUsage||{}), [_aiMonthKey]: ((ss||{}).aiUsage?.[_aiMonthKey]||0) + n } });

  // 全利用中患者を通所有無で分類
  const allActive = (appData.patients||[]).filter(p => p.status === '利用中');
  const hasAttendance = (patient) => {
    return (appData.ticketRecords||[]).some(r => {
      const m = r.date?.match(/(\d+)月/);
      return r.patientId === patient.id && m && parseInt(m[1]) === tM &&
        (r.status==='出席'||r.status==='振替');
    });
  };
  const careLevelOrd = ['事業対象者','要支援1','要支援2','要介護1','要介護2','要介護3','要介護4','要介護5'];
  const dowStr = ['日','月','火','水','木','金','土'];
  const getSchedule = (p) => (p.scheduleAmPm||[]).map((v,i)=>v?dowStr[i]:'').filter(Boolean).join('');
  const isBdayMonth = (p) => { if(!p.birthDate) return false; return new Date(p.birthDate).getMonth()+1 === new Date().getMonth()+1; };
  const sortPats = (arr) => [...arr].sort((a,b)=>{
    if(monitorSort==='kana') return (a.kana||a.name||'').localeCompare(b.kana||b.name||'','ja');
    if(monitorSort==='careLevel') return careLevelOrd.indexOf(a.careLevel)-careLevelOrd.indexOf(b.careLevel);
    if(monitorSort==='cmOffice') return (a.cmOffice||'').localeCompare(b.cmOffice||'','ja');
    if(monitorSort==='schedule') return getSchedule(a).localeCompare(getSchedule(b),'ja');
    return 0;
  });
  const filterBySearch = (p) => !searchQuery || p.name.includes(searchQuery) || (p.kana||'').includes(searchQuery);
  const attendedPats = sortPats(allActive.filter(p => hasAttendance(p) && filterBySearch(p)));
  const absentPats   = sortPats(allActive.filter(p => !hasAttendance(p) && filterBySearch(p)));

  // チェックボックス操作
  const toggleCheck = (id) => setCheckedIds(prev => {
    const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n;
  });
  const checkAll = () => setCheckedIds(new Set([...attendedPats, ...absentPats].map(p=>p.id)));
  const uncheckAll = () => setCheckedIds(new Set());
  const checkUnentered = () => setCheckedIds(new Set(attendedPats.filter(p=>!results[p.id]?.text).map(p=>p.id)));
  const checkUnconfirmed = () => setCheckedIds(new Set(attendedPats.filter(p=>!results[p.id]?.confirmed).map(p=>p.id)));
  const checkAbsent = () => setCheckedIds(new Set(absentPats.map(p=>p.id)));
  const allChecked = attendedPats.length > 0 && attendedPats.every(p => checkedIds.has(p.id));

  // 対象月の記録を患者ごとに集計
  const buildPatientData = (patient) => {
    const recs = (appData.ticketRecords||[]).filter(r => {
      const m = r.date?.match(/(\d+)月/);
      return r.patientId === patient.id && m && parseInt(m[1]) === tM;
    });
    const attended = recs.filter(r => r.status==='出席'||r.status==='振替');
    const planned  = recs.filter(r => ['出席','振替','休止'].includes(r.status) || (r.status==='欠席'&&!(r.tokki||'').includes('へ振替')));
    const rate = planned.length ? Math.round(attended.length/planned.length*100) : null;

    const bpVals = attended.filter(r=>r.bpUpSt).map(r=>parseInt(r.bpUpSt));
    const avgBp  = bpVals.length ? Math.round(bpVals.reduce((a,b)=>a+b,0)/bpVals.length) : null;
    const maxBp  = bpVals.length ? Math.max(...bpVals) : null;

    const tempVals = attended.filter(r=>r.temp).map(r=>parseFloat(r.temp));
    const avgTemp  = tempVals.length ? (tempVals.reduce((a,b)=>a+b,0)/tempVals.length).toFixed(1) : null;

    const MOOD_SCORE = {excellent:5,good:4,normal:3,bad:2,terrible:1};
    const MOOD_LABEL = {excellent:'とても良い',good:'良い',normal:'普通',bad:'イマイチ',terrible:'とても悪い'};
    const moodVals = attended.flatMap(r=>[r.kibunArrival,r.kibunDeparture]).filter(v=>MOOD_SCORE[v]);
    const avgMoodScore = moodVals.length ? moodVals.reduce((a,v)=>a+(MOOD_SCORE[v]||3),0)/moodVals.length : null;
    const avgMoodKey = avgMoodScore ? ['terrible','bad','normal','good','excellent'][Math.max(0,Math.min(4,Math.round(avgMoodScore)-1))] : null;

    const tokkiList = attended.filter(r=>r.tokki).map(r=>r.tokki).join('、');

    // 体力測定（直近2回）
    const fitnessRecs = (appData.fitnessRecords||[])
      .filter(r=>r.patientId===patient.id)
      .sort((a,b)=>b.date.localeCompare(a.date))
      .slice(0,2);

    // 前月データ
    const prevM = tM===1 ? 12 : tM-1;
    const prevY = tM===1 ? tY-1 : tY;
    const prevRecs = (appData.ticketRecords||[]).filter(r => {
      const m = r.date?.match(/(\d+)月/);
      return r.patientId === patient.id && m && parseInt(m[1]) === prevM;
    });
    const prevAttended = prevRecs.filter(r=>r.status==='出席'||r.status==='振替');
    const prevPlanned  = prevRecs.filter(r=>isPlannedRec(r));
    const prevRate = prevPlanned.length ? Math.round(prevAttended.length/prevPlanned.length*100) : null;
    const prevBpVals = prevAttended.filter(r=>r.bpUpSt).map(r=>parseInt(r.bpUpSt));
    const prevAvgBp  = prevBpVals.length ? Math.round(prevBpVals.reduce((a,b)=>a+b,0)/prevBpVals.length) : null;

    // ★ 情報量を増やす: 特記(日付つき全件)・血圧詳細(拡張期/範囲/高血圧日)・脈・体温最高・2列目血圧・気分分布
    const _num = (v) => { const n=parseInt(v); return isNaN(n)?null:n; };
    const tokkiDetail = attended.filter(r=>(r.tokki||'').trim()).map(r=>`${r.date}: ${String(r.tokki).trim()}`);
    const bpDnVals = attended.map(r=>_num(r.bpDnSt)).filter(n=>n!=null);
    const avgBpDn = bpDnVals.length ? Math.round(bpDnVals.reduce((a,b)=>a+b,0)/bpDnVals.length) : null;
    const minBp = bpVals.length ? Math.min(...bpVals) : null;
    const highBpDays = attended.filter(r=>{const s=_num(r.bpUpSt),dn=_num(r.bpDnSt); return (s!=null&&s>=140)||(dn!=null&&dn>=90);}).length;
    const pulseVals = attended.map(r=>_num(r.plSt)).filter(n=>n!=null);
    const avgPulse = pulseVals.length ? Math.round(pulseVals.reduce((a,b)=>a+b,0)/pulseVals.length) : null;
    const maxTemp = tempVals.length ? Math.max(...tempVals).toFixed(1) : null;
    const bp2Vals = attended.map(r=>_num(r.bpUpEn)).filter(n=>n!=null);
    const avgBp2 = bp2Vals.length ? Math.round(bp2Vals.reduce((a,b)=>a+b,0)/bp2Vals.length) : null;
    const moodDist = {};
    attended.forEach(r=>[r.kibunArrival,r.kibunDeparture].forEach(v=>{ if(MOOD_LABEL[v]) moodDist[v]=(moodDist[v]||0)+1; }));
    const moodDistText = ['excellent','good','normal','bad','terrible'].filter(k=>moodDist[k]).map(k=>`${MOOD_LABEL[k]}×${moodDist[k]}`).join('、');
    return {
      name: patient.name,
      careLevel: patient.careLevel,
      month: `${tY}年${tM}月`,
      prevMonth: `${prevY}年${prevM}月`,
      attended: attended.length,
      planned: planned.length,
      rate,
      prevRate,
      avgBp, maxBp, minBp, avgBpDn, highBpDays, avgPulse, avgBp2, prevAvgBp,
      avgTemp, maxTemp,
      avgMoodKey, avgMoodLabel: avgMoodKey ? MOOD_LABEL[avgMoodKey] : null, moodDistText,
      tokki: tokkiList, tokkiDetail,
      fitnessRecs,
      fitnessItems: appData.systemSettings?.fitnessItems || [],
    };
  };

  const generateOne = async (patient) => {
    const apiKey = (appData.systemSettings?.anthropicApiKey || '').trim();
    if (!apiKey) {
      setResults(prev => ({...prev, [patient.id]: {text:'', loading:false, error:'APIキーが未設定です。各種設定 → モニタリング で入力・保存してください。'}}));
      return;
    }
    setResults(prev => ({...prev, [patient.id]: {text:'', loading:true, error:null}}));
    try {
      let d;
      try { d = buildPatientData(patient); }
      catch(e2) { throw new Error('データ集計エラー: ' + e2.message); }

      const fitnessText = d.fitnessRecs.length > 0
        ? d.fitnessRecs.map(r => {
            const vals = (d.fitnessItems||[]).map(it => r.values?.[it.id] ? `${it.name}:${r.values[it.id]}${it.unit||''}` : null).filter(Boolean).join('、');
            return `${r.date}（${vals||'データあり'}）`;
          }).join(' / ')
        : '記録なし';

      const prompt = `以下のデイサービス利用者データをもとに、ケアマネジャー向けモニタリング報告文を2文で作成してください。

利用者名：${d.name}（${d.careLevel||''}）
対象月：${d.month}
血圧(開始)平均：${d.avgBp||'不明'}/${d.avgBpDn||'?'}mmHg（範囲${d.minBp||'?'}〜${d.maxBp||'?'}、前月${d.prevAvgBp||'不明'}）${d.highBpDays?`　血圧が高めの日${d.highBpDays}回`:''}${d.avgBp2!=null?`　${secondBpLabel(appData)}時平均${d.avgBp2}`:''}
脈拍平均：${d.avgPulse||'不明'}回/分　体温平均：${d.avgTemp||'不明'}℃（最高${d.maxTemp||'不明'}℃）
気分：平均${d.avgMoodLabel||'不明'}${d.moodDistText?`（内訳${d.moodDistText}）`:''}
体力測定（直近）：${fitnessText}
特記事項（日付つき全件）：${d.tokkiDetail&&d.tokkiDetail.length?d.tokkiDetail.join(' / '):'特になし'}

出力ルール：
・報告文の本文2文のみ出力。前置き・補足・文字数・説明は一切不要
・1文目：「今月は〜でした。」で始める（バイタル・気分・特記を中心に）
・2文目：「前回と比べて〜」または「引き続き〜」で変化や継続状態を記述
・専門的かつ丁寧な文体、具体的な数値を使用`;

      const resp = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': apiKey,
          'anthropic-version': '2023-06-01',
          'anthropic-dangerous-direct-browser-access': 'true'
        },
        body: JSON.stringify({
          model: 'claude-haiku-4-5-20251001',
          max_tokens: 400,
          messages: [{role:'user', content: prompt}]
        })
      });

      let data;
      try { data = await resp.json(); }
      catch(e2) { throw new Error(`レスポンス解析エラー (HTTP ${resp.status})`); }

      if (!resp.ok) {
        throw new Error(data?.error?.message || `APIエラー (HTTP ${resp.status})`);
      }

      const text = data.content?.[0]?.text?.trim() || 'エラー：テキストが取得できませんでした';
      setResults(prev => ({...prev, [patient.id]: {text, loading:false, error:null}}));
    } catch(e) {
      setResults(prev => ({...prev, [patient.id]: {text:'', loading:false, error: String(e.message||e)}}));
    }
  };

  const confirmResult = (patientId) => {
    const res = results[patientId];
    if (!res?.text) return;
    // 確定状態に変更 (画面表示のみ)。実際の appData への保存は保存ボタン押下まで遅延
    setResults(prev => ({...prev, [patientId]: {...prev[patientId], confirmed: true}}));
    if (dirtyRef) dirtyRef.current = true;
  };

  const unconfirmResult = (patientId) => {
    setResults(prev => ({...prev, [patientId]: {...prev[patientId], confirmed: false}}));
    if (dirtyRef) dirtyRef.current = true;
  };

  const generateAll = async () => {
    const targets = attendedPats.filter(p => checkedIds.has(p.id));
    if (targets.length === 0) { alert('チェックした利用者がいません'); return; }
    cancelRef.current = false;
    setIsGeneratingAll(true);
    for (const p of targets) {
      if (cancelRef.current) break;
      await generateOne(p);
    }
    setIsGeneratingAll(false);
    cancelRef.current = false;
  };

  const cancelGenerate = () => {
    cancelRef.current = true;
    setIsGeneratingAll(false);
    setSheetBatchProg(null);
  };

  // ★ モニタリング表(正式シート)をAIで一括下書き → まとめて個人ファイルに保存
  const [sheetBatchProg, setSheetBatchProg] = React.useState(null); // {done,total} | null
  const generateAllSheets = async () => {
    if (_monthLocked) { alert('当月分のAI下書きは毎月15日以降にご利用いただけます（AIコスト管理のため）。過去月はいつでも作成できます。'); return; }
    // ★ 通所がある人はAI下書き、 通所が無い人(一度も来ていない人)はAI不要で「実施できなかった」既定で作成。
    const noKey = !(appData.systemSettings?.anthropicApiKey||'').trim();
    // ★ 利用者を選択していない場合は全員生成せず、選択を促す
    const targets = [...attendedPats, ...absentPats].filter(p => checkedIds.has(p.id));
    if (!targets.length) { alert('利用者を選択してください（チェックを付けた方のみ下書きします）'); return; }
    const attCount = targets.filter(p => hasAttendance(p)).length;
    if (noKey && attCount > 0) {
      if (!window.confirm(`APIキーが未設定のため、通所がある ${attCount}名 はスキップし、通所が無い方のみ「実施できなかった」で作成します。\n（通所がある方もAIで作成するには 各種設定→モニタリング でAPIキーを設定してください）\n続行しますか？`)) return;
    } else {
      const _aiNote = attCount > _aiRemaining ? `\n※ 今月のAI下書きは残り${_aiRemaining}回です。通所がある${attCount}名のうち、先着${_aiRemaining}名のみAIで下書きし、超過分は既定値で作成します（手直しで仕上げてください）。` : `\n（今月のAI下書き残り${_aiRemaining}回）`;
      if (!window.confirm(`${targets.length}名のモニタリング表を作成し、個人ファイルに保存します。\n（通所がある方はAI下書き／一度も来ていない方は「実施できなかった」。既に作成済みの月は上書き）${_aiNote}\nよろしいですか？`)) return;
    }
    cancelRef.current = false;
    setSheetBatchProg({ done:0, total:targets.length });
    let existing = [...(appData.monitoringRecords||[])];
    const newResults = {};
    let done = 0, ok = 0;
    let aiBudget = _aiRemaining, aiUsedThisRun = 0; // ★ 今月のAI残り回数まで
    const rec = getActiveRecorderName() || '';
    const today = new Date().toISOString().slice(0,10);
    for (const p of targets) {
      if (cancelRef.current) break;
      try {
        const noAtt = !hasAttendance(p);
        let out;
        if (noAtt) {
          const sel = buildAutoSel(p);
          out = {
            s1:   { sel: sel.s1 || '実施できなかった', text: buildAutoStatus(p) },
            goal: { sel: sel.goal || '評価困難',       text: '当月は通所がなく、目標の評価が困難。' },
            s2:   { sel: '',                           text: '' },
            s3:   { sel: '経過観察を要する',            text: buildAutoChange(p) },
            s4:   { sel: 'このまま継続',                text: '' },
          };
        } else if (noKey) {
          done++; setSheetBatchProg({ done, total:targets.length }); continue; // 通所ありはAPIキー必須 → スキップ
        } else if (aiBudget > 0) {
          out = await aiDraftSheet(p); aiBudget--; aiUsedThisRun++;
        } else {
          // ★ 今月のAI利用上限に達した → AIを使わず既定値で作成(手直しで仕上げてください)
          const sel = buildAutoSel(p);
          out = {
            s1:   { sel: sel.s1 || '実施できた',   text: buildAutoStatus(p) },
            goal: { sel: sel.goal || '概ね達成',   text: '' },
            s2:   { sel: '概ね満足',                text: '' },
            s3:   { sel: sel.s3 || '変化なし',      text: buildAutoChange(p) },
            s4:   { sel: 'このまま継続',            text: '' },
          };
        }
        // ★ 既存(手入力含む)を残し、AIは空欄のみ補完。 確定はしない。
        const prevRec = existing.find(r => r.patientId===p.id && r.period===monthLabelStr);
        const base = (prevRec && prevRec.sheet) ? prevRec.sheet : { implDate: today, recorder: rec };
        const sheet = { implDate: base.implDate||today, recorder: base.recorder||rec };
        MON_ITEMS.forEach(it => { const b=_monCell(base[it.key]); const o=out[it.key]||{}; sheet[it.key] = { sel: b.sel || o.sel || '', text: b.text || o.text || '' }; });
        existing = existing.filter(r => !(r.patientId===p.id && r.period===monthLabelStr));
        const sm = _monSummary(sheet);
        existing.push({ id:(prevRec&&prevRec.id)||`${p.id}_${tY}-${String(tM).padStart(2,'0')}`, patientId:p.id, period:monthLabelStr, createdDate:(prevRec&&prevRec.createdDate)||new Date().toLocaleDateString('ja-JP'), createdAt:(prevRec&&prevRec.createdAt)||Date.now(), summary:sm, sheet, confirmed:false });
        newResults[p.id] = { text:sm, loading:false, error:null };
        ok++;
      } catch(e) { /* この利用者はスキップ */ }
      done++; setSheetBatchProg({ done, total:targets.length });
    }
    const _overflowNote = (aiUsedThisRun < _aiRemaining) ? '' : (aiBudget<=0 && !noKey ? '（今月のAI上限に達した分は既定値で作成→手直ししてください）' : '');
    onSave({ ...appData, monitoringRecords: existing, systemSettings: aiUsedThisRun ? _bumpAiUsage(appData.systemSettings, aiUsedThisRun) : appData.systemSettings }, { manual:true, message:`✓ ${ok}名のモニタリング表を作成・保存しました${_overflowNote}` });
    setResults(prev => ({ ...prev, ...newResults }));
    setSheetBatchProg(null);
    cancelRef.current = false;
  };

  // ★ 一覧で直接編集: 既存記録(なければ既定)に1項目だけ反映して保存(個人ファイルへ即格納)
  const getOrInitSheetFor = (patient) => {
    const rec = getSheetRecord(patient.id);
    if (rec?.sheet) return rec.sheet;
    const sel = buildAutoSel(patient); const noAtt = !hasAttendance(patient);
    return { implDate: new Date().toISOString().slice(0,10), recorder: getActiveRecorderName()||'',
      s1:{sel: sel.s1||(noAtt?'実施できなかった':'実施できた'), text: buildAutoStatus(patient)},
      goal:{sel: sel.goal||'', text: noAtt?'当月は通所がなく評価が困難。':''},
      s2:{sel:'',text:''}, s3:{sel:'変化なし',text: buildAutoChange(patient)}, s4:{sel:'このまま継続',text:''} };
  };
  // ★ シートを保存。 confirmedFlag=省略時は既存の確定状態を維持(=自動で確定済みにしない)。
  const upsertSheet = (patient, sheet, opts, confirmedFlag, extra) => {
    let existing = [...(appData.monitoringRecords||[])];
    const prev = existing.find(r => r.patientId===patient.id && r.period===monthLabelStr);
    existing = existing.filter(r => !(r.patientId===patient.id && r.period===monthLabelStr));
    const sm = _monSummary(sheet);
    const conf = (confirmedFlag != null) ? confirmedFlag : !!(prev && prev.confirmed);
    existing.push({ id: (prev&&prev.id) || `${patient.id}_${tY}-${String(tM).padStart(2,'0')}`, patientId:patient.id, period:monthLabelStr, createdDate:(prev&&prev.createdDate)||new Date().toLocaleDateString('ja-JP'), createdAt:(prev&&prev.createdAt)||Date.now(), summary:sm, sheet, confirmed: conf });
    onSave({...appData, monitoringRecords: existing, ...(extra||{})}, opts);
    setResults(prev2=>({...prev2,[patient.id]:{text:sm, loading:false, error:null}}));
    if (dirtyRef) dirtyRef.current = false;
  };
  const updateSheetInline = (patient, key, field, value) => {
    if (_monthLocked) { alert('当月分のモニタリングは毎月15日以降に記入できます。'); return; }
    const rec = getSheetRecord(patient.id);
    if (rec && rec.confirmed) return; // ★ 確定済みは編集不可
    const base = getOrInitSheetFor(patient);
    const sheet = { ...base, [key]: { ..._monCell(base[key]), [field]: value } };
    upsertSheet(patient, sheet); // 確定状態は維持(=未確定のまま)
  };
  // ★ 確定/解除トグル (レコードの confirmed を反転)。 未作成なら既定シートを作って確定。
  const toggleConfirm = (patient) => {
    const rec = getSheetRecord(patient.id);
    if (!rec || !rec.sheet) { const sheet = getOrInitSheetFor(patient); upsertSheet(patient, sheet, {manual:true, message:'✓ 確定しました'}, true); return; }
    upsertSheet(patient, rec.sheet, {manual:true, message: rec.confirmed ? '確定を解除しました' : '✓ 確定しました'}, !rec.confirmed);
  };
  // ★ 一覧の1行をAIで下書き (手入力済みの内容は残してAIは空欄のみ補完)。 確定はしない。
  const aiDraftRow = async (patient) => {
    if (_monthLocked) { alert('当月分のAI下書きは毎月15日以降にご利用いただけます（AIコスト管理のため）。'); return; }
    if (!(appData.systemSettings?.anthropicApiKey||'').trim()) { alert('各種設定→モニタリングでAPIキーを設定してください'); return; }
    if (_aiRemaining <= 0) { alert(`今月のAI下書きの上限（利用者${_aiActiveCount}名＋3回＝${_aiLimit}回）に達しました。\n翌月まで手入力または「一括作成（既定）」でご対応ください。`); return; }
    setResults(prev=>({...prev,[patient.id]:{...(prev[patient.id]||{}), loading:true, error:null}}));
    try {
      const out = await aiDraftSheet(patient);
      const base = getOrInitSheetFor(patient);
      const merged = { ...base };
      MON_ITEMS.forEach(it => { const b=_monCell(base[it.key]); const o=out[it.key]||{}; merged[it.key] = { sel: b.sel || o.sel || '', text: b.text || o.text || '' }; });
      upsertSheet(patient, merged, {manual:true, message:`✓ AIで下書きしました（今月の残り${_aiRemaining-1}回）`}, false, { systemSettings: _bumpAiUsage(appData.systemSettings, 1) });
    } catch(e) {
      setResults(prev=>({...prev,[patient.id]:{...(prev[patient.id]||{}), loading:false, error:String(e.message||e)}}));
    }
  };
  // ★ 一括作成(既定): 全員にモニタリング表を作成(通所ありは下書き文/通所なしは実施できなかった)。 AI不要・即保存
  const createAllDefault = () => {
    if (_monthLocked) { alert('当月分の作成・保存は毎月15日以降にご利用いただけます（AIコスト管理のため）。過去月はいつでも作成できます。'); return; }
    // ★ 未選択なら全員作成せず選択を促す
    const targets = [...attendedPats, ...absentPats].filter(p=>checkedIds.has(p.id));
    if (!targets.length) { alert('利用者を選択してください（チェックを付けた方のみ作成します）'); return; }
    if (!window.confirm(`${targets.length}名にモニタリング表を作成し、個人ファイルへ保存します。\n（既存の手入力は残します。確定はしません）よろしいですか？`)) return;
    let existing = [...(appData.monitoringRecords||[])];
    const newResults = {};
    for (const p of targets) {
      const prevRec = existing.find(r => r.patientId===p.id && r.period===monthLabelStr);
      const sheet = (prevRec && prevRec.sheet) ? prevRec.sheet : getOrInitSheetFor(p); // 既存があれば温存
      existing = existing.filter(r => !(r.patientId===p.id && r.period===monthLabelStr));
      const sm = _monSummary(sheet);
      existing.push({ id:(prevRec&&prevRec.id)||`${p.id}_${tY}-${String(tM).padStart(2,'0')}`, patientId:p.id, period:monthLabelStr, createdDate:(prevRec&&prevRec.createdDate)||new Date().toLocaleDateString('ja-JP'), createdAt:(prevRec&&prevRec.createdAt)||Date.now(), summary:sm, sheet, confirmed:(prevRec?!!prevRec.confirmed:false) });
      newResults[p.id] = { text:sm, loading:false, error:null };
    }
    onSave({ ...appData, monitoringRecords: existing }, { manual:true, message:`✓ ${targets.length}名のモニタリング表を作成・保存しました` });
    setResults(prev => ({ ...prev, ...newResults }));
  };
  // ★ モニタリング送付履歴の記録を作る (個人ファイル「連絡」タブ・宛先=担当ケアマネ)
  const _monFaxEntry = (p, idx) => ({
    id: `mon_${p.id}_${tY}-${String(tM).padStart(2,'0')}_${Date.now()}${idx!=null?'_'+idx:''}`,
    type: 'monitoring', patientId: p.id, patientName: p.name||'',
    subject: `${monthLabelStr} 通所介護モニタリング表`,
    recipientOffice: p.cmOffice||'', recipientName: p.cmName||'', recipientFax: p.cmFax||'',
    memo: (getSheetRecord(p.id)?.summary)||'', timestamp: new Date().toISOString(),
  });
  // ★ 担当ケアマネへFAX(一括): 作成済みのモニタリング表を、利用者ごとの担当ケアマネ(cmOffice/cmName)宛てで出力＋送付履歴に記録
  const faxToCareManagers = () => {
    const checked = [...attendedPats, ...absentPats].filter(p => checkedIds.has(p.id));
    const targets = (checked.length ? checked : [...attendedPats, ...absentPats]).filter(p => getSheetRecord(p.id));
    if (!targets.length) { alert('作成済みのモニタリング表がありません。先に「AIで下書き」または「個人ファイルに保存」で作成してください。'); return; }
    const noCm = targets.filter(p => !((p.cmOffice||'').trim()));
    if (noCm.length) {
      if (!window.confirm(`担当ケアマネ事業所が未設定の方が ${noCm.length}名 います（${noCm.slice(0,3).map(p=>p.name).join('、')}${noCm.length>3?' ほか':''}）。\n宛先を空欄のまま出力しますか？\n（利用者マスタで「居宅介護支援事業所」を設定すると宛先が自動で入ります）`)) return;
    }
    if (!window.confirm(`${targets.length}名のモニタリング表を、それぞれの担当ケアマネ宛て（宛先自動）で出力します。\n送付履歴にも記録します。よろしいですか？`)) return;
    const pages = targets.map(p => buildSheetHtml(p, getSheetRecord(p.id).sheet, true, true)).join('');
    const html = `<div style="font-family:'Hiragino Sans','Yu Gothic','MS PGothic',sans-serif;">${pages}</div>`;
    const title = `モニタリング表_ケアマネ送付_${monthLabelStr}_${targets.length}名`;
    const entries = targets.map((p,i) => _monFaxEntry(p, i));
    onSave({...appData, faxHistory:[...entries, ...(appData.faxHistory||[])]}, {manual:true, message:`✓ ${targets.length}名分を担当ケアマネ宛てで出力し、送付履歴に記録しました`});
    if (onShowPrintPreview) {
      onShowPrintPreview(title,'A4 landscape',null);
      setTimeout(()=>window.dispatchEvent(new CustomEvent('setPrintHtml',{detail:{title,pageSize:'A4 landscape',html}})),50);
    }
  };
  // ★ 自動FAX送信(一括): 各利用者のモニタリング表を、それぞれの担当ケアマネのFAX番号へ外部FAX(InterFAX)で自動送信
  const autoFaxToCareManagers = async () => {
    if (autoFax?.running) return;
    const checked = [...attendedPats, ...absentPats].filter(p => checkedIds.has(p.id));
    const targets = (checked.length ? checked : [...attendedPats, ...absentPats]).filter(p => getSheetRecord(p.id));
    if (!targets.length) { alert('作成済みのモニタリング表がありません。先に作成してください。'); return; }
    const withFax = targets.filter(p => (p.cmFax||'').trim());
    const noFax = targets.filter(p => !(p.cmFax||'').trim());
    if (!withFax.length) { alert('担当ケアマネのFAX番号が登録されている利用者がいません。\n利用者マスタの「担当ケアマネ FAX」を設定してください。'); return; }
    let msg = `${withFax.length}名分のモニタリング表を、各担当ケアマネのFAX番号へ【自動送信】します。`;
    if (noFax.length) msg += `\n※ FAX番号 未登録の ${noFax.length}名（${noFax.slice(0,3).map(p=>p.name).join('、')}${noFax.length>3?' ほか':''}）は送信されません。`;
    msg += `\n\n送信は外部FAXサービス（従量課金）の対象です。よろしいですか？`;
    if (!window.confirm(msg)) return;
    setAutoFax({ running:true, total:withFax.length, done:0, results:[] });
    const results = [];
    for (const p of withFax) {
      const html = `<div style="font-family:'Hiragino Sans','Yu Gothic','MS PGothic',sans-serif;">${buildSheetHtml(p, getSheetRecord(p.id).sheet, true, false)}</div>`;
      let r0 = { name:p.name, office:p.cmOffice||'', to:p.cmFax, ok:false, err:'' };
      try {
        const resp = await fetch('/api/send-fax', { method:'POST', headers:{'content-type':'application/json'}, body: JSON.stringify({ to:p.cmFax, html, subject:`${monthLabelStr} 通所介護モニタリング表` }) });
        const j = await resp.json().catch(()=>({}));
        if (resp.ok && j.success) { r0.ok = true; r0.faxId = j.faxId; }
        else { r0.err = j.error || `HTTP ${resp.status}`; r0.notConfigured = !!j.notConfigured; }
      } catch (e) { r0.err = String(e).slice(0,120); }
      results.push(r0);
      setAutoFax(prev => ({ ...prev, done: results.length, results:[...results] }));
      if (r0.notConfigured) break; // 未設定なら以降は無駄なので中断
    }
    // 送信成功分だけ送付履歴に記録
    const okList = withFax.filter((p,i) => results[i]?.ok);
    if (okList.length) {
      const entries = okList.map((p,i) => ({ ..._monFaxEntry(p, i), memo:'自動FAX送信（外部連携）' }));
      onSave({ ...appData, faxHistory:[...entries, ...(appData.faxHistory||[])] }, { manual:true, message:`✓ ${okList.length}名分をFAX自動送信しました` });
    }
    setAutoFax(prev => ({ ...prev, running:false, results, noFaxCount: noFax.length }));
  };
  // ★ 担当ケアマネへFAX(1名): この利用者のモニタリング表を担当ケアマネ宛てで出力＋送付履歴に記録
  const faxRowToCareManager = (patient) => {
    const rec = getSheetRecord(patient.id);
    const sheet = (rec&&rec.sheet) ? rec.sheet : getOrInitSheetFor(patient);
    if (!((patient.cmOffice||'').trim())) { if(!window.confirm('この利用者は担当ケアマネ事業所が未設定です。宛先を空欄のまま出力しますか？\n（利用者マスタで「居宅介護支援事業所」を設定すると宛先が自動で入ります）')) return; }
    const html = `<div style="font-family:'Hiragino Sans','Yu Gothic','MS PGothic',sans-serif;">${buildSheetHtml(patient, sheet, true, false)}</div>`;
    const title = `モニタリング表_${patient.name}_${monthLabelStr}`;
    onSave({...appData, faxHistory:[_monFaxEntry(patient), ...(appData.faxHistory||[])]}, {manual:true, message:`✓ ${patient.name}様のモニタリング表を担当ケアマネ宛てで出力しました`});
    if (onShowPrintPreview) {
      onShowPrintPreview(title,'A4 landscape',null);
      setTimeout(()=>window.dispatchEvent(new CustomEvent('setPrintHtml',{detail:{title,pageSize:'A4 landscape',html}})),50);
    }
  };
  // ★ プレビュー: 選択した利用者(無ければ全員)の「モニタリング表(表形式)」を複数ページで表示。 このプレビュー画面から印刷/PDF/FAXできる。
  const previewSheets = () => {
    const checked = [...attendedPats, ...absentPats].filter(p => checkedIds.has(p.id));
    const targets = checked.length ? checked : [...attendedPats, ...absentPats];
    if (!targets.length) { alert('対象の利用者がいません'); return; }
    const pages = targets.map(p => { const rec=getSheetRecord(p.id); const sheet = (rec&&rec.sheet) ? rec.sheet : getOrInitSheetFor(p); return buildSheetHtml(p, sheet, true, true); }).join('');
    const html = `<div style="font-family:'Hiragino Sans','Yu Gothic','MS PGothic',sans-serif;">${pages}</div>`;
    const title = `通所介護モニタリング表_${monthLabelStr}_${targets.length}名`;
    if (onShowPrintPreview) {
      onShowPrintPreview(title,'A4 landscape',null);
      setTimeout(()=>window.dispatchEvent(new CustomEvent('setPrintHtml',{detail:{title,pageSize:'A4 landscape',html}})),50);
    }
  };

  const copyText = (id, text) => {
    try {
      const el = document.createElement('textarea');
      el.value = text;
      el.style.cssText = 'position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;';
      document.body.appendChild(el);
      el.focus();
      el.select();
      document.execCommand('copy');
      document.body.removeChild(el);
      setCopiedId(id);
      setTimeout(()=>setCopiedId(null), 2000);
    } catch(e) {
      alert('コピーに失敗しました');
    }
  };

  const handlePrint = () => {
    if(onShowPrintPreview){
      setIsPrintMode(true);
      setTimeout(()=>{
        const el = document.getElementById('print-content-monitoring');
        if(!el){ setIsPrintMode(false); return; }
        // テーブル行数に応じてA4ページに自動分割（1ページ約8〜10行）
        // 欠席者（モニタリング未実施・内容なし）を除外
        const rows = Array.from(el.querySelectorAll('tbody tr')).filter(r=>{
          if(r.style.display==='none') return false;
          // チェックボックスが無い行（欠席者行）を除外
          const cb = r.querySelector('input[type="checkbox"]');
          if(!cb) return false;
          return true;
        });
        const thead = el.querySelector('thead')?.outerHTML || '';
        // 1行の高さを計測して動的にページ数を決定
        // A4印刷領域: 297mm - 20mm(padding) - 15mm(header) ≈ 262mm = 約990px@96dpi
        // 1行約50px → 1ページ約18行
        const ROWS_PER_PAGE = 16;
        const tableStyle = 'width:100%;border-collapse:collapse;font-size:12px;border:1px solid #e2e8f0;';
        const cleanThead = '<thead><tr style="background:#0284c7;color:white;"><th style="padding:10px 8px;text-align:center;font-weight:bold;font-size:12px;width:200px;">利用者名</th><th style="padding:10px 14px;text-align:center;font-weight:bold;font-size:12px;">モニタリング内容</th></tr></thead>';
        const totalPages = Math.max(1,Math.ceil(rows.length/ROWS_PER_PAGE));
        const pages = [];
        for(let i=0; i<totalPages; i++){
          const ROW_HEIGHT = Math.floor((297 - 20 - 15) / ROWS_PER_PAGE); // mm単位
        const fixRow = (html) => html.replace(/<tr /g, `<tr style="height:${ROW_HEIGHT}mm;max-height:${ROW_HEIGHT}mm;border-bottom:1.5px solid #cbd5e1;" `);
        const pageRows = rows.slice(i*ROWS_PER_PAGE,(i+1)*ROWS_PER_PAGE).map(r=>fixRow(r.outerHTML)).join('');
        // 残りの空行を埋める
        const remaining = ROWS_PER_PAGE - rows.slice(i*ROWS_PER_PAGE,(i+1)*ROWS_PER_PAGE).length;
        const emptyRows = Array.from({length:remaining},()=>`<tr style="height:${ROW_HEIGHT}mm;border-bottom:1.5px solid #cbd5e1;"><td colspan="3" style="border-bottom:none;"></td></tr>`).join('');
          pages.push(`<div style="width:210mm;height:297mm;box-sizing:border-box;padding:10mm 12mm;page-break-after:${i<totalPages-1?'always':'auto'};page-break-inside:avoid;background:white;display:flex;flex-direction:column;overflow:hidden;">
            <div style="font-size:14px;font-weight:bold;margin-bottom:8px;border-bottom:2px solid #334155;padding-bottom:4px;flex-shrink:0;">${tY}年${tM}月 モニタリング記録${totalPages>1?' '+(i+1)+'/'+totalPages+'ページ':''}</div>
            <table style="${tableStyle};flex:1;">${thead}<tbody>${pageRows}${emptyRows}</tbody></table>
          </div>`);
        }
        const title = `モニタリング_${tY}年${tM}月`;
        const html = `<div style="font-family:'Hiragino Sans','Yu Gothic',sans-serif;">${pages.join('')}</div>`;
        onShowPrintPreview(title,'A4 portrait',null);
        setTimeout(()=>window.dispatchEvent(new CustomEvent('setPrintHtml',{detail:{title,pageSize:'A4 portrait',html}})),50);
        setIsPrintMode(false);
      },300);
    } else {
      setIsPrintMode(true);
      document.title=`モニタリング_${tY}年${tM}月`;
      setTimeout(()=>{window.print();setTimeout(()=>{document.title='つむぎ｜デイサービス管理';setIsPrintMode(false);},500);},300);
    }
  };

  const handleSavePdf = handlePrint;

  // ★ 正式モニタリング表（1人1枚）: 自動下書き / 保管(個人ファイル) / FAX(ケアマネ宛先自動)
  const monthLabelStr = `${tY}年${tM}月`;
  const getSheetRecord = (pid) => (appData.monitoringRecords||[]).find(r => r.patientId===pid && r.period===monthLabelStr);
  const buildAutoStatus = (patient) => {
    // ①サービスの実施状況: 計画通りに提供できたか + 通所実績
    try {
      const d = buildPatientData(patient);
      if (!d.attended) {
        return `${d.month}は通所(利用)がなかったため、通所介護計画に基づくサービスを実施できなかった。`;
      }
      const parts = ['通所介護計画に基づき、個別機能訓練（運動プログラム）・健康チェック（バイタル測定）・送迎を提供。'];
      if (d.planned!=null) parts.push(`${d.month}は計画${d.planned}回中${d.attended}回参加（出席率${d.rate!=null?d.rate+'%':'—'}）。`);
      parts.push('概ね計画どおりサービスを実施できた。');
      return parts.join('');
    } catch { return ''; }
  };
  // ★ 出席率に応じた①実施状況・②目標 のプルダウン初期選択
  const buildAutoSel = (patient) => {
    try {
      const d = buildPatientData(patient);
      if (!d.attended) return { s1:'実施できなかった', goal:'評価困難' };
      const r = d.rate;
      const s1 = (r!=null && r>=100) ? '実施できた' : (r!=null && r>=50) ? '概ね実施できた' : '一部実施できなかった';
      return { s1, goal:'概ね達成' };
    } catch { return {}; }
  };
  const buildAutoChange = (patient) => {
    // ③利用者の生活状況及び心身の状況の変化: バイタル/気分/体力測定の経過
    try {
      const d = buildPatientData(patient);
      const parts = [];
      const vit = [];
      if (d.avgBp!=null) vit.push(`血圧平均${d.avgBp}mmHg${d.prevAvgBp!=null?`（前月${d.prevAvgBp}）`:''}`);
      if (d.avgTemp!=null) vit.push(`体温平均${d.avgTemp}℃`);
      if (vit.length) parts.push(`バイタルは${vit.join('、')}。`);
      if (d.avgMoodLabel) parts.push(`通所時の気分は概ね「${d.avgMoodLabel}」。`);
      if (d.fitnessRecs && d.fitnessRecs.length) parts.push('体力測定を実施し経過を確認。');
      if (d.tokki) parts.push(`特記事項: ${d.tokki}。`);
      parts.push('心身の状況に大きな変化は見られない。');
      return parts.join('');
    } catch { return ''; }
  };
  const escSheet = (s) => String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br>');
  const fmtJpDate = (ymd) => { if(!ymd) return ''; try { return new Date(ymd).toLocaleDateString('ja-JP',{year:'numeric',month:'long',day:'numeric'}); } catch { return ymd; } };
  // ★ AIでモニタリング表(プルダウン選択+本文)を一括下書き。 APIキー(各種設定→モニタリング)が必要。
  const aiDraftSheet = async (patient) => {
    const apiKey = (appData.systemSettings?.anthropicApiKey || '').trim();
    if (!apiKey) throw new Error('APIキーが未設定です。各種設定 → モニタリング でAPIキーを入力・保存してください。');
    const d = buildPatientData(patient);
    const fitnessText = (d.fitnessRecs && d.fitnessRecs.length)
      ? d.fitnessRecs.map(r => { const vals=(d.fitnessItems||[]).map(it=> r.values?.[it.id]?`${it.name}:${r.values[it.id]}${it.unit||''}`:null).filter(Boolean).join('、'); return `${r.date}（${vals||'データあり'}）`; }).join(' / ')
      : '記録なし（体力測定を行わない事業所もあるため、運動の記録から評価してください）';
    // ★ 運動の記録(運動メニュー)と前月からの変化を集計 (体力測定に依存せず評価できるように)
    const _exItems = appData.systemSettings?.exerciseItems || appSettings.exerciseItems;
    const _allInd = appData.systemSettings?.individualExerciseItems || [];
    const _monthAttended = (mm) => (appData.ticketRecords||[]).filter(r => { const _m=r.date?.match(/(\d+)月/); return r.patientId===patient.id && _m && parseInt(_m[1])===mm && (r.status==='出席'||(r.status&&r.status.startsWith('振'))); });
    const _exDoneNames = (recs) => { const s=new Set(); recs.forEach(r=>_exItems.forEach(it=>{ const v=r.exercises?.[it.id]; let nm=it.name, has=false; if(v&&typeof v==='object'){ const _v=String(v.value??'').trim(); has=(_v&&!['×','✕','x','ー','-'].includes(_v))||!!v.itemId; const sel=_allInd.find(x=>x.id===v.itemId); if(sel)nm=`${it.name}(${sel.name})`; } else { const _v=String(v??'').trim(); has=!!_v&&!['×','✕','x','ー','-'].includes(_v); } if(has)s.add(nm); })); return s; };
    const _nowRecs = _monthAttended(tM);
    const _prevM = tM===1?12:tM-1;
    const _nowSet = _exDoneNames(_nowRecs), _prevSet = _exDoneNames(_monthAttended(_prevM));
    const _baseName = (x)=>x.split('(')[0];
    const _added = [...(_nowSet)].filter(x=>![..._prevSet].some(p=>_baseName(p)===_baseName(x)));
    const _removed = [..._prevSet].filter(x=>![..._nowSet].some(n=>_baseName(n)===_baseName(x)));
    const exerciseNowText = [..._nowSet].join('、') || '記録なし';
    const exerciseChangeText = (_added.length||_removed.length)
      ? `${_added.length?'今月から追加/再開: '+_added.join('、'):''}${_added.length&&_removed.length?' / ':''}${_removed.length?'今月は実施なし: '+_removed.join('、'):''}`
      : '前月から運動メニューに大きな変更なし';
    // ★ 通所介護計画書 / 個別機能訓練計画書(あれば)の目標 → ②目標の達成・進捗の評価に使う
    const _tk = (appData.tsushoKeikakuRecords||[]).filter(r=>r.patientId===patient.id).sort((a,b)=>String(b.createdAt||b.createdDate||'').localeCompare(String(a.createdAt||a.createdDate||'')));
    const _kk = (appData.kinouKeikakuRecords||[]).filter(r=>r.patientId===patient.id).sort((a,b)=>String(b.createdAt||b.createdDate||'').localeCompare(String(a.createdAt||a.createdDate||'')));
    const _tkGoal = _tk.length ? [_tk[0].shortGoal&&`【通所介護計画】短期: ${_tk[0].shortGoal}`, _tk[0].longGoal&&`【通所介護計画】長期: ${_tk[0].longGoal}`].filter(Boolean).join(' / ') : '';
    const _kkGoal = _kk.length ? [_kk[0].shortKinou&&`短期(機能): ${_kk[0].shortKinou}`, _kk[0].shortKatsudo&&`短期(活動): ${_kk[0].shortKatsudo}`, _kk[0].longKinou&&`長期(機能): ${_kk[0].longKinou}`].filter(Boolean).join(' / ') : '';
    const _goalText = [_tkGoal, _kkGoal].filter(Boolean).join('\n');
    // ★ 欠席・休みの状況(回数・理由) → 休みが多い場合の④⑤判断に使う
    const _absRecs = (appData.ticketRecords||[]).filter(r => { const _m=r.date?.match(/(\d+)月/); return r.patientId===patient.id && _m && parseInt(_m[1])===tM && (r.status==='欠席'||r.status==='休止'||r.status==='休業'); });
    const _absCount = _absRecs.length;
    const _absReasons = [...new Set(_absRecs.map(r=>(r.tokki||'').trim()).filter(Boolean))].join('、') || '理由の記録なし';
    const optionsDesc = MON_ITEMS.map(it=>`${it.key}（${it.no}${it.title}）: 選択肢=[${it.options.join(' / ')}]`).join('\n');
    const prompt = `あなたは通所介護（リハビリ特化・半日型デイサービス）の【機能訓練指導員 兼 生活相談員】です。以下のデータをもとに「通所介護モニタリング表」の各項目を作成してください。

■ 文体・観点（重要）
・当事業所は医療機関ではありません。診断・医学的判断・治療的表現（病名・治療効果の評価 等）は使わないでください。
・機能訓練（運動）と生活機能・生活の様子の観点で、利用者本位にやさしく記述してください。
・所見は「〜の様子がみられた」「今後も見守りが必要」「継続して支援していく」等の、見守り・支援の語調にしてください。
・評価は【厳しすぎず、やわらかく前向き】に。できていない点を断定・否定しすぎず、良い面や意欲にも触れてください。
・【分量・優先順位（重要）】変化・気づき・特筆すべき点（血圧が高めの日・気分の変化・特記の出来事・運動や体力の変化 等）を優先して記載し、変化のない項目は「大きな変化なし」程度に簡潔にまとめてよい。全項目を細かく埋めようとせず、ケアマネが2分程度でサッと読める分量に。各項目のtextは原則1〜3文以内。
・ただし機能訓練・生活支援の【専門用語を適度に】交え、専門職らしい所見にしてください（例: 下肢筋力の維持、立位・歩行バランス、関節可動域、活動意欲、生活リハビリ、離床機会、転倒予防 等を文脈に応じて自然に）。専門用語の多用や堅すぎる表現は避け、読みやすさを保つこと。
・体力測定の数値が無くても構いません。運動の記録・通所の様子・気分・特記から柔軟に評価してください（体力測定にこだわらない）。
・運動メニューの変更（マシンの増減等）があれば、その点に触れてください。運動機能・筋力・気分の観点を重視してください。
・通所が無い/少ない場合: ①②は「記録がなく評価が難しい」旨を無理なく記載し、断定しない。④⑤は【休みの量と理由】で柔軟に判断すること。
　- 入院・長期の体調不良で休んだ場合 → 筋力・運動機能の低下が想定されるため、再開時に運動プログラムの見直し(負荷・内容の調整)を検討する方向。
　- 私用・通院など一時的な休み → 日程調整や、通所機会を増やす働きかけの方向。
　（いずれも医学的判断はせず、機能訓練・生活支援・見守りの観点で記載）

利用者: ${d.name}（${d.careLevel||''}）
対象月: ${d.month}
通所実績: 計画${d.planned}回中${d.attended}回参加（出席率${d.rate!=null?d.rate+'%':'不明'}）${d.attended===0?'　※当月は一度も通所なし':''}
欠席・休みの状況: 当月 欠席/休み ${_absCount}回。 理由: ${_absReasons}
取り組んだ運動メニュー: ${exerciseNowText}
運動メニューの変化: ${exerciseChangeText}
バイタル(参考): 血圧(開始)平均${d.avgBp||'不明'}/${d.avgBpDn||'?'}mmHg（範囲${d.minBp||'?'}〜${d.maxBp||'?'}、前月平均${d.prevAvgBp||'不明'}）${d.highBpDays?`、血圧が高め(収縮期140/拡張期90以上)の日 ${d.highBpDays}回`:''}${d.avgBp2!=null?`、${secondBpLabel(appData)}時 収縮期平均${d.avgBp2}`:''}
脈拍: 平均${d.avgPulse||'不明'}回/分　体温: 平均${d.avgTemp||'不明'}℃（最高${d.maxTemp||'不明'}℃）
通所時の気分: 平均${d.avgMoodLabel||'不明'}${d.moodDistText?`（内訳: ${d.moodDistText}）`:''}
体力測定(任意・行わない事業所もあり): ${fitnessText}
特記（当月の記録・日付つき全件。体調・気分・出来事・ご家族/職員の気づき等。③満足度・④心身の変化・⑤今後の方向性に反映すること）:
${d.tokkiDetail && d.tokkiDetail.length ? '・'+d.tokkiDetail.join('\n・') : 'なし'}
${_goalText ? `計画の目標（通所介護計画・個別機能訓練計画）:\n${_goalText}\n（②目標の達成・進捗は、これらの目標に対する取り組み状況・達成度を書いてください）` : '計画の目標: 未設定（一般的な生活機能の維持・向上の観点で評価してください）'}

各項目で、必ず下記の選択肢から最も適切なものを1つ"sel"に選び、"text"に2〜3文の所見を上記の文体・観点で書いてください。当月に通所が無い場合は①を必ず「実施できなかった」にしてください。
${optionsDesc}

出力は次のJSONのみ（前後に説明文やコードブロックを付けない）:
{"s1":{"sel":"","text":""},"goal":{"sel":"","text":""},"s2":{"sel":"","text":""},"s3":{"sel":"","text":""},"s4":{"sel":"","text":""}}`;
    const resp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'Content-Type':'application/json', 'x-api-key':apiKey, 'anthropic-version':'2023-06-01', 'anthropic-dangerous-direct-browser-access':'true' },
      body: JSON.stringify({ model:'claude-haiku-4-5-20251001', max_tokens:1000, messages:[{role:'user', content:prompt}] })
    });
    let data; try { data = await resp.json(); } catch { throw new Error(`レスポンス解析エラー (HTTP ${resp.status})`); }
    if (!resp.ok) throw new Error(data?.error?.message || `APIエラー (HTTP ${resp.status})`);
    let txt = data.content?.[0]?.text?.trim() || '';
    const m = txt.match(/\{[\s\S]*\}/);
    let obj; try { obj = JSON.parse(m ? m[0] : txt); } catch { throw new Error('AIの出力を解釈できませんでした。もう一度お試しください。'); }
    // 選択肢の検証 (候補外なら空に)
    const out = {};
    MON_ITEMS.forEach(it => {
      const v = obj[it.key] || {};
      const sel = it.options.includes(v.sel) ? v.sel : '';
      out[it.key] = { sel, text: typeof v.text==='string' ? v.text : '' };
    });
    return out;
  };
  const _monCell = (v) => (v && typeof v==='object') ? v : { sel:'', text:(v!=null?String(v):'') };
  const _monSummary = (sheet) => { const c=_monCell(sheet.s1); return c.text || c.sel || ''; };
  const saveSheet = (patient, sheet) => {
    let existing = [...(appData.monitoringRecords||[])];
    existing = existing.filter(r => !(r.patientId===patient.id && r.period===monthLabelStr));
    const sm = _monSummary(sheet);
    existing.push({ id:`${patient.id}_${tY}-${String(tM).padStart(2,'0')}_${Date.now()}`, patientId:patient.id, period:monthLabelStr, createdDate:new Date().toLocaleDateString('ja-JP'), createdAt:Date.now(), summary:sm, sheet });
    onSave({...appData, monitoringRecords: existing});
    setResults(prev=>({...prev,[patient.id]:{text:sm, confirmed:true, loading:false, error:null, editing:false}}));
  };
  // ★ 計画書連携: この利用者の最新の通所介護計画書の目標をモニタリング表に表示（②目標の評価対象を明示）
  const latestPlanGoals = (pid) => {
    const r = (appData.tsushoKeikakuRecords||[]).filter(x=>x.patientId===pid).sort((a,b)=>(b.createdDate||'').localeCompare(a.createdDate||''))[0];
    if (!r || (!r.longGoal && !r.shortGoal)) return null;
    return { long:r.longGoal||'', longP:r.longPeriod||'', short:r.shortGoal||'', shortP:r.shortPeriod||'', created:r.createdDate||'' };
  };
  const buildSheetHtml = (patient, sheet, forFax, pageBreak) => {
    const f = appData.systemSettings?.facilityInfo || {};
    const bd = 'border:1px solid #000;';
    const infoLab = `style="${bd}background:#f2f2f2;padding:5px 8px;font-weight:bold;font-size:11.5px;white-space:nowrap;"`;
    const infoVal = `style="${bd}padding:5px 8px;font-size:11.5px;"`;
    const faxLine = forFax && patient.cmOffice
      ? `<div style="border:1.5px solid #000;padding:6px 10px;margin-bottom:8px;font-size:12px;font-weight:bold;">FAX送付先：${escSheet(patient.cmOffice)} 御中${patient.cmName?`　ご担当 ${escSheet(patient.cmName)} 様`:''}${patient.cmFax?`　FAX: ${escSheet(patient.cmFax)}`:''}</div>`
      : '';
    // 各必須項目を「項目 | 結果(選択) | 内容」の行で出力 (運営基準の必須事項)
    const itemRows = MON_ITEMS.map(it => {
      const c = _monCell(sheet[it.key]);
      return `<tr>
        <td style="${bd}background:#d9d9d9;padding:7px 8px;font-weight:bold;font-size:11px;width:170px;vertical-align:top;line-height:1.45;">${it.no}${it.title}<div style="font-weight:normal;font-size:9px;color:#444;margin-top:3px;">${it.explain}</div></td>
        <td style="${bd}padding:7px 6px;font-size:11px;font-weight:bold;text-align:center;width:96px;vertical-align:top;">${escSheet(c.sel)||'　'}</td>
        <td style="${bd}padding:7px 9px;font-size:11px;vertical-align:top;line-height:1.7;">${escSheet(c.text)||'&nbsp;'}</td>
      </tr>`;
    }).join('');
    return `<div style="font-family:'Hiragino Sans','Yu Gothic','MS PGothic',sans-serif;color:#000;width:297mm;min-height:210mm;box-sizing:border-box;padding:10mm 12mm;background:white;${pageBreak?'page-break-after:always;page-break-inside:avoid;':''}">
      <div style="text-align:center;font-size:19px;font-weight:bold;margin-bottom:12px;">通所介護モニタリング表</div>
      ${faxLine}
      <table style="width:100%;border-collapse:collapse;margin-bottom:6px;">
        <tr>
          <td ${infoLab}>利用者名</td><td ${infoVal} style="${bd}padding:5px 8px;font-size:11.5px;width:34%;">${escSheet(patient.name)} 様　(被保険者番号: ${escSheet(patient.insuranceNo)||''})</td>
          <td ${infoLab}>事業社名</td><td ${infoVal}>${escSheet(f.name)||''}</td>
        </tr>
        <tr>
          <td ${infoLab}>居宅介護支援事業者</td><td ${infoVal}>${escSheet(patient.cmOffice)||''}</td>
          <td ${infoLab}>担当ケアマネージャー</td><td ${infoVal}>${escSheet(patient.cmName)||''} 様</td>
        </tr>
        <tr>
          <td ${infoLab}>対象期間</td><td ${infoVal}>${escSheet(monthLabelStr)}</td>
          <td ${infoLab}>実施日</td><td ${infoVal}>${escSheet(fmtJpDate(sheet.implDate))}</td>
        </tr>
        <tr>
          <td ${infoLab}>モニタリング実施者</td><td ${infoVal} colspan="3">${escSheet(sheet.recorder)||''}</td>
        </tr>
      </table>
      ${(() => { const g = latestPlanGoals(patient.id); if(!g) return ''; return `<div style="font-size:12px;font-weight:bold;margin:8px 0 4px;">【通所介護計画の目標】<span style="font-weight:normal;font-size:9.5px;color:#555;">（計画作成日 ${escSheet(g.created)}／②はこの目標に対する達成・進捗を評価）</span></div>
      <table style="width:100%;border-collapse:collapse;margin-bottom:6px;table-layout:fixed;">
        <tr><td style="${bd}background:#d9d9d9;padding:5px 8px;font-weight:bold;font-size:10.5px;width:80px;">長期目標</td><td style="${bd}padding:5px 9px;font-size:11px;line-height:1.6;">${escSheet(g.long)||'&nbsp;'}${g.longP?`<span style="color:#555;font-size:9.5px;">（期間 ${escSheet(g.longP)}）</span>`:''}</td></tr>
        <tr><td style="${bd}background:#d9d9d9;padding:5px 8px;font-weight:bold;font-size:10.5px;">短期目標</td><td style="${bd}padding:5px 9px;font-size:11px;line-height:1.6;">${escSheet(g.short)||'&nbsp;'}${g.shortP?`<span style="color:#555;font-size:9.5px;">（期間 ${escSheet(g.shortP)}）</span>`:''}</td></tr>
      </table>`; })()}
      <div style="font-size:12px;font-weight:bold;margin:8px 0 4px;">【モニタリング結果】</div>
      <table style="width:100%;border-collapse:collapse;table-layout:fixed;">
        <tr>
          <td style="${bd}background:#d9d9d9;padding:5px 8px;font-weight:bold;font-size:10.5px;text-align:center;width:170px;">項目</td>
          <td style="${bd}background:#d9d9d9;padding:5px 8px;font-weight:bold;font-size:10.5px;text-align:center;width:96px;">結果</td>
          <td style="${bd}background:#d9d9d9;padding:5px 8px;font-weight:bold;font-size:10.5px;text-align:center;">内容</td>
        </tr>
        ${itemRows}
      </table>
    </div>`;
  };
  const printSheet = (patient, sheet, forFax) => {
    const html = buildSheetHtml(patient, sheet, forFax, false);
    const title = `通所介護モニタリング表_${patient.name}_${monthLabelStr}`;
    if (onShowPrintPreview) {
      onShowPrintPreview(title,'A4 landscape',null);
      setTimeout(()=>window.dispatchEvent(new CustomEvent('setPrintHtml',{detail:{title,pageSize:'A4 landscape',html}})),50);
    }
  };

  return (
    <div style={{height:'100%',display:'flex',flexDirection:'column',background:'#f0f4f9'}}>
      {/* ヘッダー固定（スクロール時も上部にとどまる） */}
      {/* ★ モニタリングヘッダ: 淡い水色、 文字は黒で読みやすく */}
      <div className="no-print" style={{position:'sticky',top:0,zIndex:30,flexShrink:0,background:'linear-gradient(135deg,#bae6fd,#7dd3fc)',color:'#1e293b',padding:'12px 20px',display:'flex',alignItems:'center',justifyContent:'space-between',boxShadow:'0 2px 8px rgba(0,0,0,0.15)'}}>
        <div style={{display:'flex',alignItems:'center',gap:10}}>
          <ClipboardList size={20}/>
          <span style={{fontSize:17,fontWeight:'bold'}}>モニタリング作成</span>
          <span style={{fontSize:13,fontWeight:'bold',background:'rgba(255,255,255,0.2)',padding:'3px 10px',borderRadius:8}}>{tY}年{tM}月分</span>
        </div>
        <div style={{display:'flex',alignItems:'center',gap:8,flexWrap:'wrap'}}>
          <input type="month" value={targetMonth} onChange={e=>setTargetMonth(e.target.value)}
            style={{background:'rgba(255,255,255,0.5)',border:'1px solid rgba(255,255,255,0.7)',color:'#1e293b',borderRadius:10,padding:'6px 10px',fontSize:12,fontWeight:'bold',outline:'none',cursor:'pointer'}}/>
          <div style={{display:'flex',alignItems:'center',background:'rgba(255,255,255,0.5)',border:'1px solid rgba(255,255,255,0.7)',borderRadius:10,padding:'4px 10px',gap:6}}>
            <Search size={14} style={{color:'#1e293b',flexShrink:0}}/>
            <input type="text" value={searchQuery} onChange={e=>setSearchQuery(e.target.value)} placeholder="氏名で絞り込み"
              className="mon-search"
              style={{background:'transparent',border:'none',outline:'none',color:'#1e293b',fontSize:12,fontWeight:'bold',width:100}}/>
            {searchQuery && <button type="button" onClick={()=>setSearchQuery('')} style={{background:'none',border:'none',color:'#1e293b',cursor:'pointer',padding:0,lineHeight:1}}><X size={12}/></button>}
          </div>
          {/* ソートボタン */}
          <div style={{display:'flex',gap:4}}>
            {[['kana','名前'],['careLevel','介護度'],['cmOffice','事業所'],['schedule','曜日']].map(([k,l])=>(
              <button key={k} type="button" onClick={()=>setMonitorSort(k)}
                style={{background:monitorSort===k?'white':'rgba(255,255,255,0.5)',border:'1px solid rgba(255,255,255,0.7)',color:'#1e293b',borderRadius:8,padding:'4px 8px',fontWeight:'bold',fontSize:11,cursor:'pointer'}}>
                {l}
              </button>
            ))}
          </div>
          <button type="button" onClick={previewSheets} title="選んだ(無ければ全員の)モニタリング表を表形式でプレビュー。この画面から印刷/PDF/FAXできます"
            style={{background:'rgba(255,255,255,0.5)',border:'1px solid rgba(255,255,255,0.7)',color:'#1e293b',borderRadius:10,padding:'8px 14px',fontWeight:'bold',fontSize:12,cursor:'pointer',display:'flex',alignItems:'center',gap:6}}>
            <Printer size={14}/> プレビュー
          </button>
          <button type="button" onClick={()=>{ markClean(); onSave({...appData}, {manual:true, message:'✓ 保存しました'}); }}
            style={{background:'#2563eb',border:'none',color:'white',borderRadius:10,padding:'8px 14px',fontWeight:'bold',fontSize:12,cursor:'pointer',display:'flex',alignItems:'center',gap:6}}>
            <Save size={14}/> 保存
          </button>
        </div>
      </div>
      {/* 選択バー（固定） */}
      <div className="no-print" style={{flexShrink:0,background:'#e0f2fe',padding:'8px 14px',borderBottom:'1px solid #bae6fd',display:'flex',alignItems:'center',gap:5,flexWrap:'wrap',zIndex:20}}>
        <span style={{fontSize:11,fontWeight:'bold',color:'#0369a1',marginRight:2}}>選択：</span>
        {[
          ['全員','all',checkAll],
          ['未作成のみ','unentered',checkUnentered],
          ['通所なし','absent',checkAbsent],
          ['選択解除','none',uncheckAll],
        ].map(([label,key,fn]) => {
          const isAct = activeSelection===key;
          return (
            <button key={key} type="button" onClick={()=>{fn();setActiveSelection(key);}}
              style={{padding:'4px 10px',borderRadius:16,fontSize:11,fontWeight:'bold',
                border:`1px solid ${isAct?'#0284c7':'#bae6fd'}`,
                background:isAct?'#0284c7':'white',
                color:isAct?'white':'#0369a1',cursor:'pointer'}}>
              {label}
            </button>
          );
        })}
        {checkedIds.size > 0 && (
          <span style={{fontSize:11,fontWeight:'bold',color:'#0284c7',margin:'0 6px'}}>{checkedIds.size}名選択中</span>
        )}
        <span style={{borderLeft:'1px solid #bae6fd',height:18,margin:'0 4px'}}/>
        <span style={{fontSize:11,fontWeight:'bold',color:'#0369a1',marginRight:2}}>{checkedIds.size>0?`選んだ${checkedIds.size}名を：`:'全員を：'}</span>
        {/* ★ AIで下書き (チェックした人、無ければ全員) */}
        {sheetBatchProg ? (
          <button type="button" onClick={cancelGenerate}
            style={{padding:'5px 14px',borderRadius:16,fontSize:12,fontWeight:'bold',border:'1px solid #fca5a5',background:'#fef2f2',color:'#dc2626',cursor:'pointer'}}>
            ⟳ {sheetBatchProg.done}/{sheetBatchProg.total}（中止）
          </button>
        ) : (
          <button type="button" onClick={generateAllSheets} title="選んだ(無ければ全員の)モニタリング表をAIで下書きして個人ファイルに保存"
            style={{padding:'5px 14px',borderRadius:16,fontSize:12,fontWeight:'bold',border:'1px solid #c4b5fd',background:'#f5f3ff',color:'#6d28d9',cursor:'pointer'}}>
            AIで下書き
          </button>
        )}
        <button type="button" onClick={createAllDefault} title="選んだ利用者のモニタリング表を、利用者マスタの個人ファイル(ケアマネジメント)に表形式で保存(同月は最新で上書き)"
          style={{padding:'5px 14px',borderRadius:16,fontSize:12,fontWeight:'bold',border:'1px solid #6ee7b7',background:'#ecfdf5',color:'#047857',cursor:'pointer'}}>
          個人ファイルに保存
        </button>
        <button type="button" onClick={faxToCareManagers} title="作成済みのモニタリング表を、利用者ごとの担当ケアマネ宛て(宛先自動)で出力（印刷/複合機FAX用）し、送付履歴に記録します"
          style={{padding:'5px 14px',borderRadius:16,fontSize:12,fontWeight:'bold',border:'1px solid #fdba74',background:'#fff7ed',color:'#c2410c',cursor:'pointer'}}>
          印刷/複合機FAX用に出力
        </button>
        <button type="button" onClick={autoFaxToCareManagers} disabled={autoFax?.running} title="各利用者のモニタリング表を、それぞれの担当ケアマネのFAX番号へ外部FAX(InterFAX)で自動送信します（送信は従量課金）"
          style={{padding:'5px 14px',borderRadius:16,fontSize:12,fontWeight:'bold',border:'1px solid #6366f1',background:autoFax?.running?'#e0e7ff':'#eef2ff',color:'#4338ca',cursor:autoFax?.running?'wait':'pointer'}}>
          {autoFax?.running ? `自動送信中… ${autoFax.done}/${autoFax.total}` : '各ケアマネへ自動FAX送信'}
        </button>
      </div>
      <style>{`.mon-search::placeholder{color:rgba(255,255,255,0.75)!important;} @keyframes spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}`}</style>
      {autoFax && (() => {
        const okN = (autoFax.results||[]).filter(r=>r.ok).length;
        const ngN = (autoFax.results||[]).filter(r=>!r.ok).length;
        const notConf = (autoFax.results||[]).some(r=>r.notConfigured);
        return (
          <div style={{position:'fixed',inset:0,background:'rgba(15,23,42,0.55)',zIndex:100000,display:'flex',alignItems:'center',justifyContent:'center',padding:16}} onClick={()=>{ if(!autoFax.running) setAutoFax(null); }}>
            <div onClick={e=>e.stopPropagation()} style={{background:'white',borderRadius:16,width:460,maxWidth:'100%',maxHeight:'86vh',overflow:'auto',padding:20,boxShadow:'0 20px 60px rgba(0,0,0,0.3)'}}>
              <div style={{fontSize:16,fontWeight:'bold',color:'#1e293b',marginBottom:8}}>各ケアマネへ自動FAX送信</div>
              {autoFax.running ? (
                <div style={{fontSize:13,color:'#4338ca',fontWeight:'bold',marginBottom:10}}>送信中… {autoFax.done}/{autoFax.total}</div>
              ) : (
                <div style={{fontSize:13,fontWeight:'bold',marginBottom:10}}>完了：<span style={{color:'#16a34a'}}>成功 {okN}件</span> ／ <span style={{color:'#dc2626'}}>失敗 {ngN}件</span>{autoFax.noFaxCount?` ／ FAX未登録スキップ ${autoFax.noFaxCount}件`:''}</div>
              )}
              {notConf && <div style={{background:'#fffbeb',border:'1px solid #fde68a',borderRadius:10,padding:'10px 12px',fontSize:12,color:'#92400e',marginBottom:10,lineHeight:1.6}}>外部FAX送信が<b>未設定</b>です。ご利用には InterFAX のアカウント作成と、Vercelの環境変数（INTERFAX_USER / INTERFAX_PASS）の設定が必要です。設定後にお使いいただけます。</div>}
              <div style={{display:'grid',gap:5}}>
                {(autoFax.results||[]).map((r,i)=>(
                  <div key={i} style={{display:'flex',alignItems:'center',gap:8,fontSize:12,border:'1px solid #e2e8f0',borderRadius:8,padding:'6px 10px'}}>
                    <span style={{fontSize:14}}>{r.ok?'✅':'❌'}</span>
                    <span style={{fontWeight:'bold',color:'#334155',minWidth:80}}>{r.name} 様</span>
                    <span style={{color:'#64748b',flex:1,minWidth:0,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{r.office||'—'}　{r.to}</span>
                    {!r.ok && <span style={{color:'#dc2626',fontSize:11}}>{r.err}</span>}
                  </div>
                ))}
              </div>
              <div style={{textAlign:'right',marginTop:14}}>
                <button disabled={autoFax.running} onClick={()=>setAutoFax(null)} style={{background:autoFax.running?'#cbd5e1':'#6366f1',border:'none',color:'white',borderRadius:8,padding:'9px 20px',fontWeight:'bold',fontSize:13,cursor:autoFax.running?'wait':'pointer'}}>{autoFax.running?'送信中…':'閉じる'}</button>
              </div>
            </div>
          </div>
        );
      })()}

      {_monthLocked && (
        <div className="no-print" style={{flexShrink:0,background:'#fffbeb',borderBottom:'1px solid #fde68a',color:'#92400e',padding:'8px 16px',fontSize:12,fontWeight:'bold',display:'flex',alignItems:'center',gap:8}}>
          ⏳ 当月（{tM}月）分のモニタリングは<strong>毎月15日以降</strong>に作成・AI下書き・記入ができます（AIコスト管理のため）。過去月はいつでも編集できます。
        </div>
      )}
      <div className="no-print" style={{flexShrink:0,background:_aiRemaining>0?'#eff6ff':'#fef2f2',borderBottom:`1px solid ${_aiRemaining>0?'#bfdbfe':'#fecaca'}`,color:_aiRemaining>0?'#1e40af':'#b91c1c',padding:'6px 16px',fontSize:12,display:'flex',alignItems:'center',gap:8}}>
        今月のAI下書き：<strong>残り{_aiRemaining}回</strong>（上限{_aiLimit}回＝利用者{_aiActiveCount}名＋3回／{_aiUsed}回使用済み）
        {_aiRemaining<=0 && <span style={{fontWeight:'bold'}}>— 上限に達しました。手入力または「一括作成（既定）」でご対応ください。</span>}
      </div>
      {/* テーブル（スクロール可） */}
      <div style={{flex:1,overflow:'auto',padding:'0'}}>
        <div id="print-content-monitoring">
        {(() => {
          const renderRow = (patient, i, isAbsent) => {
            const res = results[patient.id];
            const sheetRec = getSheetRecord(patient.id);
            const confirmed = !!(sheetRec && sheetRec.confirmed);
            const checked = checkedIds.has(patient.id);
            return (
              <tr key={patient.id} style={{borderBottom:'2px solid #cbd5e1',background:confirmed?'#f0fdf4':isAbsent?'#fafafa':i%2===0?'white':'#f8fafc'}}>
                {/* チェック列 */}
                <td style={{padding:'10px 8px',textAlign:'center',verticalAlign:'middle',width:36}}>
                  {!isAbsent && (
                    <input type="checkbox" checked={checked} onChange={()=>toggleCheck(patient.id)}
                      style={{width:16,height:16,cursor:'pointer',accentColor:'#0284c7'}}/>
                  )}
                </td>
                {/* 名前列 */}
                <td style={{padding:'12px 10px',verticalAlign:'middle',borderRight:'1px solid #f1f5f9',width:160,textAlign:'center'}}>
                  <div style={{fontWeight:'bold',fontSize:13,color:isAbsent?'#94a3b8':'#1e293b',display:'flex',alignItems:'center',justifyContent:'center',gap:4}}>
                    {patient.name}
                    {isBdayMonth(patient) && <span title="今月が誕生月" style={{fontSize:14}}>👑</span>}
                  </div>
                  <div style={{fontSize:10,color:'#94a3b8',marginTop:2}}>{patient.careLevel||''}</div>
                </td>
                {/* 内容列 — ★ ①〜⑤を既定表示。 プルダウン変更・本文入力でその場保存。 確定済みは編集不可 */}
                <td style={{padding:'10px 14px',verticalAlign:'middle'}}>
                  {(() => {
                    if (res?.loading) return <div style={{display:'flex',alignItems:'center',gap:8,color:'#0284c7',fontSize:12}}><span style={{fontSize:16}}>⟳</span> AI生成中...</div>;
                    if (res?.error) return <div style={{color:'#dc2626',fontSize:11}}>{res.error}</div>;
                    const persisted = !!(sheetRec && sheetRec.sheet);
                    const sh = persisted ? sheetRec.sheet : getOrInitSheetFor(patient);
                    return (
                      <div style={{fontSize:12,lineHeight:1.5,color:'#1e293b'}}>
                        {!persisted && <div style={{fontSize:10,color:'#94a3b8',marginBottom:4}}>（既定の下書き。プルダウンや本文を変更すると保存されます）</div>}
                        {MON_ITEMS.map((it,ii) => { const c=_monCell(sh[it.key]); const cellId=`${patient.id}:${it.key}`; const editing2 = editTextCell===cellId; const copyId=`${patient.id}:${it.key}`; return (
                          <div key={it.key} style={{marginBottom:6,paddingBottom:6,borderBottom: ii<MON_ITEMS.length-1?'1px dashed #d7e3ec':'none'}}>
                            <div style={{display:'flex',alignItems:'center',gap:6,flexWrap:'wrap',marginBottom:2}}>
                              <span style={{fontWeight:'bold',color:'#0c4a6e',background:'#e0f2fe',borderRadius:5,padding:'1px 7px',fontSize:11}}>{it.no}{it.title}</span>
                              <select value={c.sel} disabled={confirmed} onChange={e=>updateSheetInline(patient, it.key, 'sel', e.target.value)}
                                style={{fontSize:11,fontWeight:'bold',border:'1px solid #7dd3fc',borderRadius:6,padding:'2px 4px',background:confirmed?'#f1f5f9':'white',color:'#0369a1'}}>
                                <option value="">— 選択 —</option>
                                {it.options.map(o=> <option key={o} value={o}>{o}</option>)}
                              </select>
                              <button type="button" title="この項目をコピー" onClick={()=>copyText(copyId, `${it.no}${it.title}：${c.sel}${c.text?` / ${c.text}`:''}`)}
                                style={{background:copiedId===copyId?'#d1fae5':'#f8fafc',border:'1px solid #e2e8f0',color:copiedId===copyId?'#059669':'#94a3b8',borderRadius:6,padding:'2px 6px',fontSize:10,fontWeight:'bold',cursor:'pointer',display:'flex',alignItems:'center',gap:2}}>
                                {copiedId===copyId?'✓':<Copy size={9}/>}
                              </button>
                            </div>
                            {(!confirmed && editing2) ? (
                              <textarea autoFocus defaultValue={c.text} rows={2}
                                onBlur={e=>{ updateSheetInline(patient, it.key, 'text', e.target.value); setEditTextCell(null); }}
                                style={{width:'100%',boxSizing:'border-box',fontSize:12,border:'1px solid #93c5fd',borderRadius:6,padding:'4px 6px',outline:'none',fontFamily:'inherit',resize:'vertical'}}/>
                            ) : (
                              <div onClick={()=>{ if(!confirmed) setEditTextCell(cellId); }} title={confirmed?'確定済み（編集不可）':'クリックで編集'} style={{color:c.text?'#334155':'#cbd5e1',cursor:confirmed?'default':'text',minHeight:16,paddingLeft:2,whiteSpace:'pre-wrap'}}>{c.text || (confirmed?'—':'（タップで内容を入力）')}</div>
                            )}
                          </div>
                        );})}
                        <div style={{fontSize:10,color:'#94a3b8'}}>実施日 {sh.implDate||'—'} / 実施者 {sh.recorder||'—'}</div>
                      </div>
                    );
                  })()}
                </td>
                {/* 操作列（縦並び） */}
                {!isPrintMode && (
                  <td style={{padding:'8px 10px',verticalAlign:'middle',width:150}} className="no-print">
                    <div style={{display:'flex',flexDirection:'column',gap:6,alignItems:'stretch'}}>
                      {!confirmed && (
                        <button type="button" onClick={()=>aiDraftRow(patient)} disabled={res?.loading}
                          style={{background:'#f5f3ff',border:'1px solid #c4b5fd',color:'#6d28d9',borderRadius:8,padding:'6px 8px',fontSize:11,fontWeight:'bold',cursor:'pointer',whiteSpace:'nowrap'}}>
                          {res?.loading ? '⟳ 生成中...' : 'AIで下書き'}
                        </button>
                      )}
                      <button type="button" onClick={()=>toggleConfirm(patient)} title={confirmed?'クリックで確定を解除':'内容を確定します（確定後は編集ロック）'}
                        style={{background:confirmed?'#d1fae5':'#10b981',border:confirmed?'1px solid #6ee7b7':'none',color:confirmed?'#059669':'white',borderRadius:8,padding:'6px 8px',fontSize:11,fontWeight:'bold',cursor:'pointer',whiteSpace:'nowrap'}}>
                        {confirmed ? '✓ 確定済（解除）' : '✓ 確定する'}
                      </button>
                      <button type="button" onClick={()=>{ const s=(sheetRec&&sheetRec.sheet)||getOrInitSheetFor(patient); const txt=MON_ITEMS.map(it=>{const c=_monCell(s[it.key]);return `${it.no}${it.title}：${c.sel}${c.text?` ${c.text}`:''}`;}).join('\n'); copyText(patient.id, txt); }}
                        style={{background:copiedId===patient.id?'#d1fae5':'#f0fdf4',border:`1px solid ${copiedId===patient.id?'#6ee7b7':'#bbf7d0'}`,color:copiedId===patient.id?'#059669':'#10b981',borderRadius:8,padding:'6px 8px',fontSize:11,fontWeight:'bold',cursor:'pointer',display:'flex',alignItems:'center',justifyContent:'center',gap:3,whiteSpace:'nowrap'}}>
                        {copiedId===patient.id ? '✓ コピー済' : <><Copy size={10}/> 全文コピー</>}
                      </button>
                      <button type="button" onClick={()=>faxRowToCareManager(patient)} title={`担当ケアマネ${patient.cmOffice?`（${patient.cmOffice}）`:'（未設定）'}宛てでこの表を出力し、送付履歴に記録します`}
                        style={{background:'#fff7ed',border:'1px solid #fdba74',color:'#c2410c',borderRadius:8,padding:'6px 8px',fontSize:11,fontWeight:'bold',cursor:'pointer',whiteSpace:'nowrap'}}>
                        ケアマネへFAX
                      </button>
                    </div>
                  </td>
                )}
              </tr>
            );
          };

          return (
            <>
              {/* 通所あり */}
              <div style={{background:'white',borderRadius:14,boxShadow:'0 1px 6px rgba(0,0,0,0.08)',border:'1px solid #e2e8f0',marginBottom:16}}>
                <table style={{width:'100%',borderCollapse:'collapse',tableLayout:'fixed'}}>
                  <colgroup><col style={{width:36}}/><col style={{width:160}}/><col/>{!isPrintMode&&<col style={{width:150}}/>}</colgroup>
                  <thead>
                    <tr style={{background:'#0284c7',color:'white'}} className="thp">
                      <th style={{padding:'10px 8px',textAlign:'center',width:36,position:'sticky',top:0,zIndex:20,background:'#0284c7'}}></th>
                      <th style={{padding:'10px 14px',fontWeight:'bold',fontSize:12,textAlign:'center',position:'sticky',top:0,zIndex:20,background:'#0284c7'}}>利用者名</th>
                      <th style={{padding:'10px 14px',fontWeight:'bold',fontSize:12,position:'sticky',top:0,zIndex:20,background:'#0284c7'}}>モニタリング内容</th>
                      {!isPrintMode && <th style={{padding:'10px 14px',textAlign:'center',fontWeight:'bold',fontSize:12,position:'sticky',top:0,zIndex:20,background:'#0284c7'}} className="no-print">操作</th>}
                    </tr>
                  </thead>
                  <tbody>
                    {attendedPats.length === 0
                      ? <tr><td colSpan={4} style={{padding:'24px',textAlign:'center',color:'#94a3b8',fontSize:12}}>対象者なし</td></tr>
                      : attendedPats.map((p,i) => renderRow(p,i,false))
                    }
                  </tbody>
                </table>
              </div>

              {/* 未通所 */}
              {absentPats.length > 0 && (
                <div style={{background:'white',borderRadius:14,boxShadow:'0 1px 4px rgba(0,0,0,0.05)',overflow:'hidden',border:'1px solid #f1f5f9'}}>
                  <div style={{background:'#f8fafc',padding:'8px 16px',fontSize:12,fontWeight:'bold',color:'#94a3b8',borderBottom:'1px solid #f1f5f9'}}>
                    今月の通所なし（{absentPats.length}名）— 必要な場合のみ手入力・生成
                  </div>
                  <table style={{width:'100%',borderCollapse:'collapse',tableLayout:'fixed'}}>
                    <colgroup><col style={{width:36}}/><col style={{width:160}}/><col/>{!isPrintMode&&<col style={{width:150}}/>}</colgroup>
                    <thead>
                      <tr style={{background:'#94a3b8',color:'white'}}>
                        <th style={{padding:'8px',width:36}}></th>
                        <th style={{padding:'8px 14px',textAlign:'left',fontWeight:'bold',fontSize:12}}>利用者名</th>
                        <th style={{padding:'8px 14px',textAlign:'left',fontWeight:'bold',fontSize:12}}>モニタリング内容</th>
                        {!isPrintMode && <th style={{padding:'8px',textAlign:'center',fontWeight:'bold',fontSize:12}} className="no-print">操作</th>}
                      </tr>
                    </thead>
                    <tbody>
                      {absentPats.map((p,i) => renderRow(p,i,true))}
                    </tbody>
                  </table>
                </div>
              )}

              {attendedPats.length === 0 && absentPats.length === 0 && (
                <div style={{textAlign:'center',padding:'40px',color:'#94a3b8',fontSize:13}}>
                  {searchQuery ? `「${searchQuery}」に一致する利用者がいません` : '利用中の利用者がいません'}
                </div>
              )}
            </>
          );
        })()}
        </div>
      </div>{/* end diary-print-content */}

      {/* ★ モニタリング表（正式シート）編集モーダル */}
      {sheetModal && (() => {
        const patient = (appData.patients||[]).find(p => p.id === sheetModal.patientId);
        if (!patient) return null;
        return (
          <MonitoringSheetModal
            patient={patient}
            facility={appData.systemSettings?.facilityInfo || {}}
            period={monthLabelStr}
            record={getSheetRecord(patient.id)}
            autoStatus={buildAutoStatus(patient)}
            autoChange={buildAutoChange(patient)}
            autoSel={buildAutoSel(patient)}
            noAttendance={!hasAttendance(patient)}
            defaultRecorder={getActiveRecorderName() || ''}
            defaultDate={new Date().toISOString().slice(0,10)}
            onClose={()=>setSheetModal(null)}
            onSave={(sheet)=>saveSheet(patient, sheet)}
            onPrint={(sheet, forFax)=>printSheet(patient, sheet, forFax)}
            onAiDraft={()=>aiDraftSheet(patient)}
            hasApiKey={!!(appData.systemSettings?.anthropicApiKey||'').trim()}
          />
        );
      })()}
    </div>
  );
}


// === AbsenceFaxView (休み連絡) ===
// === 介護保険証 / 負担割合証 OCR 取り込みモーダル ===
// Tesseract.js を CDN から動的ロードして日本語 OCR を実行し、フィールドを抽出
function InsuranceOcrModal({ onApply, onClose }) {
  const [file, setFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState('');
  const [running, setRunning] = useState(false);
  const [progress, setProgress] = useState(0);
  const [progressLabel, setProgressLabel] = useState('');
  const [rawText, setRawText] = useState('');
  const [fields, setFields] = useState({});
  const [error, setError] = useState('');
  const fileRef = useRef(null);

  // Tesseract.js CDN ロード (キャッシュ済みなら再ロードしない)
  const loadTesseract = () => new Promise((resolve, reject) => {
    if (window.Tesseract) return resolve(window.Tesseract);
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/tesseract.js@5.0.5/dist/tesseract.min.js';
    script.onload = () => resolve(window.Tesseract);
    script.onerror = () => reject(new Error('Tesseract.js の読み込みに失敗しました。インターネット接続をご確認ください。'));
    document.head.appendChild(script);
  });

  // 和暦 / 西暦 を YYYY-MM-DD に正規化
  const parseDate = (s) => {
    if (!s) return '';
    const m = s.match(/(令和|平成|昭和|明治|大正)?\s*(\d+)\s*年\s*(\d+)\s*月\s*(\d+)\s*日/);
    if (!m) return '';
    let year = parseInt(m[2], 10);
    if (m[1] === '令和') year += 2018;
    else if (m[1] === '平成') year += 1988;
    else if (m[1] === '昭和') year += 1925;
    else if (m[1] === '大正') year += 1911;
    else if (m[1] === '明治') year += 1867;
    else if (year < 100) year += 2000;
    const mm = String(parseInt(m[3], 10)).padStart(2, '0');
    const dd = String(parseInt(m[4], 10)).padStart(2, '0');
    return `${year}-${mm}-${dd}`;
  };

  // OCR テキストから各フィールドを抽出
  const parseFields = (text) => {
    const out = {};
    // 全角を半角に統一して扱う (ただし氏名・住所は元のまま)
    const ascii = text.replace(/[０-９]/g, c => String.fromCharCode(c.charCodeAt(0) - 0xFEE0));

    // 氏名 (氏名 直後のテキスト)
    const nm = text.match(/氏[\s　]*名[\s　]*[:：]?[\s　]*([^\n]+)/);
    if (nm) {
      const name = nm[1].trim().split(/[\s　]+/).slice(0, 2).join(' ');
      if (name && name.length <= 20) out.name = name;
    }

    // 性別
    if (/性[\s　]*別[\s　]*男/.test(text) || /\b男\s*$/m.test(text)) out.gender = '男性';
    else if (/性[\s　]*別[\s　]*女/.test(text) || /\b女\s*$/m.test(text)) out.gender = '女性';

    // 生年月日
    const bm = text.match(/生年月[\s　]*日[\s　]*[:：]?[\s　]*((?:令和|平成|昭和|明治|大正)?[\s　]*\d+[\s　]*年[\s　]*\d+[\s　]*月[\s　]*\d+[\s　]*日)/);
    if (bm) {
      const d = parseDate(bm[1]);
      if (d) out.birthDate = d;
    }

    // 被保険者番号 (10桁数字)
    const ins = ascii.match(/被[\s　]*保[\s　]*険[\s　]*者[\s　]*番[\s　]*号[\s　]*[:：]?[\s　]*(\d{10})/);
    if (ins) out.insuranceNo = ins[1];
    else {
      // フォールバック: 単独の10桁
      const fb = ascii.match(/(?:^|[^\d])(\d{10})(?:[^\d]|$)/);
      if (fb) out.insuranceNo = fb[1];
    }

    // 介護度
    const careLevels = ['要支援1','要支援2','要介護1','要介護2','要介護3','要介護4','要介護5','事業対象者'];
    for (const cl of careLevels) {
      if (text.includes(cl) || text.includes(cl.replace(/(\d)/, c => '１２３４５'[parseInt(c)-1] || c))) {
        out.careLevel = cl;
        break;
      }
    }

    // 認定の有効期間 (2つの日付を期間とみなす)
    // 「認定の有効期間」「認定有効期間」「適用期間」のいずれかを起点に
    const idx = ['認定の有効期間','認定有効期間','適用期間','有効期間'].reduce((found, kw) => {
      if (found !== -1) return found;
      const i = text.indexOf(kw);
      return i !== -1 ? i : -1;
    }, -1);
    if (idx !== -1) {
      const after = text.slice(idx);
      const dates = after.match(/(?:令和|平成|昭和)?[\s　]*\d+[\s　]*年[\s　]*\d+[\s　]*月[\s　]*\d+[\s　]*日/g);
      if (dates && dates.length >= 1) {
        const s = parseDate(dates[0]);
        if (s) out.careLevelFrom = s;
      }
      if (dates && dates.length >= 2) {
        const e = parseDate(dates[1]);
        if (e) out.careLevelTo = e;
      }
    }

    // 住所
    const ad = text.match(/(?:住[\s　]*所|現[\s　]*住[\s　]*所)[\s　]*[:：]?[\s　]*([^\n]+)/);
    if (ad) {
      const addr = ad[1].trim();
      if (addr.length <= 80) out.address = addr;
    }

    // 郵便番号
    const zip = ascii.match(/〒?[\s　]*(\d{3})[\s　-]?(\d{4})/);
    if (zip) out.zipCode = `${zip[1]}-${zip[2]}`;

    // 負担割合 (1割/2割/3割) - 通常 負担割合証に記載
    if (/3[\s　]*割/.test(ascii) || /三[\s　]*割/.test(text)) out.costBurden = '70%';
    else if (/2[\s　]*割/.test(ascii) || /二[\s　]*割/.test(text)) out.costBurden = '80%';
    else if (/1[\s　]*割/.test(ascii) || /一[\s　]*割/.test(text)) out.costBurden = '90%';

    return out;
  };

  const onFileChange = (e) => {
    const f = e.target.files?.[0];
    if (!f) return;
    if (isVideoFile(f)) { alert('動画はアップロードできません（写真・PDFのみ対応）。'); e.target.value=''; return; }
    setFile(f);
    setPreviewUrl(URL.createObjectURL(f));
    setRawText(''); setFields({}); setError(''); setProgress(0);
  };

  const runOcr = async () => {
    if (!file) { setError('画像を選択してください'); return; }
    setRunning(true); setError(''); setProgress(0); setProgressLabel('Tesseract を読み込み中...');
    try {
      const Tesseract = await loadTesseract();
      setProgressLabel('日本語データを読み込み中... (初回は数十秒かかります)');
      const result = await Tesseract.recognize(file, 'jpn', {
        logger: (m) => {
          if (m.status === 'recognizing text') {
            setProgress(Math.round((m.progress || 0) * 100));
            setProgressLabel('文字を認識中...');
          } else if (m.status) {
            setProgressLabel(m.status);
          }
        },
      });
      const text = result?.data?.text || '';
      setRawText(text);
      setFields(parseFields(text));
      setProgressLabel('完了');
    } catch (e) {
      setError(e?.message || 'OCR に失敗しました');
    } finally {
      setRunning(false);
    }
  };

  const fieldLabels = {
    name:'氏名', gender:'性別', birthDate:'生年月日', zipCode:'郵便番号', address:'住所',
    insuranceNo:'被保険者番号', careLevel:'介護度', careLevelFrom:'適用期間（開始）',
    careLevelTo:'適用期間（終了）', costBurden:'負担割合',
  };

  return (
    <div style={{position:'fixed',inset:0,background:'rgba(15,23,42,0.75)',zIndex:10000,display:'flex',alignItems:'center',justifyContent:'center',padding:16}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{background:'white',borderRadius:18,width:'100%',maxWidth:780,maxHeight:'90vh',overflow:'auto',boxShadow:'0 24px 60px rgba(0,0,0,0.4)'}}>
        <div style={{padding:'16px 22px',borderBottom:'1px solid #e2e8f0',display:'flex',alignItems:'center',justifyContent:'space-between',position:'sticky',top:0,background:'white',zIndex:1}}>
          <div className="text-base font-bold text-slate-800 flex items-center gap-2">介護保険証 / 負担割合証 OCR 取り込み</div>
          <button onClick={onClose} className="p-1.5 text-slate-400 hover:bg-slate-100 rounded-full">✕</button>
        </div>
        <div style={{padding:'18px 22px'}}>
          {/* 画像選択 */}
          <div className="bg-slate-50 border border-slate-200 rounded-xl p-3 mb-3">
            <div className="text-xs font-bold text-slate-600 mb-2">1. 介護保険証 / 負担割合証 の写真を選択</div>
            <input ref={fileRef} type="file" accept="image/*,application/pdf" capture="environment" onChange={onFileChange} className="block w-full text-xs"/>
            <div className="text-[10px] text-slate-500 mt-1">※ 紙の上から撮影 (なるべく文字がくっきり映るように)</div>
          </div>

          {previewUrl && (
            <div className="mb-3 text-center">
              <img src={previewUrl} alt="preview" style={{maxWidth:'100%',maxHeight:240,borderRadius:10,border:'1px solid #e2e8f0',background:'#f8fafc'}}/>
            </div>
          )}

          {/* OCR 実行 */}
          <div className="flex gap-2 mb-3">
            <button onClick={runOcr} disabled={!file || running}
              className={`flex-1 px-4 py-2.5 rounded-xl font-bold text-sm shadow ${(!file || running) ? 'bg-slate-300 text-slate-500 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700 text-white'}`}>
              {running ? `読取中... ${progress}%` : 'OCR で読み取る'}
            </button>
          </div>
          {progressLabel && <div className="text-[11px] text-slate-500 mb-2">{progressLabel} {running && progress > 0 && `(${progress}%)`}</div>}

          {error && <div className="bg-red-50 border border-red-200 text-red-700 text-xs font-bold p-2 rounded-lg mb-3">⚠ {error}</div>}

          {/* 抽出フィールド */}
          {Object.keys(fields).length > 0 && (
            <div className="bg-emerald-50 border border-emerald-300 rounded-xl p-3 mb-3">
              <div className="text-xs font-bold text-emerald-800 mb-2">✓ 抽出されたフィールド ({Object.keys(fields).length}件)</div>
              <div className="grid grid-cols-2 gap-2">
                {Object.entries(fieldLabels).map(([k, label]) => {
                  const val = fields[k];
                  if (!val) return null;
                  return (
                    <div key={k} className="bg-white border border-emerald-200 rounded-lg p-2">
                      <div className="text-[10px] font-bold text-emerald-700">{label}</div>
                      <input value={val} onChange={e=>setFields(f=>({...f, [k]: e.target.value}))} className="w-full text-sm font-bold text-slate-800 bg-transparent outline-none"/>
                    </div>
                  );
                })}
              </div>
              <div className="text-[10px] text-emerald-700 mt-2">
                ※ 上の値は手動で修正できます。「✓ 反映」を押すと利用者マスタに上書き保存します。
              </div>
              <button onClick={()=>onApply(fields)} className="mt-2 w-full px-4 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold text-sm shadow">
                ✓ この内容を利用者マスタに反映
              </button>
            </div>
          )}

          {/* 生 OCR テキスト (デバッグ用に表示) */}
          {rawText && (
            <details className="bg-slate-100 rounded-lg p-2">
              <summary className="text-[11px] font-bold text-slate-600 cursor-pointer">OCR の生テキストを見る</summary>
              <pre className="text-[10px] text-slate-700 whitespace-pre-wrap font-mono mt-2 max-h-60 overflow-auto">{rawText}</pre>
            </details>
          )}

          <div className="text-[10px] text-slate-500 mt-3 leading-relaxed bg-amber-50 border border-amber-200 rounded-lg p-2">
            <b>※ プライバシー保護:</b> 画像処理はすべてブラウザ内で実行され、外部サーバーには送信されません。<br/>
            <b>※ 精度について:</b> 印刷された文字は比較的高精度ですが、撮影状態（ピント・光・角度）により失敗する場合があります。抽出後は必ず内容を確認してください。
          </div>
        </div>
      </div>
    </div>
  );
}

// === FAX送付履歴記録モーダル (送信完了後にユーザーが手動で記録) ===
function FaxHistoryRecordModal({ defaultRecord, onSave, onClose }) {
  const [rec, setRec] = useState(defaultRecord || { recipientName:'', recipientFax:'', note:'' });
  return (
    <div style={{position:'fixed',inset:0,background:'rgba(15,23,42,0.7)',zIndex:10000,display:'flex',alignItems:'center',justifyContent:'center',padding:16}} onClick={onClose}>
      <div style={{background:'white',borderRadius:16,maxWidth:480,width:'100%',padding:24,boxShadow:'0 20px 60px rgba(0,0,0,0.3)'}} onClick={e=>e.stopPropagation()}>
        <div style={{fontSize:16,fontWeight:'bold',color:'#1e293b',marginBottom:6}}>送付履歴に記録</div>
        <div style={{fontSize:11,color:'#64748b',marginBottom:14}}>送付先・FAX番号などを入力して履歴に残します（後で確認できます）</div>
        <div style={{display:'flex',flexDirection:'column',gap:10}}>
          <div>
            <label style={{display:'block',fontSize:11,fontWeight:'bold',color:'#475569',marginBottom:4}}>送付先名 (任意)</label>
            <input value={rec.recipientName} onChange={e=>setRec({...rec,recipientName:e.target.value})} placeholder="例: ○○ケアプランセンター 田中様"
              className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg text-sm outline-none"/>
          </div>
          <div>
            <label style={{display:'block',fontSize:11,fontWeight:'bold',color:'#475569',marginBottom:4}}>FAX番号 (任意)</label>
            <input value={rec.recipientFax} onChange={e=>setRec({...rec,recipientFax:e.target.value})} placeholder="例: 03-1234-5678"
              className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg text-sm outline-none font-mono"/>
          </div>
          <div>
            <label style={{display:'block',fontSize:11,fontWeight:'bold',color:'#475569',marginBottom:4}}>備考 (任意)</label>
            <input value={rec.note} onChange={e=>setRec({...rec,note:e.target.value})} placeholder="例: 至急、再送など"
              className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg text-sm outline-none"/>
          </div>
        </div>
        <div style={{display:'flex',gap:10,marginTop:18}}>
          <button onClick={onClose} className="flex-1 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg font-bold text-sm">キャンセル</button>
          <button onClick={()=>{ onSave(rec); onClose(); }} className="flex-1 py-2.5 bg-violet-600 hover:bg-violet-700 text-white rounded-lg font-bold text-sm">記録する</button>
        </div>
      </div>
    </div>
  );
}

// === FAX送付履歴一覧モーダル ===
function FaxHistoryListModal({ history, typeLabel, onDelete, onClose }) {
  const [search, setSearch] = useState('');
  const filtered = (history||[]).filter(h => {
    if (!search.trim()) return true;
    const q = search.toLowerCase();
    return (h.recipientName||'').toLowerCase().includes(q)
      || (h.recipientFax||'').includes(q)
      || (h.subject||'').toLowerCase().includes(q)
      || (h.patientName||'').includes(q)
      || (h.note||'').includes(q);
  }).sort((a,b) => (b.timestamp||'').localeCompare(a.timestamp||''));
  return (
    <div style={{position:'fixed',inset:0,background:'rgba(15,23,42,0.7)',zIndex:10000,display:'flex',alignItems:'center',justifyContent:'center',padding:16}} onClick={onClose}>
      <div style={{background:'white',borderRadius:16,maxWidth:720,width:'100%',maxHeight:'85vh',display:'flex',flexDirection:'column',boxShadow:'0 20px 60px rgba(0,0,0,0.3)'}} onClick={e=>e.stopPropagation()}>
        <div style={{padding:'16px 20px',background:'linear-gradient(135deg,#7c3aed,#a855f7)',color:'white',display:'flex',alignItems:'center',justifyContent:'space-between',borderRadius:'16px 16px 0 0'}}>
          <div>
            <div style={{fontSize:16,fontWeight:'bold'}}>{typeLabel}の送付履歴</div>
            <div style={{fontSize:11,opacity:0.85}}>{filtered.length}件 / 全{(history||[]).length}件</div>
          </div>
          <button onClick={onClose} style={{background:'rgba(255,255,255,0.2)',border:'none',color:'white',width:30,height:30,borderRadius:'50%',cursor:'pointer',fontSize:16}}>✕</button>
        </div>
        <div style={{padding:'12px 20px',borderBottom:'1px solid #e2e8f0'}}>
          <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="送付先・FAX番号・利用者名で検索"
            className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg text-sm outline-none"/>
        </div>
        <div style={{flex:1,overflow:'auto',padding:'8px 0'}}>
          {filtered.length === 0 ? (
            <div style={{padding:'40px 20px',textAlign:'center',color:'#94a3b8',fontSize:13}}>
              {history && history.length > 0 ? '該当する履歴がありません' : '送付履歴はまだありません'}
            </div>
          ) : (
            filtered.map(h => (
              <div key={h.id} style={{padding:'12px 20px',borderBottom:'1px solid #f1f5f9',display:'flex',gap:12,alignItems:'flex-start'}}>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:4,flexWrap:'wrap'}}>
                    <span style={{fontSize:11,fontWeight:'bold',color:'#1e293b',background:'#f1f5f9',padding:'2px 6px',borderRadius:4}}>
                      {h.timestamp ? new Date(h.timestamp).toLocaleString('ja-JP',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}) : '—'}
                    </span>
                    {h.patientName && <span style={{fontSize:11,fontWeight:'bold',color:'#1e40af',background:'#dbeafe',padding:'2px 6px',borderRadius:4}}>{h.patientName}</span>}
                  </div>
                  <div style={{fontSize:13,fontWeight:'bold',color:'#1e293b',marginBottom:2}}>件名: {h.subject || '（件名なし）'}</div>
                  <div style={{fontSize:12,color:'#475569'}}>
                    {(h.recipientName || h.recipientFax) ? (
                      <>宛先: <b>{h.recipientName||'(名前なし)'}</b>{h.recipientFax && <span style={{fontFamily:'Menlo,monospace',marginLeft:6,color:'#7c3aed'}}>{h.recipientFax}</span>}</>
                    ) : (
                      <span style={{color:'#94a3b8',fontStyle:'italic'}}>宛先情報なし</span>
                    )}
                  </div>
                  {h.memo && <div style={{fontSize:12,color:'#334155',marginTop:3,whiteSpace:'pre-wrap'}}>{String(h.memo).slice(0,120)}{String(h.memo).length>120?'…':''}</div>}
                  {h.note && <div style={{fontSize:11,color:'#64748b',marginTop:3,fontStyle:'italic'}}>{h.note}</div>}
                </div>
                <button onClick={()=>{ if(window.confirm('この履歴を削除しますか?')) onDelete(h.id); }} className="text-slate-300 hover:text-red-500 text-sm"></button>
              </div>
            ))
          )}
        </div>
        <div style={{padding:'10px 20px',background:'#f8fafc',borderRadius:'0 0 16px 16px',fontSize:10,color:'#64748b',textAlign:'center'}}>
          ※ 履歴はあくまで送付の記録です。実際の送信は複合機で行われます
        </div>
      </div>
    </div>
  );
}

